    ('stdlib/ast.py', 54, 62, 'literal_eval', 'def literal_eval(node_or_string):\n    """\n    Evaluate an expression node or a string containing only a Python\n    expression.  The string or node provided may only consist of the following\n    Python literal structures: strings, bytes, numbers, tuples, lists, dicts,\n    sets, booleans, and None.\n\n    Caution: A complex expression can overflow the C stack and cause a crash.\n    """\n'),
    ('stdlib/ast.py', 113, 124, 'dump', 'def dump(node, annotate_fields=True, include_attributes=False, *, indent=None):\n    """\n    Return a formatted dump of the tree in node.  This is mainly useful for\n    debugging purposes.  If annotate_fields is true (by default),\n    the returned string will show the names and the values for fields.\n    If annotate_fields is false, the result string will be more compact by\n    omitting unambiguous field names.  Attributes such as line\n    numbers and column offsets are not dumped by default.  If this is wanted,\n    include_attributes can be set to true.  If indent is a non-negative\n    integer or string, then the tree will be pretty-printed with that indent\n    level. None (the default) selects the single line representation.\n    """\n'),
    ('stdlib/ast.py', 180, 184, 'copy_location', 'def copy_location(new_node, old_node):\n    """\n    Copy source location (`lineno`, `col_offset`, `end_lineno`, and `end_col_offset`\n    attributes) from *old_node* to *new_node* if possible, and return *new_node*.\n    """\n'),
    ('stdlib/ast.py', 197, 204, 'fix_missing_locations', 'def fix_missing_locations(node):\n    """\n    When you compile a node tree with compile(), the compiler expects lineno and\n    col_offset attributes for every node that supports them.  This is rather\n    tedious to fill in for generated nodes, so this helper adds these attributes\n    recursively where not already set, by setting them to the values of the\n    parent node.  It works recursively starting at *node*.\n    """\n'),
    ('stdlib/ast.py', 232, 237, 'increment_lineno', 'def increment_lineno(node, n=1):\n    """\n    Increment the line number and end line number of each node in the tree\n    starting at *node* by *n*. This is useful to "move code" to a different\n    location in a file.\n    """\n'),
