    ('stdlib/base64.py', 51, 57, 'b64encode', 'def b64encode(s, altchars=None):\n    """Encode the bytes-like object s using Base64 and return a bytes object.\n\n    Optional altchars should be a byte string of length 2 which specifies an\n    alternative alphabet for the \'+\' and \'/\' characters.  This allows an\n    application to e.g. generate url or filesystem safe Base64 strings.\n    """\n'),
    ('stdlib/base64.py', 65, 79, 'b64decode', 'def b64decode(s, altchars=None, validate=False):\n    """Decode the Base64 encoded bytes-like object or ASCII string s.\n\n    Optional altchars must be a bytes-like object or ASCII string of length 2\n    which specifies the alternative alphabet used instead of the \'+\' and \'/\'\n    characters.\n\n    The result is returned as a bytes object.  A binascii.Error is raised if\n    s is incorrectly padded.\n\n    If validate is False (the default), characters that are neither in the\n    normal base-64 alphabet nor the alternative alphabet are discarded prior\n    to the padding check.  If validate is True, these non-alphabet characters\n    in the input result in a binascii.Error.\n    """\n'),
    ('stdlib/base64.py', 90, 94, 'standard_b64encode', 'def standard_b64encode(s):\n    """Encode bytes-like object s using the standard Base64 alphabet.\n\n    The result is returned as a bytes object.\n    """\n'),
    ('stdlib/base64.py', 97, 104, 'standard_b64decode', 'def standard_b64decode(s):\n    """Decode bytes encoded with the standard Base64 alphabet.\n\n    Argument s is a bytes-like object or ASCII string to decode.  The result\n    is returned as a bytes object.  A binascii.Error is raised if the input\n    is incorrectly padded.  Characters that are not in the standard alphabet\n    are discarded prior to the padding check.\n    """\n'),
    ('stdlib/base64.py', 111, 117, 'urlsafe_b64encode', 'def urlsafe_b64encode(s):\n    """Encode bytes using the URL- and filesystem-safe Base64 alphabet.\n\n    Argument s is a bytes-like object to encode.  The result is returned as a\n    bytes object.  The alphabet uses \'-\' instead of \'+\' and \'_\' instead of\n    \'/\'.\n    """\n'),
    ('stdlib/base64.py', 120, 130, 'urlsafe_b64decode', 'def urlsafe_b64decode(s):\n    """Decode bytes using the URL- and filesystem-safe Base64 alphabet.\n\n    Argument s is a bytes-like object or ASCII string to decode.  The result\n    is returned as a bytes object.  A binascii.Error is raised if the input\n    is incorrectly padded.  Characters that are not in the URL-safe base-64\n    alphabet, and are not a plus \'+\' or slash \'/\', are discarded prior to the\n    padding check.\n\n    The alphabet uses \'-\' instead of \'+\' and \'_\' instead of \'/\'.\n    """\n'),
    ('stdlib/base64.py', 248, 248, 'b32encode', 'def b32encode(s):\n'),
    ('stdlib/base64.py', 252, 252, 'b32decode', 'def b32decode(s, casefold=False, map01=None):\n'),
    ('stdlib/base64.py', 257, 257, 'b32hexencode', 'def b32hexencode(s):\n'),
    ('stdlib/base64.py', 261, 262, 'b32hexdecode', 'def b32hexdecode(s, casefold=False):\n    # base32hex does not have the 01 mapping\n'),
    ('stdlib/base64.py', 271, 273, 'b16encode', 'def b16encode(s):\n    """Encode the bytes-like object s using Base16 and return a bytes object.\n    """\n'),
    ('stdlib/base64.py', 277, 286, 'b16decode', 'def b16decode(s, casefold=False):\n    """Decode the Base16 encoded bytes-like object or ASCII string s.\n\n    Optional casefold is a flag specifying whether a lowercase alphabet is\n    acceptable as input.  For security purposes, the default is False.\n\n    The result is returned as a bytes object.  A binascii.Error is raised if\n    s is incorrectly padded or if there are non-alphabet characters present\n    in the input.\n    """\n'),
    ('stdlib/base64.py', 327, 343, 'a85encode', 'def a85encode(b, *, foldspaces=False, wrapcol=0, pad=False, adobe=False):\n    """Encode bytes-like object b using Ascii85 and return a bytes object.\n\n    foldspaces is an optional flag that uses the special short sequence \'y\'\n    instead of 4 consecutive spaces (ASCII 0x20) as supported by \'btoa\'. This\n    feature is not supported by the "standard" Adobe encoding.\n\n    wrapcol controls whether the output should have newline (b\'\\\\n\') characters\n    added to it. If this is non-zero, each output line will be at most this\n    many characters long.\n\n    pad controls whether the input is padded to a multiple of 4 before\n    encoding. Note that the btoa implementation always pads.\n\n    adobe controls whether the encoded byte sequence is framed with <~ and ~>,\n    which is used by the Adobe implementation.\n    """\n'),
    ('stdlib/base64.py', 368, 383, 'a85decode', 'def a85decode(b, *, foldspaces=False, adobe=False, ignorechars=b\' \\t\\n\\r\\v\'):\n    """Decode the Ascii85 encoded bytes-like object or ASCII string b.\n\n    foldspaces is a flag that specifies whether the \'y\' short sequence should be\n    accepted as shorthand for 4 consecutive spaces (ASCII 0x20). This feature is\n    not supported by the "standard" Adobe encoding.\n\n    adobe controls whether the input sequence is in Adobe Ascii85 format (i.e.\n    is framed with <~ and ~>).\n\n    ignorechars should be a byte string containing characters to ignore from the\n    input. This should only contain whitespace characters, and by default\n    contains all whitespace characters in ASCII.\n\n    The result is returned as a bytes object.\n    """\n'),
    ('stdlib/base64.py', 446, 451, 'b85encode', 'def b85encode(b, pad=False):\n    """Encode bytes-like object b in base85 format and return a bytes object.\n\n    If pad is true, the input is padded with b\'\\\\0\' so its length is a multiple of\n    4 bytes before encoding.\n    """\n'),
    ('stdlib/base64.py', 460, 464, 'b85decode', 'def b85decode(b):\n    """Decode the base85-encoded bytes-like object or ASCII string b\n\n    The result is returned as a bytes object.\n    """\n'),
    ('stdlib/base64.py', 508, 509, 'encode', 'def encode(input, output):\n    """Encode a file; input and output are binary files."""\n'),
    ('stdlib/base64.py', 523, 524, 'decode', 'def decode(input, output):\n    """Decode a file; input and output are binary files."""\n'),
    ('stdlib/base64.py', 548, 550, 'encodebytes', 'def encodebytes(s):\n    """Encode a bytestring into a bytes object containing multiple lines\n    of base-64 data."""\n'),
    ('stdlib/base64.py', 559, 560, 'decodebytes', 'def decodebytes(s):\n    """Decode a bytestring of base-64 data into a bytes object."""\n'),
    ('stdlib/base64.py', 566, 567, 'main', 'def main():\n    """Small main program"""\n'),
    ('stdlib/base64.py', 592, 592, 'test', 'def test():\n'),
    ('stdlib/bdb.py', 650, 651, 'set_trace', 'def set_trace():\n    """Start debugging with a Bdb instance from the caller\'s frame."""\n'),
    ('stdlib/bdb.py', 777, 784, 'checkfuncname', 'def checkfuncname(b, frame):\n    """Return True if break should happen here.\n\n    Whether a break should happen depends on the way that b (the breakpoint)\n    was set.  If it was set via line number, check if b.line is the same as\n    the one in the frame.  If it was set via function name, check if this is\n    the right function and if it is on the first executable line.\n    """\n'),
    ('stdlib/bdb.py', 809, 821, 'effective', 'def effective(file, line, frame):\n    """Return (active breakpoint, delete temporary flag) or (None, None) as\n       breakpoint to act upon.\n\n       The "active breakpoint" is the first entry in bplist[line, file] (which\n       must exist) that is enabled, for which checkfuncname is True, and that\n       has neither a False condition nor a positive ignore count.  The flag,\n       meaning that a temporary breakpoint should be deleted, is False only\n       when the condiion cannot be evaluated (in which case, ignore count is\n       ignored).\n\n       If no such entry exists, then (None, None) is returned.\n    """\n'),
    ('stdlib/bdb.py', 880, 880, 'foo', 'def foo(n):\n'),
    ('stdlib/bdb.py', 885, 885, 'bar', 'def bar(a):\n'),
    ('stdlib/bdb.py', 889, 889, 'test', 'def test():\n'),
    ('stdlib/binhex.py', 59, 59, 'getfileinfo', 'def getfileinfo(name):\n'),
    ('stdlib/binhex.py', 253, 254, 'binhex', 'def binhex(inp, out):\n    """binhex(infilename, outfilename): create binhex-encoded copy of a file"""\n'),
    ('stdlib/binhex.py', 477, 478, 'hexbin', 'def hexbin(inp, out):\n    """hexbin(infilename, outfilename) - Decode binhexed file"""\n'),
    ('stdlib/bisect.py', 4, 11, 'insort_right', 'def insort_right(a, x, lo=0, hi=None, *, key=None):\n    """Insert item x in list a, and keep it sorted assuming a is sorted.\n\n    If x is already in a, insert it to the right of the rightmost x.\n\n    Optional args lo (default 0) and hi (default len(a)) bound the\n    slice of a to be searched.\n    """\n'),
    ('stdlib/bisect.py', 19, 28, 'bisect_right', 'def bisect_right(a, x, lo=0, hi=None, *, key=None):\n    """Return the index where to insert item x in list a, assuming a is sorted.\n\n    The return value i is such that all e in a[:i] have e <= x, and all e in\n    a[i:] have e > x.  So if x already appears in the list, a.insert(i, x) will\n    insert just after the rightmost x already there.\n\n    Optional args lo (default 0) and hi (default len(a)) bound the\n    slice of a to be searched.\n    """\n'),
    ('stdlib/bisect.py', 53, 60, 'insort_left', 'def insort_left(a, x, lo=0, hi=None, *, key=None):\n    """Insert item x in list a, and keep it sorted assuming a is sorted.\n\n    If x is already in a, insert it to the left of the leftmost x.\n\n    Optional args lo (default 0) and hi (default len(a)) bound the\n    slice of a to be searched.\n    """\n'),
    ('stdlib/bisect.py', 68, 77, 'bisect_left', 'def bisect_left(a, x, lo=0, hi=None, *, key=None):\n    """Return the index where to insert item x in list a, assuming a is sorted.\n\n    The return value i is such that all e in a[:i] have e < x, and all e in\n    a[i:] have e >= x.  So if x already appears in the list, a.insert(i, x) will\n    insert just before the leftmost x already there.\n\n    Optional args lo (default 0) and hi (default len(a)) bound the\n    slice of a to be searched.\n    """\n'),
    ('stdlib/bz2.py', 271, 291, 'open', 'def open(filename, mode="rb", compresslevel=9,\n         encoding=None, errors=None, newline=None):\n    """Open a bzip2-compressed file in binary or text mode.\n\n    The filename argument can be an actual filename (a str, bytes, or\n    PathLike object), or an existing file object to read from or write\n    to.\n\n    The mode argument can be "r", "rb", "w", "wb", "x", "xb", "a" or\n    "ab" for binary mode, or "rt", "wt", "xt" or "at" for text mode.\n    The default mode is "rb", and the default compresslevel is 9.\n\n    For binary mode, this function is equivalent to the BZ2File\n    constructor: BZ2File(filename, mode, compresslevel). In this case,\n    the encoding, errors and newline arguments must not be provided.\n\n    For text mode, a BZ2File object is created, and wrapped in an\n    io.TextIOWrapper instance with the specified encoding, error\n    handling behavior, and line ending(s).\n\n    """\n'),
    ('stdlib/bz2.py', 313, 319, 'compress', 'def compress(data, compresslevel=9):\n    """Compress a block of data.\n\n    compresslevel, if given, must be a number between 1 and 9.\n\n    For incremental compression, use a BZ2Compressor object instead.\n    """\n'),
    ('stdlib/bz2.py', 324, 328, 'decompress', 'def decompress(data):\n    """Decompress a block of data.\n\n    For incremental decompression, use a BZ2Decompressor object instead.\n    """\n'),
