    ('stdlib/calendar.py', 107, 109, 'leapdays', 'def leapdays(y1, y2):\n    """Return number of leap years in range [y1, y2).\n       Assume y1 <= y2."""\n'),
    ('stdlib/calendar.py', 115, 116, 'weekday', 'def weekday(year, month, day):\n    """Return weekday (0-6 ~ Mon-Sun) for year, month (1-12), day (1-31)."""\n'),
    ('stdlib/calendar.py', 122, 124, 'monthrange', 'def monthrange(year, month):\n    """Return weekday (0-6 ~ Mon-Sun) and number of days (28-31) for\n       year, month."""\n'),
    ('stdlib/calendar.py', 609, 609, 'setfirstweekday', 'def setfirstweekday(firstweekday):\n'),
    ('stdlib/calendar.py', 629, 630, 'format', 'def format(cols, colwidth=_colwidth, spacing=_spacing):\n    """Prints multi-column formatting for year calendars"""\n'),
    ('stdlib/calendar.py', 634, 635, 'formatstring', 'def formatstring(cols, colwidth=_colwidth, spacing=_spacing):\n    """Returns a string formatted from n strings, centered within n columns."""\n'),
    ('stdlib/calendar.py', 644, 645, 'timegm', 'def timegm(tuple):\n    """Unrelated but handy function to calculate Unix timestamp from GMT."""\n'),
    ('stdlib/calendar.py', 654, 654, 'main', 'def main(args):\n'),
    ('stdlib/cgi.py', 57, 79, 'initlog', 'def initlog(*allargs):\n    """Write a log message, if there is a log file.\n\n    Even though this function is called initlog(), you should always\n    use log(); log is a variable that is set either to initlog\n    (initially), to dolog (once the log file has been opened), or to\n    nolog (when logging is disabled).\n\n    The first argument is a format string; the remaining arguments (if\n    any) are arguments to the % operator, so e.g.\n        log("%s: %s", "a", "b")\n    will write "a: b" to the log file, followed by a newline.\n\n    If the global logfp is not None, it should be a file object to\n    which log data is written.\n\n    If the global logfp is None, the global logfile may be a string\n    giving a filename to open, in append mode.  This file should be\n    world writable!!!  If the file can\'t be opened, logging is\n    silently disabled (since there is no safe place where we could\n    send an error message).\n\n    """\n'),
    ('stdlib/cgi.py', 94, 95, 'dolog', 'def dolog(fmt, *args):\n    """Write a log message to the log file.  See initlog() for docs."""\n'),
    ('stdlib/cgi.py', 98, 99, 'nolog', 'def nolog(*allargs):\n    """Dummy function, assigned to log when logging is disabled."""\n'),
    ('stdlib/cgi.py', 102, 103, 'closelog', 'def closelog():\n    """Close the log file."""\n'),
    ('stdlib/cgi.py', 121, 144, 'parse', 'def parse(fp=None, environ=os.environ, keep_blank_values=0,\n          strict_parsing=0, separator=\'&\'):\n    """Parse a query in the environment or from a file (default stdin)\n\n        Arguments, all optional:\n\n        fp              : file pointer; default: sys.stdin.buffer\n\n        environ         : environment dictionary; default: os.environ\n\n        keep_blank_values: flag indicating whether blank values in\n            percent-encoded forms should be treated as blank strings.\n            A true value indicates that blanks should be retained as\n            blank strings.  The default false value indicates that\n            blank values are to be ignored and treated as if they were\n            not included.\n\n        strict_parsing: flag indicating what to do with parsing errors.\n            If false (the default), errors are silently ignored.\n            If true, errors raise a ValueError exception.\n\n        separator: str. The symbol to use for separating the query arguments.\n            Defaults to &.\n    """\n'),
    ('stdlib/cgi.py', 191, 203, 'parse_multipart', 'def parse_multipart(fp, pdict, encoding="utf-8", errors="replace", separator=\'&\'):\n    """Parse multipart input.\n\n    Arguments:\n    fp   : input file\n    pdict: dictionary containing other parameters of content-type header\n    encoding, errors: request encoding and error handler, passed to\n        FieldStorage\n\n    Returns a dictionary just like parse_qs(): keys are the field names, each\n    value is a list of values for that field. For non-file fields, the value\n    is a list of strings.\n    """\n'),
    ('stdlib/cgi.py', 230, 235, 'parse_header', 'def parse_header(line):\n    """Parse a Content-type like header.\n\n    Return the main content-type and a dictionary of options.\n\n    """\n'),
    ('stdlib/cgi.py', 845, 851, 'test', 'def test(environ=os.environ):\n    """Robust test CGI script, usable as main program.\n\n    Write minimal HTTP headers and dump all information provided to\n    the script in HTML form.\n\n    """\n'),
    ('stdlib/cgi.py', 884, 884, 'print_exception', 'def print_exception(type=None, value=None, tb=None, limit=None):\n'),
    ('stdlib/cgi.py', 898, 899, 'print_environ', 'def print_environ(environ=os.environ):\n    """Dump the shell environment as HTML."""\n'),
    ('stdlib/cgi.py', 909, 910, 'print_form', 'def print_form(form):\n    """Dump the contents of a form as HTML."""\n'),
    ('stdlib/cgi.py', 925, 926, 'print_directory', 'def print_directory():\n    """Dump the current directory as HTML."""\n'),
    ('stdlib/cgi.py', 937, 937, 'print_arguments', 'def print_arguments():\n'),
    ('stdlib/cgi.py', 944, 945, 'print_environ_usage', 'def print_environ_usage():\n    """Dump a list of environment variables used by CGI as HTML."""\n'),
    ('stdlib/cgi.py', 991, 991, 'valid_boundary', 'def valid_boundary(s):\n'),
    ('stdlib/cgitb.py', 35, 36, 'reset', 'def reset():\n    """Return a string that resets the CGI and browser to a known state."""\n'),
    ('stdlib/cgitb.py', 46, 46, 'small', 'def small(text):\n'),
    ('stdlib/cgitb.py', 52, 52, 'strong', 'def strong(text):\n'),
    ('stdlib/cgitb.py', 58, 58, 'grey', 'def grey(text):\n'),
    ('stdlib/cgitb.py', 64, 65, 'lookup', 'def lookup(name, frame, locals):\n    """Find the value for a given name in the given environment."""\n'),
    ('stdlib/cgitb.py', 80, 81, 'scanvars', 'def scanvars(reader, frame, locals):\n    """Scan one logical line of Python and look up values of variables used."""\n'),
    ('stdlib/cgitb.py', 101, 102, 'html', 'def html(einfo, context=5):\n    """Return a nice HTML document describing a given traceback."""\n'),
    ('stdlib/cgitb.py', 192, 193, 'text', 'def text(einfo, context=5):\n    """Return a plain text document describing a given traceback."""\n'),
    ('stdlib/cgitb.py', 314, 319, 'enable', 'def enable(display=1, logdir=None, context=5, format="html"):\n    """Install an exception handler that formats tracebacks as HTML.\n\n    The optional argument \'display\' can be set to 0 to suppress sending the\n    traceback to the browser, and \'logdir\' can be set to a directory to cause\n    tracebacks to be written to files there."""\n'),
    ('stdlib/code.py', 278, 292, 'interact', 'def interact(banner=None, readfunc=None, local=None, exitmsg=None):\n    """Closely emulate the interactive Python interpreter.\n\n    This is a backwards compatible interface to the InteractiveConsole\n    class.  When readfunc is not specified, it attempts to import the\n    readline module to enable GNU readline if it is available.\n\n    Arguments (all optional, all default to None):\n\n    banner -- passed to InteractiveConsole.interact()\n    readfunc -- if not None, replaces InteractiveConsole.raw_input()\n    local -- passed to InteractiveInterpreter.__init__()\n    exitmsg -- passed to InteractiveConsole.interact()\n\n    """\n'),
    ('stdlib/codecs.py', 871, 901, 'open', 'def open(filename, mode=\'r\', encoding=None, errors=\'strict\', buffering=-1):\n\n    """ Open an encoded file using the given mode and return\n        a wrapped version providing transparent encoding/decoding.\n\n        Note: The wrapped version will only accept the object format\n        defined by the codecs, i.e. Unicode objects for most builtin\n        codecs. Output is also codec dependent and will usually be\n        Unicode as well.\n\n        If encoding is not None, then the\n        underlying encoded files are always opened in binary mode.\n        The default file mode is \'r\', meaning to open the file in read mode.\n\n        encoding specifies the encoding which is to be used for the\n        file.\n\n        errors may be given to define the error handling. It defaults\n        to \'strict\' which causes ValueErrors to be raised in case an\n        encoding error occurs.\n\n        buffering has the same meaning as for the builtin open() API.\n        It defaults to -1 which means that the default buffer size will\n        be used.\n\n        The returned wrapped file object provides an extra attribute\n        .encoding which allows querying the used encoding. This\n        attribute is only available if an encoding was specified as\n        parameter.\n\n    """\n'),
    ('stdlib/codecs.py', 920, 944, 'EncodedFile', 'def EncodedFile(file, data_encoding, file_encoding=None, errors=\'strict\'):\n\n    """ Return a wrapped version of file which provides transparent\n        encoding translation.\n\n        Data written to the wrapped file is decoded according\n        to the given data_encoding and then encoded to the underlying\n        file using file_encoding. The intermediate data type\n        will usually be Unicode but depends on the specified codecs.\n\n        Bytes read from the file are decoded using file_encoding and then\n        passed back to the caller encoded using data_encoding.\n\n        If file_encoding is not given, it defaults to data_encoding.\n\n        errors may be given to define the error handling. It defaults\n        to \'strict\' which causes ValueErrors to be raised in case an\n        encoding error occurs.\n\n        The returned wrapped file object provides two extra attributes\n        .data_encoding and .file_encoding which reflect the given\n        parameters of the same name. The attributes can be used for\n        introspection by Python programs.\n\n    """\n'),
    ('stdlib/codecs.py', 958, 965, 'getencoder', 'def getencoder(encoding):\n\n    """ Lookup up the codec for the given encoding and return\n        its encoder function.\n\n        Raises a LookupError in case the encoding cannot be found.\n\n    """\n'),
    ('stdlib/codecs.py', 968, 975, 'getdecoder', 'def getdecoder(encoding):\n\n    """ Lookup up the codec for the given encoding and return\n        its decoder function.\n\n        Raises a LookupError in case the encoding cannot be found.\n\n    """\n'),
    ('stdlib/codecs.py', 978, 986, 'getincrementalencoder', 'def getincrementalencoder(encoding):\n\n    """ Lookup up the codec for the given encoding and return\n        its IncrementalEncoder class or factory function.\n\n        Raises a LookupError in case the encoding cannot be found\n        or the codecs doesn\'t provide an incremental encoder.\n\n    """\n'),
    ('stdlib/codecs.py', 992, 1000, 'getincrementaldecoder', 'def getincrementaldecoder(encoding):\n\n    """ Lookup up the codec for the given encoding and return\n        its IncrementalDecoder class or factory function.\n\n        Raises a LookupError in case the encoding cannot be found\n        or the codecs doesn\'t provide an incremental decoder.\n\n    """\n'),
    ('stdlib/codecs.py', 1006, 1013, 'getreader', 'def getreader(encoding):\n\n    """ Lookup up the codec for the given encoding and return\n        its StreamReader class or factory function.\n\n        Raises a LookupError in case the encoding cannot be found.\n\n    """\n'),
    ('stdlib/codecs.py', 1016, 1023, 'getwriter', 'def getwriter(encoding):\n\n    """ Lookup up the codec for the given encoding and return\n        its StreamWriter class or factory function.\n\n        Raises a LookupError in case the encoding cannot be found.\n\n    """\n'),
    ('stdlib/codecs.py', 1026, 1034, 'iterencode', 'def iterencode(iterator, encoding, errors=\'strict\', **kwargs):\n    """\n    Encoding iterator.\n\n    Encodes the input strings from the iterator using an IncrementalEncoder.\n\n    errors and kwargs are passed through to the IncrementalEncoder\n    constructor.\n    """\n'),
    ('stdlib/codecs.py', 1044, 1052, 'iterdecode', 'def iterdecode(iterator, encoding, errors=\'strict\', **kwargs):\n    """\n    Decoding iterator.\n\n    Decodes the input strings from the iterator using an IncrementalDecoder.\n\n    errors and kwargs are passed through to the IncrementalDecoder\n    constructor.\n    """\n'),
    ('stdlib/codecs.py', 1064, 1071, 'make_identity_dict', 'def make_identity_dict(rng):\n\n    """ make_identity_dict(rng) -> dict\n\n        Return a dictionary where elements of the rng sequence are\n        mapped to themselves.\n\n    """\n'),
    ('stdlib/codecs.py', 1074, 1086, 'make_encoding_map', 'def make_encoding_map(decoding_map):\n\n    """ Creates an encoding map from a decoding map.\n\n        If a target mapping in the decoding map occurs multiple\n        times, then that target is mapped to None (undefined mapping),\n        causing an exception when encountered by the charmap codec\n        during translation.\n\n        One example where this happens is cp875.py which decodes\n        multiple character to \\\\u001a.\n\n    """\n'),
    ('stdlib/codeop.py', 88, 106, 'compile_command', 'def compile_command(source, filename="<input>", symbol="single"):\n    r"""Compile a command and determine whether it is incomplete.\n\n    Arguments:\n\n    source -- the source string; may contain \\n characters\n    filename -- optional filename from which source was read; default\n                "<input>"\n    symbol -- optional grammar start symbol; "single" (default), "exec"\n              or "eval"\n\n    Return value / exceptions raised:\n\n    - Return a code object if the command is complete and valid\n    - Return None if the command is incomplete\n    - Raise SyntaxError, ValueError or OverflowError if the command is a\n      syntax error (OverflowError and ValueError can be produced by\n      malformed literals).\n    """\n'),
    ('stdlib/colorsys.py', 40, 40, 'rgb_to_yiq', 'def rgb_to_yiq(r, g, b):\n'),
    ('stdlib/colorsys.py', 46, 50, 'yiq_to_rgb', 'def yiq_to_rgb(y, i, q):\n    # r = y + (0.27*q + 0.41*i) / (0.74*0.41 + 0.27*0.48)\n    # b = y + (0.74*q - 0.48*i) / (0.74*0.41 + 0.27*0.48)\n    # g = y - (0.30*(r-y) + 0.11*(b-y)) / 0.59\n\n'),
    ('stdlib/colorsys.py', 75, 75, 'rgb_to_hls', 'def rgb_to_hls(r, g, b):\n'),
    ('stdlib/colorsys.py', 99, 99, 'hls_to_rgb', 'def hls_to_rgb(h, l, s):\n'),
    ('stdlib/colorsys.py', 125, 125, 'rgb_to_hsv', 'def rgb_to_hsv(r, g, b):\n'),
    ('stdlib/colorsys.py', 144, 144, 'hsv_to_rgb', 'def hsv_to_rgb(h, s, v):\n'),
    ('stdlib/compileall.py', 48, 75, 'compile_dir', 'def compile_dir(dir, maxlevels=None, ddir=None, force=False,\n                rx=None, quiet=0, legacy=False, optimize=-1, workers=1,\n                invalidation_mode=None, *, stripdir=None,\n                prependdir=None, limit_sl_dest=None, hardlink_dupes=False):\n    """Byte-compile all modules in the given directory tree.\n\n    Arguments (only dir is required):\n\n    dir:       the directory to byte-compile\n    maxlevels: maximum recursion level (default `sys.getrecursionlimit()`)\n    ddir:      the directory that will be prepended to the path to the\n               file as it is compiled into each byte-code file.\n    force:     if True, force compilation, even if timestamps are up-to-date\n    quiet:     full output with False or 0, errors only with 1,\n               no output with 2\n    legacy:    if True, produce legacy pyc paths instead of PEP 3147 paths\n    optimize:  int or list of optimization levels or -1 for level of\n               the interpreter. Multiple levels leads to multiple compiled\n               files each with one optimization level.\n    workers:   maximum number of parallel workers\n    invalidation_mode: how the up-to-dateness of the pyc will be checked\n    stripdir:  part of path to left-strip from source file path\n    prependdir: path to prepend to beginning of original file path, applied\n               after stripdir\n    limit_sl_dest: ignore symlinks if they are pointing outside of\n                   the defined path\n    hardlink_dupes: hardlink duplicated pyc files\n    """\n'),
    ('stdlib/compileall.py', 125, 150, 'compile_file', 'def compile_file(fullname, ddir=None, force=False, rx=None, quiet=0,\n                 legacy=False, optimize=-1,\n                 invalidation_mode=None, *, stripdir=None, prependdir=None,\n                 limit_sl_dest=None, hardlink_dupes=False):\n    """Byte-compile one file.\n\n    Arguments (only fullname is required):\n\n    fullname:  the file to byte-compile\n    ddir:      if given, the directory name compiled in to the\n               byte-code file.\n    force:     if True, force compilation, even if timestamps are up-to-date\n    quiet:     full output with False or 0, errors only with 1,\n               no output with 2\n    legacy:    if True, produce legacy pyc paths instead of PEP 3147 paths\n    optimize:  int or list of optimization levels or -1 for level of\n               the interpreter. Multiple levels leads to multiple compiled\n               files each with one optimization level.\n    invalidation_mode: how the up-to-dateness of the pyc will be checked\n    stripdir:  part of path to left-strip from source file path\n    prependdir: path to prepend to beginning of original file path, applied\n               after stripdir\n    limit_sl_dest: ignore symlinks if they are pointing outside of\n                   the defined path.\n    hardlink_dupes: hardlink duplicated pyc files\n    """\n'),
    ('stdlib/compileall.py', 274, 288, 'compile_path', 'def compile_path(skip_curdir=1, maxlevels=0, force=False, quiet=0,\n                 legacy=False, optimize=-1,\n                 invalidation_mode=None):\n    """Byte-compile all module on sys.path.\n\n    Arguments (all optional):\n\n    skip_curdir: if true, skip current directory (default True)\n    maxlevels:   max recursion level (default 0)\n    force: as for compile_dir() (default False)\n    quiet: as for compile_dir() (default 0)\n    legacy: as for compile_dir() (default False)\n    optimize: as for compile_dir() (default -1)\n    invalidation_mode: as for compiler_dir()\n    """\n'),
    ('stdlib/compileall.py', 308, 309, 'main', 'def main():\n    """Script main program."""\n'),
    ('stdlib/contextlib.py', 252, 278, 'contextmanager', 'def contextmanager(func):\n    """@contextmanager decorator.\n\n    Typical usage:\n\n        @contextmanager\n        def some_generator(<arguments>):\n            <setup>\n            try:\n                yield <value>\n            finally:\n                <cleanup>\n\n    This makes this:\n\n        with some_generator(<arguments>) as <variable>:\n            <body>\n\n    equivalent to this:\n\n        <setup>\n        try:\n            <variable> = <value>\n            <body>\n        finally:\n            <cleanup>\n    """\n'),
    ('stdlib/contextlib.py', 285, 311, 'asynccontextmanager', 'def asynccontextmanager(func):\n    """@asynccontextmanager decorator.\n\n    Typical usage:\n\n        @asynccontextmanager\n        async def some_async_generator(<arguments>):\n            <setup>\n            try:\n                yield <value>\n            finally:\n                <cleanup>\n\n    This makes this:\n\n        async with some_async_generator(<arguments>) as <variable>:\n            <body>\n\n    equivalent to this:\n\n        <setup>\n        try:\n            <variable> = <value>\n            <body>\n        finally:\n            <cleanup>\n    """\n'),
    ('stdlib/copy.py', 66, 70, 'copy', 'def copy(x):\n    """Shallow copy operation on arbitrary Python objects.\n\n    See the module\'s __doc__ string for more info.\n    """\n'),
    ('stdlib/copy.py', 128, 132, 'deepcopy', 'def deepcopy(x, memo=None, _nil=[]):\n    """Deep copy operation on arbitrary Python objects.\n\n    See the module\'s __doc__ string for more info.\n    """\n'),
    ('stdlib/copyreg.py', 12, 12, 'pickle', 'def pickle(ob_type, pickle_function, constructor_ob=None):\n'),
    ('stdlib/copyreg.py', 22, 22, 'constructor', 'def constructor(object):\n'),
    ('stdlib/copyreg.py', 39, 39, 'pickle_union', 'def pickle_union(obj):\n'),
    ('stdlib/copyreg.py', 175, 176, 'add_extension', 'def add_extension(module, name, code):\n    """Register an extension code."""\n'),
    ('stdlib/copyreg.py', 193, 194, 'remove_extension', 'def remove_extension(module, name, code):\n    """Unregister an extension code.  For testing only."""\n'),
    ('stdlib/copyreg.py', 205, 205, 'clear_extension_cache', 'def clear_extension_cache():\n'),
    ('stdlib/crypt.py', 32, 37, 'mksalt', 'def mksalt(method=None, *, rounds=None):\n    """Generate a salt for the specified method.\n\n    If not specified, the strongest available method will be used.\n\n    """\n'),
    ('stdlib/crypt.py', 70, 79, 'crypt', 'def crypt(word, salt=None):\n    """Return a string representing the one-way hash of a password, with a salt\n    prepended.\n\n    If ``salt`` is not specified or is ``None``, the strongest\n    available method will be selected and a salt generated.  Otherwise,\n    ``salt`` may be one of the ``crypt.METHOD_*`` values, or a string as\n    returned by ``crypt.mksalt()``.\n\n    """\n'),
    ('stdlib/dataclasses.py', 367, 383, 'field', 'def field(*, default=MISSING, default_factory=MISSING, init=True, repr=True,\n          hash=None, compare=True, metadata=None, kw_only=MISSING):\n    """Return an object to identify dataclass fields.\n\n    default is the default value of the field.  default_factory is a\n    0-argument function called to initialize a field\'s value.  If init\n    is true, the field will be a parameter to the class\'s __init__()\n    function.  If repr is true, the field will be included in the\n    object\'s repr().  If hash is true, the field will be included in the\n    object\'s hash().  If compare is true, the field will be used in\n    comparison functions.  metadata, if specified, must be a mapping\n    which is stored but not otherwise examined by dataclass.  If kw_only\n    is true, the field will become a keyword-only parameter to\n    __init__().\n\n    It is an error to specify both default and default_factory.\n    """\n'),
    ('stdlib/dataclasses.py', 1156, 1172, 'dataclass', 'def dataclass(cls=None, /, *, init=True, repr=True, eq=True, order=False,\n              unsafe_hash=False, frozen=False, match_args=True,\n              kw_only=False, slots=False):\n    """Returns the same class as was passed in, with dunder methods\n    added based on the fields defined in the class.\n\n    Examines PEP 526 __annotations__ to determine fields.\n\n    If init is true, an __init__() method is added to the class. If\n    repr is true, a __repr__() method is added. If order is true, rich\n    comparison dunder methods are added. If unsafe_hash is true, a\n    __hash__() method function is added. If frozen is true, fields may\n    not be assigned to after instance creation. If match_args is true,\n    the __match_args__ tuple is added. If kw_only is true, then by\n    default all fields are keyword-only. If slots is true, an\n    __slots__ attribute is added.\n    """\n'),
    ('stdlib/dataclasses.py', 1187, 1192, 'fields', 'def fields(class_or_instance):\n    """Return a tuple describing the fields of this dataclass.\n\n    Accepts a dataclass or an instance of one. Tuple elements are of\n    type Field.\n    """\n'),
    ('stdlib/dataclasses.py', 1210, 1212, 'is_dataclass', 'def is_dataclass(obj):\n    """Returns True if obj is a dataclass or an instance of a\n    dataclass."""\n'),
    ('stdlib/dataclasses.py', 1217, 1235, 'asdict', 'def asdict(obj, *, dict_factory=dict):\n    """Return the fields of a dataclass instance as a new dictionary mapping\n    field names to field values.\n\n    Example usage:\n\n      @dataclass\n      class C:\n          x: int\n          y: int\n\n      c = C(1, 2)\n      assert asdict(c) == {\'x\': 1, \'y\': 2}\n\n    If given, \'dict_factory\' will be used instead of built-in dict.\n    The function applies recursively to field values that are\n    dataclass instances. This will also look into built-in containers:\n    tuples, lists, and dicts.\n    """\n'),
    ('stdlib/dataclasses.py', 1282, 1299, 'astuple', 'def astuple(obj, *, tuple_factory=tuple):\n    """Return the fields of a dataclass instance as a new tuple of field values.\n\n    Example usage::\n\n      @dataclass\n      class C:\n          x: int\n          y: int\n\n    c = C(1, 2)\n    assert astuple(c) == (1, 2)\n\n    If given, \'tuple_factory\' will be used instead of built-in tuple.\n    The function applies recursively to field values that are\n    dataclass instances. This will also look into built-in containers:\n    tuples, lists, and dicts.\n    """\n'),
    ('stdlib/dataclasses.py', 1333, 1357, 'make_dataclass', 'def make_dataclass(cls_name, fields, *, bases=(), namespace=None, init=True,\n                   repr=True, eq=True, order=False, unsafe_hash=False,\n                   frozen=False, match_args=True, kw_only=False, slots=False):\n    """Return a new dynamically created dataclass.\n\n    The dataclass name will be \'cls_name\'.  \'fields\' is an iterable\n    of either (name), (name, type) or (name, type, Field) objects. If type is\n    omitted, use the string \'typing.Any\'.  Field objects are created by\n    the equivalent of calling \'field(name, type [, Field-info])\'.\n\n      C = make_dataclass(\'C\', [\'x\', (\'y\', int), (\'z\', int, field(init=False))], bases=(Base,))\n\n    is equivalent to:\n\n      @dataclass\n      class C(Base):\n          x: \'typing.Any\'\n          y: int\n          z: int = field(init=False)\n\n    For the bases and namespace parameters, see the builtin type() function.\n\n    The parameters init, repr, eq, order, unsafe_hash, and frozen are passed to\n    dataclass().\n    """\n'),
    ('stdlib/dataclasses.py', 1405, 1418, 'replace', 'def replace(obj, /, **changes):\n    """Return a new object replacing specified fields with new values.\n\n    This is especially useful for frozen classes.  Example usage:\n\n      @dataclass(frozen=True)\n      class C:\n          x: int\n          y: int\n\n      c = C(1, 2)\n      c1 = replace(c, x=3)\n      assert c1.x == 3 and c1.y == 2\n      """\n'),
    ('stdlib/difflib.py', 666, 693, 'get_close_matches', 'def get_close_matches(word, possibilities, n=3, cutoff=0.6):\n    """Use SequenceMatcher to return list of the best "good enough" matches.\n\n    word is a sequence for which close matches are desired (typically a\n    string).\n\n    possibilities is a list of sequences against which to match word\n    (typically a list of strings).\n\n    Optional arg n (default 3) is the maximum number of close matches to\n    return.  n must be > 0.\n\n    Optional arg cutoff (default 0.6) is a float in [0, 1].  Possibilities\n    that don\'t score at least that similar to word are ignored.\n\n    The best (no more than n) matches among the possibilities are returned\n    in a list, sorted by similarity score, most similar first.\n\n    >>> get_close_matches("appel", ["ape", "apple", "peach", "puppy"])\n    [\'apple\', \'ape\']\n    >>> import keyword as _keyword\n    >>> get_close_matches("wheel", _keyword.kwlist)\n    [\'while\']\n    >>> get_close_matches("Apple", _keyword.kwlist)\n    []\n    >>> get_close_matches("accept", _keyword.kwlist)\n    [\'except\']\n    """\n'),
    ('stdlib/difflib.py', 1045, 1057, 'IS_LINE_JUNK', 'def IS_LINE_JUNK(line, pat=re.compile(r"\\s*(?:#\\s*)?$").match):\n    r"""\n    Return True for ignorable line: iff `line` is blank or contains a single \'#\'.\n\n    Examples:\n\n    >>> IS_LINE_JUNK(\'\\n\')\n    True\n    >>> IS_LINE_JUNK(\'  #   \\n\')\n    True\n    >>> IS_LINE_JUNK(\'hello\\n\')\n    False\n    """\n'),
    ('stdlib/difflib.py', 1061, 1075, 'IS_CHARACTER_JUNK', 'def IS_CHARACTER_JUNK(ch, ws=" \\t"):\n    r"""\n    Return True for ignorable character: iff `ch` is a space or tab.\n\n    Examples:\n\n    >>> IS_CHARACTER_JUNK(\' \')\n    True\n    >>> IS_CHARACTER_JUNK(\'\\t\')\n    True\n    >>> IS_CHARACTER_JUNK(\'\\n\')\n    False\n    >>> IS_CHARACTER_JUNK(\'x\')\n    False\n    """\n'),
    ('stdlib/difflib.py', 1095, 1134, 'unified_diff', 'def unified_diff(a, b, fromfile=\'\', tofile=\'\', fromfiledate=\'\',\n                 tofiledate=\'\', n=3, lineterm=\'\\n\'):\n    r"""\n    Compare two sequences of lines; generate the delta as a unified diff.\n\n    Unified diffs are a compact way of showing line changes and a few\n    lines of context.  The number of context lines is set by \'n\' which\n    defaults to three.\n\n    By default, the diff control lines (those with ---, +++, or @@) are\n    created with a trailing newline.  This is helpful so that inputs\n    created from file.readlines() result in diffs that are suitable for\n    file.writelines() since both the inputs and outputs have trailing\n    newlines.\n\n    For inputs that do not have trailing newlines, set the lineterm\n    argument to "" so that the output will be uniformly newline free.\n\n    The unidiff format normally has a header for filenames and modification\n    times.  Any or all of these may be specified using strings for\n    \'fromfile\', \'tofile\', \'fromfiledate\', and \'tofiledate\'.\n    The modification times are normally expressed in the ISO 8601 format.\n\n    Example:\n\n    >>> for line in unified_diff(\'one two three four\'.split(),\n    ...             \'zero one tree four\'.split(), \'Original\', \'Current\',\n    ...             \'2005-01-26 23:30:50\', \'2010-04-02 10:20:52\',\n    ...             lineterm=\'\'):\n    ...     print(line)                 # doctest: +NORMALIZE_WHITESPACE\n    --- Original        2005-01-26 23:30:50\n    +++ Current         2010-04-02 10:20:52\n    @@ -1,4 +1,4 @@\n    +zero\n     one\n    -two\n    -three\n    +tree\n     four\n    """\n'),
    ('stdlib/difflib.py', 1180, 1222, 'context_diff', 'def context_diff(a, b, fromfile=\'\', tofile=\'\',\n                 fromfiledate=\'\', tofiledate=\'\', n=3, lineterm=\'\\n\'):\n    r"""\n    Compare two sequences of lines; generate the delta as a context diff.\n\n    Context diffs are a compact way of showing line changes and a few\n    lines of context.  The number of context lines is set by \'n\' which\n    defaults to three.\n\n    By default, the diff control lines (those with *** or ---) are\n    created with a trailing newline.  This is helpful so that inputs\n    created from file.readlines() result in diffs that are suitable for\n    file.writelines() since both the inputs and outputs have trailing\n    newlines.\n\n    For inputs that do not have trailing newlines, set the lineterm\n    argument to "" so that the output will be uniformly newline free.\n\n    The context diff format normally has a header for filenames and\n    modification times.  Any or all of these may be specified using\n    strings for \'fromfile\', \'tofile\', \'fromfiledate\', and \'tofiledate\'.\n    The modification times are normally expressed in the ISO 8601 format.\n    If not specified, the strings default to blanks.\n\n    Example:\n\n    >>> print(\'\'.join(context_diff(\'one\\ntwo\\nthree\\nfour\\n\'.splitlines(True),\n    ...       \'zero\\none\\ntree\\nfour\\n\'.splitlines(True), \'Original\', \'Current\')),\n    ...       end="")\n    *** Original\n    --- Current\n    ***************\n    *** 1,4 ****\n      one\n    ! two\n    ! three\n      four\n    --- 1,4 ----\n    + zero\n      one\n    ! tree\n      four\n    """\n'),
    ('stdlib/difflib.py', 1273, 1283, 'diff_bytes', 'def diff_bytes(dfunc, a, b, fromfile=b\'\', tofile=b\'\',\n               fromfiledate=b\'\', tofiledate=b\'\', n=3, lineterm=b\'\\n\'):\n    r"""\n    Compare `a` and `b`, two sequences of lines represented as bytes rather\n    than str. This is a wrapper for `dfunc`, which is typically either\n    unified_diff() or context_diff(). Inputs are losslessly converted to\n    strings so that `dfunc` only has to worry about strings, and encoded\n    back to bytes on return. This is necessary to compare files with\n    unknown or inconsistent encoding. All other inputs (except `n`) must be\n    bytes rather than str.\n    """\n'),
    ('stdlib/difflib.py', 1303, 1337, 'ndiff', 'def ndiff(a, b, linejunk=None, charjunk=IS_CHARACTER_JUNK):\n    r"""\n    Compare `a` and `b` (lists of strings); return a `Differ`-style delta.\n\n    Optional keyword parameters `linejunk` and `charjunk` are for filter\n    functions, or can be None:\n\n    - linejunk: A function that should accept a single string argument and\n      return true iff the string is junk.  The default is None, and is\n      recommended; the underlying SequenceMatcher class has an adaptive\n      notion of "noise" lines.\n\n    - charjunk: A function that accepts a character (string of length\n      1), and returns true iff the character is junk. The default is\n      the module-level function IS_CHARACTER_JUNK, which filters out\n      whitespace characters (a blank or tab; note: it\'s a bad idea to\n      include newline in this!).\n\n    Tools/scripts/ndiff.py is a command-line front-end to this function.\n\n    Example:\n\n    >>> diff = ndiff(\'one\\ntwo\\nthree\\n\'.splitlines(keepends=True),\n    ...              \'ore\\ntree\\nemu\\n\'.splitlines(keepends=True))\n    >>> print(\'\'.join(diff), end="")\n    - one\n    ?  ^\n    + ore\n    ?  ^\n    - two\n    - three\n    ?  -\n    + tree\n    + emu\n    """\n'),
    ('stdlib/difflib.py', 2019, 2040, 'restore', 'def restore(delta, which):\n    r"""\n    Generate one of the two sequences that generated a delta.\n\n    Given a `delta` produced by `Differ.compare()` or `ndiff()`, extract\n    lines originating from file 1 or 2 (parameter `which`), stripping off line\n    prefixes.\n\n    Examples:\n\n    >>> diff = ndiff(\'one\\ntwo\\nthree\\n\'.splitlines(keepends=True),\n    ...              \'ore\\ntree\\nemu\\n\'.splitlines(keepends=True))\n    >>> diff = list(diff)\n    >>> print(\'\'.join(restore(diff, 1)), end="")\n    one\n    two\n    three\n    >>> print(\'\'.join(restore(diff, 2)), end="")\n    ore\n    tree\n    emu\n    """\n'),
    ('stdlib/dis.py', 43, 51, 'dis', 'def dis(x=None, *, file=None, depth=None):\n    """Disassemble classes, methods, functions, and other compiled objects.\n\n    With no argument, disassemble the last traceback.\n\n    Compiled objects currently include generator objects, async generator\n    objects, and coroutine objects, all of which store their code object\n    in a special attribute.\n    """\n'),
    ('stdlib/dis.py', 88, 89, 'distb', 'def distb(tb=None, *, file=None):\n    """Disassemble a traceback (default: last traceback)."""\n'),
    ('stdlib/dis.py', 114, 115, 'pretty_flags', 'def pretty_flags(flags):\n    """Return pretty representation of code flags."""\n'),
    ('stdlib/dis.py', 151, 152, 'code_info', 'def code_info(x):\n    """Formatted details of methods, functions, or code."""\n'),
    ('stdlib/dis.py', 187, 191, 'show_code', 'def show_code(co, *, file=None):\n    """Print details of methods, functions, or code to *file*.\n\n    If *file* is not provided, the output is printed on stdout.\n    """\n'),
    ('stdlib/dis.py', 261, 271, 'get_instructions', 'def get_instructions(x, *, first_line=None):\n    """Iterator for the opcodes in methods, functions or code\n\n    Generates a series of Instruction named tuples giving the details of\n    each operations in the supplied code.\n\n    If *first_line* is not None, it indicates the line number that should\n    be reported for the first source line in the disassembled code.\n    Otherwise, the source line information (if any) is taken directly from\n    the disassembled code object.\n    """\n'),
    ('stdlib/dis.py', 368, 369, 'disassemble', 'def disassemble(co, lasti=-1, *, file=None):\n    """Disassemble a code object."""\n'),
    ('stdlib/dis.py', 434, 439, 'findlabels', 'def findlabels(code):\n    """Detect all offsets in a byte code which are jump targets.\n\n    Return the list of offsets.\n\n    """\n'),
    ('stdlib/dis.py', 453, 457, 'findlinestarts', 'def findlinestarts(code):\n    """Find the offsets in a byte code which are start of lines in the source.\n\n    Generate pairs (offset, lineno)\n    """\n'),
    ('stdlib/doctest.py', 132, 133, 'register_optionflag', 'def register_optionflag(name):\n    # Create a new flag unless `name` is already known.\n'),
    ('stdlib/doctest.py', 1878, 1943, 'testmod', 'def testmod(m=None, name=None, globs=None, verbose=None,\n            report=True, optionflags=0, extraglobs=None,\n            raise_on_error=False, exclude_empty=False):\n    """m=None, name=None, globs=None, verbose=None, report=True,\n       optionflags=0, extraglobs=None, raise_on_error=False,\n       exclude_empty=False\n\n    Test examples in docstrings in functions and classes reachable\n    from module m (or the current module if m is not supplied), starting\n    with m.__doc__.\n\n    Also test examples reachable from dict m.__test__ if it exists and is\n    not None.  m.__test__ maps names to functions, classes and strings;\n    function and class docstrings are tested even if the name is private;\n    strings are tested directly, as if they were docstrings.\n\n    Return (#failures, #tests).\n\n    See help(doctest) for an overview.\n\n    Optional keyword arg "name" gives the name of the module; by default\n    use m.__name__.\n\n    Optional keyword arg "globs" gives a dict to be used as the globals\n    when executing examples; by default, use m.__dict__.  A copy of this\n    dict is actually used for each docstring, so that each docstring\'s\n    examples start with a clean slate.\n\n    Optional keyword arg "extraglobs" gives a dictionary that should be\n    merged into the globals that are used to execute examples.  By\n    default, no extra globals are used.  This is new in 2.4.\n\n    Optional keyword arg "verbose" prints lots of stuff if true, prints\n    only failures if false; by default, it\'s true iff "-v" is in sys.argv.\n\n    Optional keyword arg "report" prints a summary at the end when true,\n    else prints nothing at the end.  In verbose mode, the summary is\n    detailed, else very brief (in fact, empty if all tests passed).\n\n    Optional keyword arg "optionflags" or\'s together module constants,\n    and defaults to 0.  This is new in 2.3.  Possible values (see the\n    docs for details):\n\n        DONT_ACCEPT_TRUE_FOR_1\n        DONT_ACCEPT_BLANKLINE\n        NORMALIZE_WHITESPACE\n        ELLIPSIS\n        SKIP\n        IGNORE_EXCEPTION_DETAIL\n        REPORT_UDIFF\n        REPORT_CDIFF\n        REPORT_NDIFF\n        REPORT_ONLY_FIRST_FAILURE\n\n    Optional keyword arg "raise_on_error" raises an exception on the\n    first unexpected exception or failure. This allows failures to be\n    post-mortem debugged.\n\n    Advanced tomfoolery:  testmod runs methods of a local instance of\n    class doctest.Tester, then merges the results into (or creates)\n    global Tester instance doctest.master.  Methods of doctest.master\n    can be called directly too, if you want to do something unusual.\n    Passing report=0 to testmod is especially useful then, to delay\n    displaying a summary.  Invoke doctest.master.summarize(verbose)\n    when you\'re done fiddling.\n    """\n'),
    ('stdlib/doctest.py', 1982, 2061, 'testfile', 'def testfile(filename, module_relative=True, name=None, package=None,\n             globs=None, verbose=None, report=True, optionflags=0,\n             extraglobs=None, raise_on_error=False, parser=DocTestParser(),\n             encoding=None):\n    """\n    Test examples in the given file.  Return (#failures, #tests).\n\n    Optional keyword arg "module_relative" specifies how filenames\n    should be interpreted:\n\n      - If "module_relative" is True (the default), then "filename"\n         specifies a module-relative path.  By default, this path is\n         relative to the calling module\'s directory; but if the\n         "package" argument is specified, then it is relative to that\n         package.  To ensure os-independence, "filename" should use\n         "/" characters to separate path segments, and should not\n         be an absolute path (i.e., it may not begin with "/").\n\n      - If "module_relative" is False, then "filename" specifies an\n        os-specific path.  The path may be absolute or relative (to\n        the current working directory).\n\n    Optional keyword arg "name" gives the name of the test; by default\n    use the file\'s basename.\n\n    Optional keyword argument "package" is a Python package or the\n    name of a Python package whose directory should be used as the\n    base directory for a module relative filename.  If no package is\n    specified, then the calling module\'s directory is used as the base\n    directory for module relative filenames.  It is an error to\n    specify "package" if "module_relative" is False.\n\n    Optional keyword arg "globs" gives a dict to be used as the globals\n    when executing examples; by default, use {}.  A copy of this dict\n    is actually used for each docstring, so that each docstring\'s\n    examples start with a clean slate.\n\n    Optional keyword arg "extraglobs" gives a dictionary that should be\n    merged into the globals that are used to execute examples.  By\n    default, no extra globals are used.\n\n    Optional keyword arg "verbose" prints lots of stuff if true, prints\n    only failures if false; by default, it\'s true iff "-v" is in sys.argv.\n\n    Optional keyword arg "report" prints a summary at the end when true,\n    else prints nothing at the end.  In verbose mode, the summary is\n    detailed, else very brief (in fact, empty if all tests passed).\n\n    Optional keyword arg "optionflags" or\'s together module constants,\n    and defaults to 0.  Possible values (see the docs for details):\n\n        DONT_ACCEPT_TRUE_FOR_1\n        DONT_ACCEPT_BLANKLINE\n        NORMALIZE_WHITESPACE\n        ELLIPSIS\n        SKIP\n        IGNORE_EXCEPTION_DETAIL\n        REPORT_UDIFF\n        REPORT_CDIFF\n        REPORT_NDIFF\n        REPORT_ONLY_FIRST_FAILURE\n\n    Optional keyword arg "raise_on_error" raises an exception on the\n    first unexpected exception or failure. This allows failures to be\n    post-mortem debugged.\n\n    Optional keyword arg "parser" specifies a DocTestParser (or\n    subclass) that should be used to extract tests from the files.\n\n    Optional keyword arg "encoding" specifies an encoding that should\n    be used to convert the file to unicode.\n\n    Advanced tomfoolery:  testmod runs methods of a local instance of\n    class doctest.Tester, then merges the results into (or creates)\n    global Tester instance doctest.master.  Methods of doctest.master\n    can be called directly too, if you want to do something unusual.\n    Passing report=0 to testmod is especially useful then, to delay\n    displaying a summary.  Invoke doctest.master.summarize(verbose)\n    when you\'re done fiddling.\n    """\n'),
    ('stdlib/doctest.py', 2105, 2121, 'run_docstring_examples', 'def run_docstring_examples(f, globs, verbose=False, name="NoName",\n                           compileflags=None, optionflags=0):\n    """\n    Test examples in the given object\'s docstring (`f`), using `globs`\n    as globals.  Optional argument `name` is used in failure messages.\n    If the optional argument `verbose` is true, then generate output\n    even if there are no failures.\n\n    `compileflags` gives the set of flags that should be used by the\n    Python compiler when running the examples.  If not specified, then\n    it will default to the set of future-import flags that apply to\n    `globs`.\n\n    Optional keyword arg `optionflags` specifies options for the\n    testing and output.  See the documentation for `testmod` for more\n    information.\n    """\n'),
    ('stdlib/doctest.py', 2134, 2160, 'set_unittest_reportflags', 'def set_unittest_reportflags(flags):\n    """Sets the unittest option flags.\n\n    The old flag is returned so that a runner could restore the old\n    value if it wished to:\n\n      >>> import doctest\n      >>> old = doctest._unittest_reportflags\n      >>> doctest.set_unittest_reportflags(REPORT_NDIFF |\n      ...                          REPORT_ONLY_FIRST_FAILURE) == old\n      True\n\n      >>> doctest._unittest_reportflags == (REPORT_NDIFF |\n      ...                                   REPORT_ONLY_FIRST_FAILURE)\n      True\n\n    Only reporting flags can be set:\n\n      >>> doctest.set_unittest_reportflags(ELLIPSIS)\n      Traceback (most recent call last):\n      ...\n      ValueError: (\'Only reporting flags allowed\', 8)\n\n      >>> doctest.set_unittest_reportflags(old) == (REPORT_NDIFF |\n      ...                                   REPORT_ONLY_FIRST_FAILURE)\n      True\n    """\n'),
    ('stdlib/doctest.py', 2356, 2391, 'DocTestSuite', 'def DocTestSuite(module=None, globs=None, extraglobs=None, test_finder=None,\n                 **options):\n    """\n    Convert doctest tests for a module to a unittest test suite.\n\n    This converts each documentation string in a module that\n    contains doctest tests to a unittest test case.  If any of the\n    tests in a doc string fail, then the test case fails.  An exception\n    is raised showing the name of the file containing the test and a\n    (sometimes approximate) line number.\n\n    The `module` argument provides the module to be tested.  The argument\n    can be either a module or a module name.\n\n    If no argument is given, the calling module is used.\n\n    A number of options may be provided as keyword arguments:\n\n    setUp\n      A set-up function.  This is called before running the\n      tests in each file. The setUp function will be passed a DocTest\n      object.  The setUp function can access the test globals as the\n      globs attribute of the test passed.\n\n    tearDown\n      A tear-down function.  This is called after running the\n      tests in each file.  The tearDown function will be passed a DocTest\n      object.  The tearDown function can access the test globals as the\n      globs attribute of the test passed.\n\n    globs\n      A dictionary containing initial global variables for the tests.\n\n    optionflags\n       A set of doctest option flags expressed as an integer.\n    """\n'),
    ('stdlib/doctest.py', 2433, 2435, 'DocFileTest', 'def DocFileTest(path, module_relative=True, package=None,\n                globs=None, parser=DocTestParser(),\n                encoding=None, **options):\n'),
    ('stdlib/doctest.py', 2459, 2514, 'DocFileSuite', 'def DocFileSuite(*paths, **kw):\n    """A unittest suite for one or more doctest files.\n\n    The path to each doctest file is given as a string; the\n    interpretation of that string depends on the keyword argument\n    "module_relative".\n\n    A number of options may be provided as keyword arguments:\n\n    module_relative\n      If "module_relative" is True, then the given file paths are\n      interpreted as os-independent module-relative paths.  By\n      default, these paths are relative to the calling module\'s\n      directory; but if the "package" argument is specified, then\n      they are relative to that package.  To ensure os-independence,\n      "filename" should use "/" characters to separate path\n      segments, and may not be an absolute path (i.e., it may not\n      begin with "/").\n\n      If "module_relative" is False, then the given file paths are\n      interpreted as os-specific paths.  These paths may be absolute\n      or relative (to the current working directory).\n\n    package\n      A Python package or the name of a Python package whose directory\n      should be used as the base directory for module relative paths.\n      If "package" is not specified, then the calling module\'s\n      directory is used as the base directory for module relative\n      filenames.  It is an error to specify "package" if\n      "module_relative" is False.\n\n    setUp\n      A set-up function.  This is called before running the\n      tests in each file. The setUp function will be passed a DocTest\n      object.  The setUp function can access the test globals as the\n      globs attribute of the test passed.\n\n    tearDown\n      A tear-down function.  This is called after running the\n      tests in each file.  The tearDown function will be passed a DocTest\n      object.  The tearDown function can access the test globals as the\n      globs attribute of the test passed.\n\n    globs\n      A dictionary containing initial global variables for the tests.\n\n    optionflags\n      A set of doctest option flags expressed as an integer.\n\n    parser\n      A DocTestParser (or subclass) that should be used to extract\n      tests from the files.\n\n    encoding\n      An encoding that will be used to convert the files to unicode.\n    """\n'),
    ('stdlib/doctest.py', 2532, 2589, 'script_from_examples', 'def script_from_examples(s):\n    r"""Extract script from text with examples.\n\n       Converts text with examples to a Python script.  Example input is\n       converted to regular code.  Example output and all other words\n       are converted to comments:\n\n       >>> text = \'\'\'\n       ...       Here are examples of simple math.\n       ...\n       ...           Python has super accurate integer addition\n       ...\n       ...           >>> 2 + 2\n       ...           5\n       ...\n       ...           And very friendly error messages:\n       ...\n       ...           >>> 1/0\n       ...           To Infinity\n       ...           And\n       ...           Beyond\n       ...\n       ...           You can use logic if you want:\n       ...\n       ...           >>> if 0:\n       ...           ...    blah\n       ...           ...    blah\n       ...           ...\n       ...\n       ...           Ho hum\n       ...           \'\'\'\n\n       >>> print(script_from_examples(text))\n       # Here are examples of simple math.\n       #\n       #     Python has super accurate integer addition\n       #\n       2 + 2\n       # Expected:\n       ## 5\n       #\n       #     And very friendly error messages:\n       #\n       1/0\n       # Expected:\n       ## To Infinity\n       ## And\n       ## Beyond\n       #\n       #     You can use logic if you want:\n       #\n       if 0:\n          blah\n          blah\n       #\n       #     Ho hum\n       <BLANKLINE>\n       """\n'),
    ('stdlib/doctest.py', 2614, 2620, 'testsource', 'def testsource(module, name):\n    """Extract the test sources from a doctest docstring as a script.\n\n    Provide the module (or dotted name of the module) containing the\n    test to be debugged and the name (within the module) of the object\n    with the doc string with tests to be debugged.\n    """\n'),
    ('stdlib/doctest.py', 2630, 2631, 'debug_src', 'def debug_src(src, pm=False, globs=None):\n    """Debug a single doctest docstring, in argument `src`\'"""\n'),
    ('stdlib/doctest.py', 2635, 2636, 'debug_script', 'def debug_script(src, pm=False, globs=None):\n    "Debug a test script.  `src` is the script, as a string."\n'),
    ('stdlib/doctest.py', 2655, 2661, 'debug', 'def debug(module, name, pm=False):\n    """Debug a single doctest docstring.\n\n    Provide the module (or dotted name of the module) containing the\n    test to be debugged and the name (within the module) of the object\n    with the docstring with tests to be debugged.\n    """\n'),
    ('stdlib/enum.py', 1011, 1014, 'unique', 'def unique(enumeration):\n    """\n    Class decorator for enumerations ensuring unique member values.\n    """\n'),
    ('stdlib/filecmp.py', 26, 27, 'clear_cache', 'def clear_cache():\n    """Clear the filecmp cache."""\n'),
    ('stdlib/filecmp.py', 30, 51, 'cmp', 'def cmp(f1, f2, shallow=True):\n    """Compare two files.\n\n    Arguments:\n\n    f1 -- First file name\n\n    f2 -- Second file name\n\n    shallow -- treat files as identical if their stat signatures (type, size,\n               mtime) are identical. Otherwise, files are considered different\n               if their sizes or contents differ.  [default: True]\n\n    Return value:\n\n    True if the files are the same, False otherwise.\n\n    This function uses a cache for past comparisons and the results,\n    with cache entries invalidated if their stat information\n    changes.  The cache may be cleared by calling clear_cache().\n\n    """\n'),
    ('stdlib/filecmp.py', 258, 270, 'cmpfiles', 'def cmpfiles(a, b, common, shallow=True):\n    """Compare common files in two directories.\n\n    a, b -- directory names\n    common -- list of file names found in both directories\n    shallow -- if true, do comparison based solely on stat() information\n\n    Returns a tuple of three lists:\n      files that compare equal\n      files that are different\n      filenames that aren\'t regular files.\n\n    """\n'),
    ('stdlib/filecmp.py', 300, 300, 'demo', 'def demo():\n'),
    ('stdlib/fileinput.py', 78, 85, 'input', 'def input(files=None, inplace=False, backup="", *, mode="r", openhook=None,\n          encoding=None, errors=None):\n    """Return an instance of the FileInput class, which can be iterated.\n\n    The parameters are passed to the constructor of the FileInput class.\n    The returned instance, in addition to being an iterator,\n    keeps global state for the functions of this module,.\n    """\n'),
    ('stdlib/fileinput.py', 93, 94, 'close', 'def close():\n    """Close the sequence."""\n'),
    ('stdlib/fileinput.py', 101, 110, 'nextfile', 'def nextfile():\n    """\n    Close the current file so that the next iteration will read the first\n    line from the next file (if any); lines not read from the file will\n    not count towards the cumulative line count. The filename is not\n    changed until after the first line of the next file has been read.\n    Before the first line has been read, this function has no effect;\n    it cannot be used to skip the first file. After the last line of the\n    last file has been read, this function has no effect.\n    """\n'),
    ('stdlib/fileinput.py', 115, 119, 'filename', 'def filename():\n    """\n    Return the name of the file currently being read.\n    Before the first line has been read, returns None.\n    """\n'),
    ('stdlib/fileinput.py', 124, 129, 'lineno', 'def lineno():\n    """\n    Return the cumulative line number of the line that has just been read.\n    Before the first line has been read, returns 0. After the last line\n    of the last file has been read, returns the line number of that line.\n    """\n'),
    ('stdlib/fileinput.py', 134, 139, 'filelineno', 'def filelineno():\n    """\n    Return the line number in the current file. Before the first line\n    has been read, returns 0. After the last line of the last file has\n    been read, returns the line number of that line within the file.\n    """\n'),
    ('stdlib/fileinput.py', 144, 148, 'fileno', 'def fileno():\n    """\n    Return the file number of the current file. When no file is currently\n    opened, returns -1.\n    """\n'),
    ('stdlib/fileinput.py', 153, 157, 'isfirstline', 'def isfirstline():\n    """\n    Returns true the line just read is the first line of its file,\n    otherwise returns false.\n    """\n'),
    ('stdlib/fileinput.py', 162, 166, 'isstdin', 'def isstdin():\n    """\n    Returns true if the last line was read from sys.stdin,\n    otherwise returns false.\n    """\n'),
    ('stdlib/fileinput.py', 421, 421, 'hook_compressed', 'def hook_compressed(filename, mode, *, encoding=None, errors=None):\n'),
    ('stdlib/fileinput.py', 440, 440, 'hook_encoded', 'def hook_encoded(encoding, errors=None):\n'),
    ('stdlib/fnmatch.py', 25, 39, 'fnmatch', 'def fnmatch(name, pat):\n    """Test whether FILENAME matches PATTERN.\n\n    Patterns are Unix shell style:\n\n    *       matches everything\n    ?       matches any single character\n    [seq]   matches any character in seq\n    [!seq]  matches any char not in seq\n\n    An initial period in FILENAME is not special.\n    Both FILENAME and PATTERN are first case-normalized\n    if the operating system requires it.\n    If you don\'t want this, use fnmatchcase(FILENAME, PATTERN).\n    """\n'),
    ('stdlib/fnmatch.py', 54, 55, 'filter', 'def filter(names, pat):\n    """Construct a list from those elements of the iterable NAMES that match PAT."""\n'),
    ('stdlib/fnmatch.py', 70, 75, 'fnmatchcase', 'def fnmatchcase(name, pat):\n    """Test whether FILENAME matches PATTERN, including case.\n\n    This is a version of fnmatch() which doesn\'t case-normalize\n    its arguments.\n    """\n'),
    ('stdlib/fnmatch.py', 80, 84, 'translate', 'def translate(pat):\n    """Translate a shell PATTERN to a regular expression.\n\n    There is no way to quote meta-characters.\n    """\n'),
    ('stdlib/ftplib.py', 814, 818, 'parse150', "def parse150(resp):\n    '''Parse the '150' response for a RETR request.\n    Returns the expected transfer size or None; size is not guaranteed to\n    be present in the 150 message.\n    '''\n"),
    ('stdlib/ftplib.py', 834, 837, 'parse227', "def parse227(resp):\n    '''Parse the '227' response for a PASV request.\n    Raises error_proto if it does not contain '(h1,h2,h3,h4,p1,p2)'\n    Return ('host.addr.as.numbers', port#) tuple.'''\n"),
    ('stdlib/ftplib.py', 853, 856, 'parse229', "def parse229(resp, peer):\n    '''Parse the '229' response for an EPSV request.\n    Raises error_proto if it does not contain '(|||port|)'\n    Return ('host.addr.as.numbers', port#) tuple.'''\n"),
    ('stdlib/ftplib.py', 874, 877, 'parse257', "def parse257(resp):\n    '''Parse the '257' response for a MKD or PWD request.\n    This is a response to a MKD or PWD request: a directory name.\n    Returns the directoryname in the 257 reply.'''\n"),
    ('stdlib/ftplib.py', 896, 897, 'print_line', "def print_line(line):\n    '''Default retrlines callback to print a line.'''\n"),
    ('stdlib/ftplib.py', 901, 902, 'ftpcp', "def ftpcp(source, sourcename, target, targetname = '', type = 'I'):\n    '''Copy file from one FTP-instance to another.'''\n"),
    ('stdlib/ftplib.py', 923, 930, 'test', "def test():\n    '''Test program.\n    Usage: ftp [-d] [-r[file]] host [-l[dir]] [-d[dir]] [-p] [file] ...\n\n    -d dir\n    -l list\n    -p password\n    '''\n"),
    ('stdlib/functools.py', 35, 49, 'update_wrapper', 'def update_wrapper(wrapper,\n                   wrapped,\n                   assigned = WRAPPER_ASSIGNMENTS,\n                   updated = WRAPPER_UPDATES):\n    """Update a wrapper function to look like the wrapped function\n\n       wrapper is the function to be updated\n       wrapped is the original function\n       assigned is a tuple naming the attributes assigned directly\n       from the wrapped function to the wrapper function (defaults to\n       functools.WRAPPER_ASSIGNMENTS)\n       updated is a tuple naming the attributes of the wrapper that\n       are updated with the corresponding attribute from the wrapped\n       function (defaults to functools.WRAPPER_UPDATES)\n    """\n'),
    ('stdlib/functools.py', 65, 75, 'wraps', 'def wraps(wrapped,\n          assigned = WRAPPER_ASSIGNMENTS,\n          updated = WRAPPER_UPDATES):\n    """Decorator factory to apply update_wrapper() to a wrapper function\n\n       Returns a decorator that invokes update_wrapper() with the decorated\n       function as the wrapper argument and the arguments to wraps() as the\n       remaining arguments. Default arguments are as for update_wrapper().\n       This is a convenience function to simplify applying partial() to\n       update_wrapper().\n    """\n'),
    ('stdlib/functools.py', 188, 189, 'total_ordering', 'def total_ordering(cls):\n    """Class decorator that fills in missing ordering methods"""\n'),
    ('stdlib/functools.py', 206, 207, 'cmp_to_key', 'def cmp_to_key(mycmp):\n    """Convert a cmp= function into a key= function"""\n'),
    ('stdlib/functools.py', 237, 247, 'reduce', 'def reduce(function, sequence, initial=_initial_missing):\n    """\n    reduce(function, iterable[, initial]) -> value\n\n    Apply a function of two arguments cumulatively to the items of a sequence\n    or iterable, from left to right, so as to reduce the iterable to a single\n    value.  For example, reduce(lambda x, y: x+y, [1, 2, 3, 4, 5]) calculates\n    ((((1+2)+3)+4)+5).  If initial is present, it is placed before the items\n    of the iterable in the calculation, and serves as a default when the\n    iterable is empty.\n    """\n'),
    ('stdlib/functools.py', 479, 497, 'lru_cache', 'def lru_cache(maxsize=128, typed=False):\n    """Least-recently-used cache decorator.\n\n    If *maxsize* is set to None, the LRU features are disabled and the cache\n    can grow without bound.\n\n    If *typed* is True, arguments of different types will be cached separately.\n    For example, f(3.0) and f(3) will be treated as distinct calls with\n    distinct results.\n\n    Arguments to the cached function must be hashable.\n\n    View the cache statistics named tuple (hits, misses, maxsize, currsize)\n    with f.cache_info().  Clear the cache and statistics with f.cache_clear().\n    Access the underlying function with f.__wrapped__.\n\n    See:  https://en.wikipedia.org/wiki/Cache_replacement_policies#Least_recently_used_(LRU)\n\n    """\n'),
    ('stdlib/functools.py', 651, 652, 'cache', 'def cache(user_function, /):\n    \'Simple lightweight unbounded cache.  Sometimes called "memoize".\'\n'),
    ('stdlib/functools.py', 800, 808, 'singledispatch', 'def singledispatch(func):\n    """Single-dispatch generic function decorator.\n\n    Transforms a function into a generic function, which can have different\n    behaviours depending upon the type of its first argument. The decorated\n    function acts as the default implementation, and additional\n    implementations can be registered using the register() attribute of the\n    generic function.\n    """\n'),
    ('stdlib/genericpath.py', 16, 17, 'exists', 'def exists(path):\n    """Test whether a path exists.  Returns False for broken symbolic links"""\n'),
    ('stdlib/genericpath.py', 27, 28, 'isfile', 'def isfile(path):\n    """Test whether a path is a regular file"""\n'),
    ('stdlib/genericpath.py', 39, 40, 'isdir', 'def isdir(s):\n    """Return true if the pathname refers to an existing directory."""\n'),
    ('stdlib/genericpath.py', 48, 49, 'getsize', 'def getsize(filename):\n    """Return the size of a file, reported by os.stat()."""\n'),
    ('stdlib/genericpath.py', 53, 54, 'getmtime', 'def getmtime(filename):\n    """Return the last modification time of a file, reported by os.stat()."""\n'),
    ('stdlib/genericpath.py', 58, 59, 'getatime', 'def getatime(filename):\n    """Return the last access time of a file, reported by os.stat()."""\n'),
    ('stdlib/genericpath.py', 63, 64, 'getctime', 'def getctime(filename):\n    """Return the metadata change time of a file, reported by os.stat()."""\n'),
    ('stdlib/genericpath.py', 69, 70, 'commonprefix', 'def commonprefix(m):\n    "Given a list of pathnames, returns the longest common leading component"\n'),
    ('stdlib/genericpath.py', 87, 88, 'samestat', 'def samestat(s1, s2):\n    """Test whether two stat buffers reference the same file"""\n'),
    ('stdlib/genericpath.py', 94, 99, 'samefile', 'def samefile(f1, f2):\n    """Test whether two pathnames reference the same actual file or directory\n\n    This is determined by the device number and i-node number and\n    raises an exception if an os.stat() call on either pathname fails.\n    """\n'),
    ('stdlib/genericpath.py', 107, 108, 'sameopenfile', 'def sameopenfile(fp1, fp2):\n    """Test whether two open file objects reference the same file"""\n'),
    ('stdlib/getopt.py', 56, 81, 'getopt', 'def getopt(args, shortopts, longopts = []):\n    """getopt(args, options[, long_options]) -> opts, args\n\n    Parses command line options and parameter list.  args is the\n    argument list to be parsed, without the leading reference to the\n    running program.  Typically, this means "sys.argv[1:]".  shortopts\n    is the string of option letters that the script wants to\n    recognize, with options that require an argument followed by a\n    colon (i.e., the same format that Unix getopt() uses).  If\n    specified, longopts is a list of strings with the names of the\n    long options which should be supported.  The leading \'--\'\n    characters should not be included in the option name.  Options\n    which require an argument should be followed by an equal sign\n    (\'=\').\n\n    The return value consists of two elements: the first is a list of\n    (option, value) pairs; the second is the list of program arguments\n    left after the option list was stripped (this is a trailing slice\n    of the first argument).  Each option-and-value pair returned has\n    the option as its first element, prefixed with a hyphen (e.g.,\n    \'-x\'), and the option argument as its second element, or an empty\n    string if the option has no argument.  The options occur in the\n    list in the same order in which they were found, thus allowing\n    multiple occurrences.  Long and short options may be mixed.\n\n    """\n'),
    ('stdlib/getopt.py', 99, 112, 'gnu_getopt', 'def gnu_getopt(args, shortopts, longopts = []):\n    """getopt(args, options[, long_options]) -> opts, args\n\n    This function works like getopt(), except that GNU style scanning\n    mode is used by default. This means that option and non-option\n    arguments may be intermixed. The getopt() function stops\n    processing options as soon as a non-option argument is\n    encountered.\n\n    If the first character of the option string is `+\', or if the\n    environment variable POSIXLY_CORRECT is set, then option\n    processing stops as soon as a non-option argument is encountered.\n\n    """\n'),
    ('stdlib/getopt.py', 149, 149, 'do_longs', 'def do_longs(opts, opt, longopts, args):\n'),
    ('stdlib/getopt.py', 171, 171, 'long_has_args', 'def long_has_args(opt, longopts):\n'),
    ('stdlib/getopt.py', 192, 192, 'do_shorts', 'def do_shorts(opts, optstring, shortopts, args):\n'),
    ('stdlib/getopt.py', 207, 207, 'short_has_arg', 'def short_has_arg(opt, shortopts):\n'),
    ('stdlib/getpass.py', 29, 43, 'unix_getpass', 'def unix_getpass(prompt=\'Password: \', stream=None):\n    """Prompt for a password, with echo turned off.\n\n    Args:\n      prompt: Written on stream to ask for the input.  Default: \'Password: \'\n      stream: A writable file object to display the prompt.  Defaults to\n              the tty.  If no tty is available defaults to sys.stderr.\n    Returns:\n      The seKr3t input.\n    Raises:\n      EOFError: If our input tty or stdin was closed.\n      GetPassWarning: When we were unable to turn echo off on the input.\n\n    Always restores terminal settings before returning.\n    """\n'),
    ('stdlib/getpass.py', 97, 98, 'win_getpass', 'def win_getpass(prompt=\'Password: \', stream=None):\n    """Prompt for password with echo off, using Windows getwch()."""\n'),
    ('stdlib/getpass.py', 120, 120, 'fallback_getpass', "def fallback_getpass(prompt='Password: ', stream=None):\n"),
    ('stdlib/getpass.py', 154, 160, 'getuser', 'def getuser():\n    """Get the username from the environment or password database.\n\n    First try various environment variables, then the password\n    database.  This works on Windows as long as USERNAME is set.\n\n    """\n'),
    ('stdlib/gettext.py', 175, 178, 'c2py', 'def c2py(plural):\n    """Gets a C expression as used in PO files for plural forms and returns a\n    Python function that implements an equivalent expression.\n    """\n'),
