    ('stdlib/glob.py', 224, 226, 'escape', 'def escape(pathname):\n    """Escape all special characters.\n    """\n'),
    ('stdlib/gzip.py', 25, 44, 'open', 'def open(filename, mode="rb", compresslevel=_COMPRESS_LEVEL_BEST,\n         encoding=None, errors=None, newline=None):\n    """Open a gzip-compressed file in binary or text mode.\n\n    The filename argument can be an actual filename (a str or bytes object), or\n    an existing file object to read from or write to.\n\n    The mode argument can be "r", "rb", "w", "wb", "x", "xb", "a" or "ab" for\n    binary mode, or "rt", "wt", "xt" or "at" for text mode. The default mode is\n    "rb", and the default compresslevel is 9.\n\n    For binary mode, this function is equivalent to the GzipFile constructor:\n    GzipFile(filename, mode, compresslevel). In this case, the encoding, errors\n    and newline arguments must not be provided.\n\n    For text mode, a GzipFile object is created, and wrapped in an\n    io.TextIOWrapper instance with the specified encoding, error handling\n    behavior, and line ending(s).\n\n    """\n'),
    ('stdlib/gzip.py', 70, 72, 'write32u', 'def write32u(output, value):\n    # The L format writes the bit pattern correctly whether signed\n    # or unsigned.\n'),
    ('stdlib/gzip.py', 543, 546, 'compress', 'def compress(data, compresslevel=_COMPRESS_LEVEL_BEST, *, mtime=None):\n    """Compress data in one shot and return the compressed string.\n    Optional argument is the compression level, in range of 0-9.\n    """\n'),
    ('stdlib/gzip.py', 552, 555, 'decompress', 'def decompress(data):\n    """Decompress a gzip compressed string in one shot.\n    Return the decompressed string.\n    """\n'),
    ('stdlib/gzip.py', 560, 560, 'main', 'def main():\n'),
    ('stdlib/heapq.py', 130, 131, 'heappush', 'def heappush(heap, item):\n    """Push item onto heap, maintaining the heap invariant."""\n'),
    ('stdlib/heapq.py', 135, 136, 'heappop', 'def heappop(heap):\n    """Pop the smallest item off the heap, maintaining the heap invariant."""\n'),
    ('stdlib/heapq.py', 145, 155, 'heapreplace', 'def heapreplace(heap, item):\n    """Pop and return the current smallest value, and add the new item.\n\n    This is more efficient than heappop() followed by heappush(), and can be\n    more appropriate when using a fixed-size heap.  Note that the value\n    returned may be larger than item!  That constrains reasonable uses of\n    this routine unless written as part of a conditional replacement:\n\n        if item > heap[0]:\n            item = heapreplace(heap, item)\n    """\n'),
    ('stdlib/heapq.py', 161, 162, 'heappushpop', 'def heappushpop(heap, item):\n    """Fast version of a heappush followed by a heappop."""\n'),
    ('stdlib/heapq.py', 168, 169, 'heapify', 'def heapify(x):\n    """Transform list into a heap, in-place, in O(len(x)) time."""\n'),
    ('stdlib/heapq.py', 314, 330, 'merge', "def merge(*iterables, key=None, reverse=False):\n    '''Merge multiple sorted inputs into a single sorted output.\n\n    Similar to sorted(itertools.chain(*iterables)) but returns a generator,\n    does not pull the data into memory all at once, and assumes that each of\n    the input streams is already sorted (smallest to largest).\n\n    >>> list(merge([1,3,5,7], [0,2,4,8], [5,10,15,20], [], [25]))\n    [0, 1, 2, 3, 4, 5, 5, 7, 8, 10, 15, 20, 25]\n\n    If *key* is not None, applies a key function to each element to determine\n    its sort order.\n\n    >>> list(merge(['dog', 'horse'], ['cat', 'fish', 'kangaroo'], key=len))\n    ['dog', 'cat', 'fish', 'horse', 'kangaroo']\n\n    '''\n"),
    ('stdlib/heapq.py', 461, 465, 'nsmallest', 'def nsmallest(n, iterable, key=None):\n    """Find the n smallest elements in a dataset.\n\n    Equivalent to:  sorted(iterable, key=key)[:n]\n    """\n'),
    ('stdlib/heapq.py', 521, 525, 'nlargest', 'def nlargest(n, iterable, key=None):\n    """Find the n largest elements in a dataset.\n\n    Equivalent to:  sorted(iterable, key=key, reverse=True)[:n]\n    """\n'),
    ('stdlib/hmac.py', 167, 183, 'new', 'def new(key, msg=None, digestmod=\'\'):\n    """Create a new hashing object and return it.\n\n    key: bytes or buffer, The starting key for the hash.\n    msg: bytes or buffer, Initial input for the hash, or None.\n    digestmod: A hash name suitable for hashlib.new(). *OR*\n               A hashlib constructor returning a new hash object. *OR*\n               A module supporting PEP 247.\n\n               Required as of 3.8, despite its position after the optional\n               msg argument.  Passing it as a keyword argument is\n               recommended, though not required for legacy API reasons.\n\n    You can now feed arbitrary bytes into the object using its update()\n    method, and can ask for the hash value at any time by calling its digest()\n    or hexdigest() methods.\n    """\n'),
    ('stdlib/hmac.py', 187, 195, 'digest', 'def digest(key, msg, digest):\n    """Fast inline implementation of HMAC.\n\n    key: bytes or buffer, The key for the keyed hash object.\n    msg: bytes or buffer, Input message.\n    digest: A hash name suitable for hashlib.new() for best performance. *OR*\n            A hashlib constructor returning a new hash object. *OR*\n            A module supporting PEP 247.\n    """\n'),
    ('stdlib/imaplib.py', 1445, 1450, 'Internaldate2tuple', 'def Internaldate2tuple(resp):\n    """Parse an IMAP4 INTERNALDATE string.\n\n    Return corresponding local time.  The return value is a\n    time.struct_time tuple or None if the string has wrong format.\n    """\n'),
    ('stdlib/imaplib.py', 1480, 1482, 'Int2AP', 'def Int2AP(num):\n\n    """Convert integer to A-P string representation."""\n'),
    ('stdlib/imaplib.py', 1493, 1495, 'ParseFlags', 'def ParseFlags(resp):\n\n    """Convert IMAP4 flags response to python tuple."""\n'),
    ('stdlib/imaplib.py', 1504, 1515, 'Time2Internaldate', 'def Time2Internaldate(date_time):\n\n    """Convert date_time to IMAP4 INTERNALDATE representation.\n\n    Return string in form: \'"DD-Mmm-YYYY HH:MM:SS +HHMM"\'.  The\n    date_time argument can be a number (int or float) representing\n    seconds since epoch (as returned by time.time()), a 9-tuple\n    representing local time, an instance of time.struct_time (as\n    returned by time.localtime()), an aware datetime instance or a\n    double-quoted string.  In the last case, it is assumed to already\n    be in the correct format.\n    """\n'),
