    ('stdlib/imp.py', 73, 86, 'cache_from_source', 'def cache_from_source(path, debug_override=None):\n    """**DEPRECATED**\n\n    Given the path to a .py file, return the path to its .pyc file.\n\n    The .py file does not need to exist; this simply returns the path to the\n    .pyc file calculated as if the .py file were imported.\n\n    If debug_override is not None, then it must be a boolean and is used in\n    place of sys.flags.optimize.\n\n    If sys.implementation.cache_tag is None then NotImplementedError is raised.\n\n    """\n'),
    ('stdlib/imp.py', 92, 102, 'source_from_cache', 'def source_from_cache(path):\n    """**DEPRECATED**\n\n    Given the path to a .pyc. file, return the path to its .py file.\n\n    The .pyc file does not need to exist; this simply returns the path to\n    the .py file calculated to correspond to the .pyc file.  If path does\n    not conform to PEP 3147 format, ValueError will be raised. If\n    sys.implementation.cache_tag is None then NotImplementedError is raised.\n\n    """\n'),
    ('stdlib/imp.py', 106, 107, 'get_suffixes', 'def get_suffixes():\n    """**DEPRECATED**"""\n'),
    ('stdlib/imp.py', 166, 166, 'load_source', 'def load_source(name, pathname, file=None):\n'),
    ('stdlib/imp.py', 185, 186, 'load_compiled', 'def load_compiled(name, pathname, file=None):\n    """**DEPRECATED**"""\n'),
    ('stdlib/imp.py', 200, 201, 'load_package', 'def load_package(name, path):\n    """**DEPRECATED**"""\n'),
    ('stdlib/imp.py', 220, 227, 'load_module', 'def load_module(name, file, filename, details):\n    """**DEPRECATED**\n\n    Load a module, given information returned by find_module().\n\n    The module name must include the full package name, if any.\n\n    """\n'),
    ('stdlib/imp.py', 255, 265, 'find_module', 'def find_module(name, path=None):\n    """**DEPRECATED**\n\n    Search for a module.\n\n    If path is omitted or None, search for a built-in, frozen or special\n    module and continue search in sys.path. The module name cannot\n    contain \'.\'; to search for a submodule of a package, pass the\n    submodule name and the package\'s __path__.\n\n    """\n'),
    ('stdlib/imp.py', 307, 314, 'reload', 'def reload(module):\n    """**DEPRECATED**\n\n    Reload the module and return it.\n\n    The module must have been successfully imported before.\n\n    """\n'),
    ('stdlib/imp.py', 318, 323, 'init_builtin', 'def init_builtin(name):\n    """**DEPRECATED**\n\n    Load and return a built-in module by name, or None is such module doesn\'t\n    exist\n    """\n'),
    ('stdlib/inspect.py', 66, 110, 'get_annotations', 'def get_annotations(obj, *, globals=None, locals=None, eval_str=False):\n    """Compute the annotations dict for an object.\n\n    obj may be a callable, class, or module.\n    Passing in an object of any other type raises TypeError.\n\n    Returns a dict.  get_annotations() returns a new dict every time\n    it\'s called; calling it twice on the same object will return two\n    different but equivalent dicts.\n\n    This function handles several details for you:\n\n      * If eval_str is true, values of type str will\n        be un-stringized using eval().  This is intended\n        for use with stringized annotations\n        ("from __future__ import annotations").\n      * If obj doesn\'t have an annotations dict, returns an\n        empty dict.  (Functions and methods always have an\n        annotations dict; classes, modules, and other types of\n        callables may not.)\n      * Ignores inherited annotations on classes.  If a class\n        doesn\'t have its own annotations dict, returns an empty dict.\n      * All accesses to object members and dict values are done\n        using getattr() and dict.get() for safety.\n      * Always, always, always returns a freshly-created dict.\n\n    eval_str controls whether or not values of type str are replaced\n    with the result of calling eval() on those values:\n\n      * If eval_str is true, eval() is called on values of type str.\n      * If eval_str is false (the default), values of type str are unchanged.\n\n    globals and locals are passed in to eval(); see the documentation\n    for eval() for more information.  If either globals or locals is\n    None, this function may replace that value with a context-specific\n    default, contingent on type(obj):\n\n      * If obj is a module, globals defaults to obj.__dict__.\n      * If obj is a class, globals defaults to\n        sys.modules[obj.__module__].__dict__ and locals\n        defaults to the obj class namespace.\n      * If obj is a callable, globals defaults to obj.__globals__,\n        although if obj is a wrapped function (using\n        functools.update_wrapper()) it is first unwrapped.\n    """\n'),
    ('stdlib/inspect.py', 182, 188, 'ismodule', 'def ismodule(object):\n    """Return true if the object is a module.\n\n    Module objects provide these attributes:\n        __cached__      pathname to byte compiled file\n        __doc__         documentation string\n        __file__        filename (missing for built-in modules)"""\n'),
    ('stdlib/inspect.py', 191, 196, 'isclass', 'def isclass(object):\n    """Return true if the object is a class.\n\n    Class objects provide these attributes:\n        __doc__         documentation string\n        __module__      name of module in which this class was defined"""\n'),
    ('stdlib/inspect.py', 199, 206, 'ismethod', 'def ismethod(object):\n    """Return true if the object is an instance method.\n\n    Instance method objects provide these attributes:\n        __doc__         documentation string\n        __name__        name with which this method was defined\n        __func__        function object containing implementation of method\n        __self__        instance to which this method is bound"""\n'),
    ('stdlib/inspect.py', 209, 222, 'ismethoddescriptor', 'def ismethoddescriptor(object):\n    """Return true if the object is a method descriptor.\n\n    But not if ismethod() or isclass() or isfunction() are true.\n\n    This is new in Python 2.2, and, for example, is true of int.__add__.\n    An object passing this test has a __get__ attribute but not a __set__\n    attribute, but beyond that the set of attributes varies.  __name__ is\n    usually sensible, and __doc__ often is.\n\n    Methods implemented via descriptors that also pass one of the other\n    tests return false from the ismethoddescriptor() test, simply because\n    the other tests promise more -- you can, e.g., count on having the\n    __func__ attribute (etc) when an object passes ismethod()."""\n'),
    ('stdlib/inspect.py', 229, 236, 'isdatadescriptor', 'def isdatadescriptor(object):\n    """Return true if the object is a data descriptor.\n\n    Data descriptors have a __set__ or a __delete__ attribute.  Examples are\n    properties (defined in Python) and getsets and members (defined in C).\n    Typically, data descriptors will also have __name__ and __doc__ attributes\n    (properties, getsets, and members have both of these attributes), but this\n    is not guaranteed."""\n'),
    ('stdlib/inspect.py', 277, 287, 'isfunction', 'def isfunction(object):\n    """Return true if the object is a user-defined function.\n\n    Function objects provide these attributes:\n        __doc__         documentation string\n        __name__        name with which this function was defined\n        __code__        code object containing compiled function bytecode\n        __defaults__    tuple of any default values for arguments\n        __globals__     global namespace in which this function was defined\n        __annotations__ dict of parameter annotations\n        __kwdefaults__  dict of keyword only parameters with defaults"""\n'),
    ('stdlib/inspect.py', 301, 305, 'isgeneratorfunction', 'def isgeneratorfunction(obj):\n    """Return true if the object is a user-defined generator function.\n\n    Generator function objects provide the same attributes as functions.\n    See help(isfunction) for a list of attributes."""\n'),
    ('stdlib/inspect.py', 308, 312, 'iscoroutinefunction', 'def iscoroutinefunction(obj):\n    """Return true if the object is a coroutine function.\n\n    Coroutine functions are defined with "async def" syntax.\n    """\n'),
    ('stdlib/inspect.py', 315, 320, 'isasyncgenfunction', 'def isasyncgenfunction(obj):\n    """Return true if the object is an asynchronous generator function.\n\n    Asynchronous generator functions are defined with "async def"\n    syntax and have "yield" expressions in their body.\n    """\n'),
    ('stdlib/inspect.py', 323, 324, 'isasyncgen', 'def isasyncgen(object):\n    """Return true if the object is an asynchronous generator."""\n'),
    ('stdlib/inspect.py', 327, 341, 'isgenerator', 'def isgenerator(object):\n    """Return true if the object is a generator.\n\n    Generator objects provide these attributes:\n        __iter__        defined to support iteration over container\n        close           raises a new GeneratorExit exception inside the\n                        generator to terminate the iteration\n        gi_code         code object\n        gi_frame        frame object or possibly None once the generator has\n                        been exhausted\n        gi_running      set to 1 when generator is executing, 0 otherwise\n        next            return the next item from the container\n        send            resumes the generator and "sends" a value that becomes\n                        the result of the current yield-expression\n        throw           used to raise an exception inside the generator"""\n'),
    ('stdlib/inspect.py', 344, 345, 'iscoroutine', 'def iscoroutine(object):\n    """Return true if the object is a coroutine."""\n'),
    ('stdlib/inspect.py', 348, 349, 'isawaitable', 'def isawaitable(object):\n    """Return true if object can be passed to an ``await`` expression."""\n'),
    ('stdlib/inspect.py', 355, 362, 'istraceback', 'def istraceback(object):\n    """Return true if the object is a traceback.\n\n    Traceback objects provide these attributes:\n        tb_frame        frame object at this level\n        tb_lasti        index of last attempted instruction in bytecode\n        tb_lineno       current line number in Python source code\n        tb_next         next inner traceback object (called by this level)"""\n'),
    ('stdlib/inspect.py', 365, 376, 'isframe', 'def isframe(object):\n    """Return true if the object is a frame object.\n\n    Frame objects provide these attributes:\n        f_back          next outer frame object (this frame\'s caller)\n        f_builtins      built-in namespace seen by this frame\n        f_code          code object being executed in this frame\n        f_globals       global namespace seen by this frame\n        f_lasti         index of last attempted instruction in bytecode\n        f_lineno        current line number in Python source code\n        f_locals        local namespace seen by this frame\n        f_trace         tracing function for this frame, or None"""\n'),
    ('stdlib/inspect.py', 379, 401, 'iscode', 'def iscode(object):\n    """Return true if the object is a code object.\n\n    Code objects provide these attributes:\n        co_argcount         number of arguments (not including *, ** args\n                            or keyword only arguments)\n        co_code             string of raw compiled bytecode\n        co_cellvars         tuple of names of cell variables\n        co_consts           tuple of constants used in the bytecode\n        co_filename         name of file in which this code object was created\n        co_firstlineno      number of first line in Python source code\n        co_flags            bitmap: 1=optimized | 2=newlocals | 4=*arg | 8=**arg\n                            | 16=nested | 32=generator | 64=nofree | 128=coroutine\n                            | 256=iterable_coroutine | 512=async_generator\n        co_freevars         tuple of names of free variables\n        co_posonlyargcount  number of positional only arguments\n        co_kwonlyargcount   number of keyword only arguments (not including ** arg)\n        co_lnotab           encoded mapping of line numbers to bytecode indices\n        co_name             name with which this code object was defined\n        co_names            tuple of names other than arguments and function locals\n        co_nlocals          number of local variables\n        co_stacksize        virtual machine stack space required\n        co_varnames         tuple of names of arguments and local variables"""\n'),
    ('stdlib/inspect.py', 404, 410, 'isbuiltin', 'def isbuiltin(object):\n    """Return true if the object is a built-in function or method.\n\n    Built-in functions and methods provide these attributes:\n        __doc__         documentation string\n        __name__        original name of this function or method\n        __self__        instance to which a method is bound, or None"""\n'),
    ('stdlib/inspect.py', 413, 414, 'isroutine', 'def isroutine(object):\n    """Return true if the object is any kind of function or method."""\n'),
    ('stdlib/inspect.py', 420, 421, 'isabstract', 'def isabstract(object):\n    """Return true if the object is an abstract base class (ABC)."""\n'),
    ('stdlib/inspect.py', 444, 446, 'getmembers', 'def getmembers(object, predicate=None):\n    """Return all members of an object as (name, value) pairs sorted by name.\n    Optionally, only return members that satisfy a given predicate."""\n'),
    ('stdlib/inspect.py', 490, 515, 'classify_class_attrs', 'def classify_class_attrs(cls):\n    """Return list of attribute-descriptor tuples.\n\n    For each name in dir(cls), the return list contains a 4-tuple\n    with these elements:\n\n        0. The name (a string).\n\n        1. The kind of attribute this is, one of these strings:\n               \'class method\'    created via classmethod()\n               \'static method\'   created via staticmethod()\n               \'property\'        created via property()\n               \'method\'          any other flavor of method or descriptor\n               \'data\'            not a method\n\n        2. The class which defined this attribute (a class).\n\n        3. The object as obtained by calling getattr; if this fails, or if the\n           resulting object does not live anywhere in the class\' mro (including\n           metaclasses) then the object is looked up in the defining class\'s\n           dict (found by walking the mro).\n\n    If one of the items in dir(cls) is stored in the metaclass it will now\n    be discovered and not have None be listed as the class in which it was\n    defined.  Any items whose home class cannot be discovered are skipped.\n    """\n'),
    ('stdlib/inspect.py', 606, 607, 'getmro', 'def getmro(cls):\n    "Return tuple of base classes (including cls) in method resolution order."\n'),
    ('stdlib/inspect.py', 612, 627, 'unwrap', 'def unwrap(func, *, stop=None):\n    """Get the object wrapped by *func*.\n\n   Follows the chain of :attr:`__wrapped__` attributes returning the last\n   object in the chain.\n\n   *stop* is an optional callback accepting an object in the wrapper chain\n   as its sole argument that allows the unwrapping to be terminated early if\n   the callback returns a true value. If the callback never returns a true\n   value, the last object in the chain is returned as usual. For example,\n   :func:`signature` uses this to stop unwrapping if any object in the\n   chain has a ``__signature__`` attribute defined.\n\n   :exc:`ValueError` is raised if a cycle is encountered.\n\n    """\n'),
    ('stdlib/inspect.py', 648, 649, 'indentsize', 'def indentsize(line):\n    """Return the indent size, in spaces, at the start of a line of text."""\n'),
    ('stdlib/inspect.py', 725, 730, 'getdoc', 'def getdoc(object):\n    """Get the documentation string for an object.\n\n    All tabs are expanded to spaces.  To clean up docstrings that are\n    indented to line up with blocks of code, any whitespace than can be\n    uniformly removed from the second line onwards is removed."""\n'),
    ('stdlib/inspect.py', 744, 748, 'cleandoc', 'def cleandoc(doc):\n    """Clean up indentation from docstrings.\n\n    Any whitespace that can be uniformly removed from the second line\n    onwards is removed."""\n'),
    ('stdlib/inspect.py', 773, 774, 'getfile', 'def getfile(object):\n    """Work out which source or compiled file an object was defined in."""\n'),
    ('stdlib/inspect.py', 801, 802, 'getmodulename', 'def getmodulename(path):\n    """Return the module name for a given file, or None."""\n'),
    ('stdlib/inspect.py', 813, 816, 'getsourcefile', 'def getsourcefile(object):\n    """Return the filename that can be used to locate an object\'s source.\n    Return None if no way can be identified to get the source.\n    """\n'),
    ('stdlib/inspect.py', 838, 842, 'getabsfile', 'def getabsfile(object, _filename=None):\n    """Return an absolute path to the source or compiled file for an object.\n\n    The idea is for each object to have a unique origin, so this routine\n    normalizes the result as much as possible."""\n'),
    ('stdlib/inspect.py', 850, 851, 'getmodule', 'def getmodule(object, _filename=None):\n    """Return the module an object was defined in, or None if not found."""\n'),
    ('stdlib/inspect.py', 932, 938, 'findsource', 'def findsource(object):\n    """Return the entire source file and starting line number for an object.\n\n    The argument may be a module, class, method, function, traceback, frame,\n    or code object.  The source code is returned as a list of all the lines\n    in the file and the line number indexes a line in that list.  An OSError\n    is raised if the source code cannot be retrieved."""\n'),
    ('stdlib/inspect.py', 1000, 1004, 'getcomments', 'def getcomments(object):\n    """Get lines of comments immediately preceding an object\'s source code.\n\n    Returns None when source can\'t be found.\n    """\n'),
    ('stdlib/inspect.py', 1101, 1102, 'getblock', 'def getblock(lines):\n    """Extract the block of code at the top of the given list of lines."""\n'),
    ('stdlib/inspect.py', 1112, 1119, 'getsourcelines', 'def getsourcelines(object):\n    """Return a list of source lines and starting line number for an object.\n\n    The argument may be a module, class, method, function, traceback, frame,\n    or code object.  The source code is returned as a list of the lines\n    corresponding to the object and the line number indicates where in the\n    original source file the first line of code was found.  An OSError is\n    raised if the source code cannot be retrieved."""\n'),
    ('stdlib/inspect.py', 1133, 1138, 'getsource', 'def getsource(object):\n    """Return the text of the source code for an object.\n\n    The argument may be a module, class, method, function, traceback, frame,\n    or code object.  The source code is returned as a single string.  An\n    OSError is raised if the source code cannot be retrieved."""\n'),
    ('stdlib/inspect.py', 1143, 1144, 'walktree', 'def walktree(classes, children, parent):\n    """Recursive helper function for getclasstree()."""\n'),
    ('stdlib/inspect.py', 1153, 1161, 'getclasstree', 'def getclasstree(classes, unique=False):\n    """Arrange the given list of classes into a hierarchy of nested lists.\n\n    Where a nested list appears, it contains classes derived from the class\n    whose entry immediately precedes the list.  Each entry is a 2-tuple\n    containing a class and a tuple of its base classes.  If the \'unique\'\n    argument is true, exactly one entry appears in the returned structure\n    for each class in the given list.  Otherwise, classes using multiple\n    inheritance and their descendants will appear multiple times."""\n'),
    ('stdlib/inspect.py', 1182, 1188, 'getargs', 'def getargs(co):\n    """Get information about the arguments accepted by a code object.\n\n    Three things are returned: (args, varargs, varkw), where\n    \'args\' is the list of argument names. Keyword-only arguments are\n    appended. \'varargs\' and \'varkw\' are the names of the * and **\n    arguments or None."""\n'),
    ('stdlib/inspect.py', 1211, 1230, 'getargspec', 'def getargspec(func):\n    """Get the names and default values of a function\'s parameters.\n\n    A tuple of four things is returned: (args, varargs, keywords, defaults).\n    \'args\' is a list of the argument names, including keyword-only argument names.\n    \'varargs\' and \'keywords\' are the names of the * and ** parameters or None.\n    \'defaults\' is an n-tuple of the default values of the last n parameters.\n\n    This function is deprecated, as it does not support annotations or\n    keyword-only parameters and will raise ValueError if either is present\n    on the supplied callable.\n\n    For a more structured introspection API, use inspect.signature() instead.\n\n    Alternatively, use getfullargspec() for an API with a similar namedtuple\n    based interface, but full support for annotations and keyword-only\n    parameters.\n\n    Deprecated since Python 3.5, use `inspect.getfullargspec()`.\n    """\n'),
    ('stdlib/inspect.py', 1244, 1259, 'getfullargspec', 'def getfullargspec(func):\n    """Get the names and default values of a callable object\'s parameters.\n\n    A tuple of seven things is returned:\n    (args, varargs, varkw, defaults, kwonlyargs, kwonlydefaults, annotations).\n    \'args\' is a list of the parameter names.\n    \'varargs\' and \'varkw\' are the names of the * and ** parameters or None.\n    \'defaults\' is an n-tuple of the default values of the last n parameters.\n    \'kwonlyargs\' is a list of keyword-only parameter names.\n    \'kwonlydefaults\' is a dictionary mapping names from kwonlyargs to defaults.\n    \'annotations\' is a dictionary mapping parameter names to annotations.\n\n    Notable differences from inspect.signature():\n      - the "self" parameter is always reported, even for bound methods\n      - wrapper chains defined by __wrapped__ *not* unwrapped automatically\n    """\n'),
    ('stdlib/inspect.py', 1339, 1345, 'getargvalues', 'def getargvalues(frame):\n    """Get information about arguments passed into a particular frame.\n\n    A tuple of four things is returned: (args, varargs, varkw, locals).\n    \'args\' is a list of the argument names.\n    \'varargs\' and \'varkw\' are the names of the * and ** arguments or None.\n    \'locals\' is the locals dictionary of the given frame."""\n'),
    ('stdlib/inspect.py', 1349, 1349, 'formatannotation', 'def formatannotation(annotation, base_module=None):\n'),
    ('stdlib/inspect.py', 1363, 1363, 'formatannotationrelativeto', 'def formatannotationrelativeto(object):\n'),
    ('stdlib/inspect.py', 1369, 1387, 'formatargspec', 'def formatargspec(args, varargs=None, varkw=None, defaults=None,\n                  kwonlyargs=(), kwonlydefaults={}, annotations={},\n                  formatarg=str,\n                  formatvarargs=lambda name: \'*\' + name,\n                  formatvarkw=lambda name: \'**\' + name,\n                  formatvalue=lambda value: \'=\' + repr(value),\n                  formatreturns=lambda text: \' -> \' + text,\n                  formatannotation=formatannotation):\n    """Format an argument spec from the values returned by getfullargspec.\n\n    The first seven arguments are (args, varargs, varkw, defaults,\n    kwonlyargs, kwonlydefaults, annotations).  The other five arguments\n    are the corresponding optional formatting functions that are called to\n    turn names and values into strings.  The last argument is an optional\n    function to format the sequence of arguments.\n\n    Deprecated since Python 3.5: use the `signature` function and `Signature`\n    objects.\n    """\n'),
    ('stdlib/inspect.py', 1427, 1437, 'formatargvalues', 'def formatargvalues(args, varargs, varkw, locals,\n                    formatarg=str,\n                    formatvarargs=lambda name: \'*\' + name,\n                    formatvarkw=lambda name: \'**\' + name,\n                    formatvalue=lambda value: \'=\' + repr(value)):\n    """Format an argument spec from the 4 values returned by getargvalues.\n\n    The first four arguments are (args, varargs, varkw, locals).  The\n    next four arguments are the corresponding optional formatting functions\n    that are called to turn names and values into strings.  The ninth\n    argument is an optional function to format the sequence of arguments."""\n'),
    ('stdlib/inspect.py', 1487, 1492, 'getcallargs', 'def getcallargs(func, /, *positional, **named):\n    """Get the mapping of arguments to values.\n\n    A dict is returned, with keys the function argument names (including the\n    names of the * and ** arguments, if any), and values the respective bound\n    values from \'positional\' and \'named\'."""\n'),
    ('stdlib/inspect.py', 1549, 1556, 'getclosurevars', 'def getclosurevars(func):\n    """\n    Get the mapping of free variables to their current values.\n\n    Returns a named tuple of dicts mapping the current nonlocal, global\n    and builtin references as seen by the body of the function. A final\n    set of unbound names that could not be resolved is also provided.\n    """\n'),
    ('stdlib/inspect.py', 1604, 1611, 'getframeinfo', 'def getframeinfo(frame, context=1):\n    """Get information about a frame or traceback object.\n\n    A tuple of five things is returned: the filename, the line number of\n    the current line, the function name, a list of lines of context from\n    the source code, and the index of the current line within that list.\n    The optional second argument specifies the number of lines of context\n    to return, which are centered around the current line."""\n'),
    ('stdlib/inspect.py', 1636, 1637, 'getlineno', 'def getlineno(frame):\n    """Get the line number from a frame object, allowing for optimization."""\n'),
    ('stdlib/inspect.py', 1643, 1647, 'getouterframes', 'def getouterframes(frame, context=1):\n    """Get a list of records for a frame and all higher (calling) frames.\n\n    Each record contains a frame object, filename, line number, function\n    name, a list of lines of context, and index within the context."""\n'),
    ('stdlib/inspect.py', 1655, 1659, 'getinnerframes', 'def getinnerframes(tb, context=1):\n    """Get a list of records for a traceback\'s frame and all lower frames.\n\n    Each record contains a frame object, filename, line number, function\n    name, a list of lines of context, and index within the context."""\n'),
    ('stdlib/inspect.py', 1667, 1668, 'currentframe', 'def currentframe():\n    """Return the frame of the caller or None if this is not possible."""\n'),
    ('stdlib/inspect.py', 1671, 1672, 'stack', 'def stack(context=1):\n    """Return a list of records for the stack above the caller\'s frame."""\n'),
    ('stdlib/inspect.py', 1675, 1676, 'trace', 'def trace(context=1):\n    """Return a list of records for the stack below the current exception."""\n'),
    ('stdlib/inspect.py', 1726, 1736, 'getattr_static', 'def getattr_static(obj, attr, default=_sentinel):\n    """Retrieve attributes without triggering dynamic lookup via the\n       descriptor protocol,  __getattr__ or __getattribute__.\n\n       Note: this function may not be able to retrieve all attributes\n       that getattr can fetch (like dynamically created attributes)\n       and may find attributes that getattr can\'t (like descriptors\n       that raise AttributeError). It can also return descriptor objects\n       instead of instance members in some cases. See the\n       documentation for details.\n    """\n'),
    ('stdlib/inspect.py', 1779, 1787, 'getgeneratorstate', 'def getgeneratorstate(generator):\n    """Get current state of a generator-iterator.\n\n    Possible states are:\n      GEN_CREATED: Waiting to start execution.\n      GEN_RUNNING: Currently being executed by the interpreter.\n      GEN_SUSPENDED: Currently suspended at a yield expression.\n      GEN_CLOSED: Execution has completed.\n    """\n'),
    ('stdlib/inspect.py', 1797, 1802, 'getgeneratorlocals', 'def getgeneratorlocals(generator):\n    """\n    Get the mapping of generator local variables to their current values.\n\n    A dict is returned, with the keys the local variable names and values the\n    bound values."""\n'),
    ('stdlib/inspect.py', 1821, 1829, 'getcoroutinestate', 'def getcoroutinestate(coroutine):\n    """Get current state of a coroutine object.\n\n    Possible states are:\n      CORO_CREATED: Waiting to start execution.\n      CORO_RUNNING: Currently being executed by the interpreter.\n      CORO_SUSPENDED: Currently suspended at an await expression.\n      CORO_CLOSED: Execution has completed.\n    """\n'),
    ('stdlib/inspect.py', 1839, 1844, 'getcoroutinelocals', 'def getcoroutinelocals(coroutine):\n    """\n    Get the mapping of coroutine local variables to their current values.\n\n    A dict is returned, with the keys the local variable names and values the\n    bound values."""\n'),
    ('stdlib/inspect.py', 3252, 3253, 'signature', 'def signature(obj, *, follow_wrapped=True, globals=None, locals=None, eval_str=False):\n    """Get a signature object for the passed callable."""\n'),
    ('stdlib/ipaddress.py', 28, 43, 'ip_address', 'def ip_address(address):\n    """Take an IP string/int and return an object of the correct type.\n\n    Args:\n        address: A string or integer, the IP address.  Either IPv4 or\n          IPv6 addresses may be supplied; integers less than 2**32 will\n          be considered to be IPv4 by default.\n\n    Returns:\n        An IPv4Address or IPv6Address object.\n\n    Raises:\n        ValueError: if the *address* passed isn\'t either a v4 or a v6\n          address\n\n    """\n'),
    ('stdlib/ipaddress.py', 57, 72, 'ip_network', 'def ip_network(address, strict=True):\n    """Take an IP string/int and return an object of the correct type.\n\n    Args:\n        address: A string or integer, the IP network.  Either IPv4 or\n          IPv6 networks may be supplied; integers less than 2**32 will\n          be considered to be IPv4 by default.\n\n    Returns:\n        An IPv4Network or IPv6Network object.\n\n    Raises:\n        ValueError: if the string passed isn\'t either a v4 or a v6\n          address. Or if the network has host bits set.\n\n    """\n'),
    ('stdlib/ipaddress.py', 86, 106, 'ip_interface', 'def ip_interface(address):\n    """Take an IP string/int and return an object of the correct type.\n\n    Args:\n        address: A string or integer, the IP address.  Either IPv4 or\n          IPv6 addresses may be supplied; integers less than 2**32 will\n          be considered to be IPv4 by default.\n\n    Returns:\n        An IPv4Interface or IPv6Interface object.\n\n    Raises:\n        ValueError: if the string passed isn\'t either a v4 or a v6\n          address.\n\n    Notes:\n        The IPv?Interface classes describe an Address on a particular\n        Network, so they\'re basically a combination of both the Address\n        and Network classes.\n\n    """\n'),
    ('stdlib/ipaddress.py', 120, 133, 'v4_int_to_packed', 'def v4_int_to_packed(address):\n    """Represent an address as 4 packed bytes in network (big-endian) order.\n\n    Args:\n        address: An integer representation of an IPv4 IP address.\n\n    Returns:\n        The integer address packed as 4 bytes in network (big-endian) order.\n\n    Raises:\n        ValueError: If the integer is negative or too large to be an\n          IPv4 IP address.\n\n    """\n'),
    ('stdlib/ipaddress.py', 140, 149, 'v6_int_to_packed', 'def v6_int_to_packed(address):\n    """Represent an address as 16 packed bytes in network (big-endian) order.\n\n    Args:\n        address: An integer representation of an IPv6 IP address.\n\n    Returns:\n        The integer address packed as 16 bytes in network (big-endian) order.\n\n    """\n'),
    ('stdlib/ipaddress.py', 200, 225, 'summarize_address_range', 'def summarize_address_range(first, last):\n    """Summarize a network range given the first and last IP addresses.\n\n    Example:\n        >>> list(summarize_address_range(IPv4Address(\'192.0.2.0\'),\n        ...                              IPv4Address(\'192.0.2.130\')))\n        ...                                #doctest: +NORMALIZE_WHITESPACE\n        [IPv4Network(\'192.0.2.0/25\'), IPv4Network(\'192.0.2.128/31\'),\n         IPv4Network(\'192.0.2.130/32\')]\n\n    Args:\n        first: the first IPv4Address or IPv6Address in the range.\n        last: the last IPv4Address or IPv6Address in the range.\n\n    Returns:\n        An iterator of the summarized IPv(4|6) network objects.\n\n    Raise:\n        TypeError:\n            If the first and last objects are not IP addresses.\n            If the first and last objects are not the same version.\n        ValueError:\n            If the last object is not greater than the first.\n            If the version of the first address is not 4 or 6.\n\n    """\n'),
    ('stdlib/ipaddress.py', 304, 321, 'collapse_addresses', 'def collapse_addresses(addresses):\n    """Collapse a list of IP objects.\n\n    Example:\n        collapse_addresses([IPv4Network(\'192.0.2.0/25\'),\n                            IPv4Network(\'192.0.2.128/25\')]) ->\n                           [IPv4Network(\'192.0.2.0/24\')]\n\n    Args:\n        addresses: An iterator of IPv4Network or IPv6Network objects.\n\n    Returns:\n        An iterator of the collapsed IPv(4|6)Network objects.\n\n    Raises:\n        TypeError: If passed a list of mixed version objects.\n\n    """\n'),
    ('stdlib/ipaddress.py', 358, 375, 'get_mixed_type_key', 'def get_mixed_type_key(obj):\n    """Return a key suitable for sorting between networks and addresses.\n\n    Address and Network objects are not sortable by default; they\'re\n    fundamentally different so the expression\n\n        IPv4Address(\'192.0.2.0\') <= IPv4Network(\'192.0.2.0/24\')\n\n    doesn\'t make any sense.  There are some times however, where you may wish\n    to have ipaddress sort these for you anyway. If you need to do this, you\n    can use this function as the key= argument to sorted().\n\n    Args:\n      obj: either a Network or Address object.\n    Returns:\n      appropriate key.\n\n    """\n'),
    ('stdlib/linecache.py', 21, 22, 'clearcache', 'def clearcache():\n    """Clear the cache entirely."""\n'),
    ('stdlib/linecache.py', 26, 28, 'getline', 'def getline(filename, lineno, module_globals=None):\n    """Get a line for a Python source file from the cache.\n    Update the cache if it doesn\'t contain an entry for this file already."""\n'),
    ('stdlib/linecache.py', 36, 38, 'getlines', 'def getlines(filename, module_globals=None):\n    """Get the lines for a Python source file from the cache.\n    Update the cache if it doesn\'t contain an entry for this file already."""\n'),
    ('stdlib/linecache.py', 52, 54, 'checkcache', 'def checkcache(filename=None):\n    """Discard cache entries that are out of date.\n    (This is not checked upon each call!)"""\n'),
    ('stdlib/linecache.py', 80, 83, 'updatecache', 'def updatecache(filename, module_globals=None):\n    """Update a cache entry and return its list of lines.\n    If something\'s wrong, print a message, discard the cache entry,\n    and return an empty list."""\n'),
    ('stdlib/linecache.py', 147, 159, 'lazycache', 'def lazycache(filename, module_globals):\n    """Seed the cache for filename with module_globals.\n\n    The module loader will be asked for the source only when getlines is\n    called, not immediately.\n\n    If there is an entry in the cache already, it is not altered.\n\n    :return: True if a lazy load is registered in the cache,\n        otherwise False. To register such a load a module loader with a\n        get_source method must be found, the filename must be a cacheable\n        filename, and the filename must not be already cached.\n    """\n'),
    ('stdlib/locale.py', 109, 109, 'localeconv', 'def localeconv():\n'),
    ('stdlib/locale.py', 213, 219, 'format_string', 'def format_string(f, val, grouping=False, monetary=False):\n    """Formats a string in the same way that the % formatting would use,\n    but takes the current locale into account.\n\n    Grouping is applied if the third parameter is true.\n    Conversion uses monetary thousands separator and grouping strings if\n    forth parameter monetary is true."""\n'),
    ('stdlib/locale.py', 250, 251, 'format', 'def format(percent, value, grouping=False, monetary=False, *additional):\n    """Deprecated, use format_string instead."""\n'),
    ('stdlib/locale.py', 265, 267, 'currency', 'def currency(val, symbol=True, grouping=False, international=False):\n    """Formats val according to the currency settings\n    in the current locale."""\n'),
    ('stdlib/locale.py', 312, 313, 'str', 'def str(val):\n    """Convert float to string, taking the locale into account."""\n'),
    ('stdlib/locale.py', 316, 317, 'delocalize', 'def delocalize(string):\n    "Parses a string as a normalized number according to the locale settings."\n'),
    ('stdlib/locale.py', 332, 333, 'localize', 'def localize(string, grouping=False, monetary=False):\n    """Parses a string as locale number according to the locale settings."""\n'),
    ('stdlib/locale.py', 336, 337, 'atof', 'def atof(string, func=float):\n    "Parses a string as a float according to the locale settings."\n'),
    ('stdlib/locale.py', 340, 341, 'atoi', 'def atoi(string):\n    "Converts a string to an integer according to the locale settings."\n'),
    ('stdlib/locale.py', 396, 411, 'normalize', 'def normalize(localename):\n\n    """ Returns a normalized locale code for the given locale\n        name.\n\n        The returned locale code is formatted for use with\n        setlocale().\n\n        If normalization fails, the original name is returned\n        unchanged.\n\n        If the given encoding is not known, the function defaults to\n        the default encoding for the locale code just like setlocale()\n        does.\n\n    """\n'),
    ('stdlib/locale.py', 534, 556, 'getdefaultlocale', 'def getdefaultlocale(envvars=(\'LC_ALL\', \'LC_CTYPE\', \'LANG\', \'LANGUAGE\')):\n\n    """ Tries to determine the default locale settings and returns\n        them as tuple (language code, encoding).\n\n        According to POSIX, a program which has not called\n        setlocale(LC_ALL, "") runs using the portable \'C\' locale.\n        Calling setlocale(LC_ALL, "") lets it use the default locale as\n        defined by the LANG variable. Since we don\'t want to interfere\n        with the current locale setting we thus emulate the behavior\n        in the way described above.\n\n        To maintain compatibility with other platforms, not only the\n        LANG variable is tested, but a list of variables given as\n        envvars parameter. The first found to be defined will be\n        used. envvars defaults to the search path used in GNU gettext;\n        it must always contain the variable name \'LANG\'.\n\n        Except for the code \'C\', the language code corresponds to RFC\n        1766.  code and encoding can be None in case the values cannot\n        be determined.\n\n    """\n'),
    ('stdlib/locale.py', 587, 599, 'getlocale', 'def getlocale(category=LC_CTYPE):\n\n    """ Returns the current setting for the given locale category as\n        tuple (language code, encoding).\n\n        category may be one of the LC_* value except LC_ALL. It\n        defaults to LC_CTYPE.\n\n        Except for the code \'C\', the language code corresponds to RFC\n        1766.  code and encoding can be None in case the values cannot\n        be determined.\n\n    """\n'),
    ('stdlib/locale.py', 605, 616, 'setlocale', 'def setlocale(category, locale=None):\n\n    """ Set the locale for the given category.  The locale can be\n        a string, an iterable of two strings (language code and encoding),\n        or None.\n\n        Iterables are converted to strings using the locale aliasing\n        engine.  Locale strings are passed directly to the C lib.\n\n        category may be given as one of the LC_* values.\n\n    """\n'),
    ('stdlib/locale.py', 622, 629, 'resetlocale', 'def resetlocale(category=LC_ALL):\n\n    """ Sets the locale for category to the default setting.\n\n        The default setting is determined by calling\n        getdefaultlocale(). category defaults to LC_ALL.\n\n    """\n'),
    ('stdlib/lzma.py', 271, 296, 'open', 'def open(filename, mode="rb", *,\n         format=None, check=-1, preset=None, filters=None,\n         encoding=None, errors=None, newline=None):\n    """Open an LZMA-compressed file in binary or text mode.\n\n    filename can be either an actual file name (given as a str, bytes,\n    or PathLike object), in which case the named file is opened, or it\n    can be an existing file object to read from or write to.\n\n    The mode argument can be "r", "rb" (default), "w", "wb", "x", "xb",\n    "a", or "ab" for binary mode, or "rt", "wt", "xt", or "at" for text\n    mode.\n\n    The format, check, preset and filters arguments specify the\n    compression settings, as for LZMACompressor, LZMADecompressor and\n    LZMAFile.\n\n    For binary mode, this function is equivalent to the LZMAFile\n    constructor: LZMAFile(filename, mode, ...). In this case, the\n    encoding, errors and newline arguments must not be provided.\n\n    For text mode, an LZMAFile object is created, and wrapped in an\n    io.TextIOWrapper instance with the specified encoding, error\n    handling behavior, and line ending(s).\n\n    """\n'),
    ('stdlib/lzma.py', 319, 326, 'compress', 'def compress(data, format=FORMAT_XZ, check=-1, preset=None, filters=None):\n    """Compress a block of data.\n\n    Refer to LZMACompressor\'s docstring for a description of the\n    optional arguments *format*, *check*, *preset* and *filters*.\n\n    For incremental compression, use an LZMACompressor instead.\n    """\n'),
    ('stdlib/lzma.py', 331, 338, 'decompress', 'def decompress(data, format=FORMAT_AUTO, memlimit=None, filters=None):\n    """Decompress a block of data.\n\n    Refer to LZMADecompressor\'s docstring for a description of the\n    optional arguments *format*, *check* and *filters*.\n\n    For incremental decompression, use an LZMADecompressor instead.\n    """\n'),
    ('stdlib/mailcap.py', 10, 11, 'lineno_sort_key', 'def lineno_sort_key(entry):\n    # Sort in ascending order, with unspecified entries at the end\n'),
    ('stdlib/mailcap.py', 25, 34, 'getcaps', 'def getcaps():\n    """Return a dictionary containing the mailcap database.\n\n    The dictionary maps a MIME type (in all lowercase, e.g. \'text/plain\')\n    to a list of dictionaries corresponding to mailcap entries.  The list\n    collects all the entries for that MIME type from all available mailcap\n    files.  Each dictionary contains key-value pairs for that MIME type,\n    where the viewing command is stored with the key "view".\n\n    """\n'),
    ('stdlib/mailcap.py', 51, 52, 'listmailcapfiles', 'def listmailcapfiles():\n    """Return a list of all mailcap files found on the system."""\n'),
    ('stdlib/mailcap.py', 69, 70, 'readmailcapfile', 'def readmailcapfile(fp):\n    """Read a mailcap file and return a dictionary keyed by MIME type."""\n'),
    ('stdlib/mailcap.py', 118, 123, 'parseline', 'def parseline(line):\n    """Parse one entry in a mailcap file and return a dictionary.\n\n    The viewing command is stored as the value with the key "view",\n    and the rest of the fields produce key-value pairs in the dict.\n    """\n'),
    ('stdlib/mailcap.py', 149, 150, 'parsefield', 'def parsefield(line, i, n):\n    """Separate one key-value pair in a mailcap entry."""\n'),
    ('stdlib/mailcap.py', 165, 173, 'findmatch', 'def findmatch(caps, MIMEtype, key=\'view\', filename="/dev/null", plist=[]):\n    """Find a match for a mailcap entry.\n\n    Return a tuple containing the command line, and the mailcap entry\n    used; (None, None) if no match is found.  This may invoke the\n    \'test\' command of several matching entries before deciding which\n    entry to use.\n\n    """\n'),
    ('stdlib/mailcap.py', 192, 192, 'lookup', 'def lookup(caps, MIMEtype, key=None):\n'),
    ('stdlib/mailcap.py', 205, 206, 'subst', 'def subst(field, MIMEtype, filename, plist=[]):\n    # XXX Actually, this is Unix-specific\n'),
    ('stdlib/mailcap.py', 246, 246, 'findparam', 'def findparam(name, plist):\n'),
    ('stdlib/mailcap.py', 257, 257, 'test', 'def test():\n'),
    ('stdlib/mailcap.py', 280, 280, 'show', 'def show(caps):\n'),
    ('stdlib/mimetypes.py', 287, 304, 'guess_type', 'def guess_type(url, strict=True):\n    """Guess the type of a file based on its URL.\n\n    Return value is a tuple (type, encoding) where type is None if the\n    type can\'t be guessed (no or unknown suffix) or a string of the\n    form type/subtype, usable for a MIME Content-type header; and\n    encoding is None for no encoding or the name of the program used\n    to encode (e.g. compress or gzip).  The mappings are table\n    driven.  Encoding suffixes are case sensitive; type suffixes are\n    first tried case sensitive, then case insensitive.\n\n    The suffixes .tgz, .taz and .tz (case sensitive!) are all mapped\n    to ".tar.gz".  (This is table-driven too, using the dictionary\n    suffix_map).\n\n    Optional `strict\' argument when false adds a bunch of commonly found, but\n    non-standard types.\n    """\n'),
    ('stdlib/mimetypes.py', 310, 322, 'guess_all_extensions', 'def guess_all_extensions(type, strict=True):\n    """Guess the extensions for a file based on its MIME type.\n\n    Return value is a list of strings giving the possible filename\n    extensions, including the leading dot (\'.\').  The extension is not\n    guaranteed to have been associated with any particular data\n    stream, but would be mapped to the MIME type `type\' by\n    guess_type().  If no extension can be guessed for `type\', None\n    is returned.\n\n    Optional `strict\' argument when false adds a bunch of commonly found,\n    but non-standard types.\n    """\n'),
    ('stdlib/mimetypes.py', 327, 338, 'guess_extension', 'def guess_extension(type, strict=True):\n    """Guess the extension for a file based on its MIME type.\n\n    Return value is a string giving a filename extension, including the\n    leading dot (\'.\').  The extension is not guaranteed to have been\n    associated with any particular data stream, but would be mapped to the\n    MIME type `type\' by guess_type().  If no extension can be guessed for\n    `type\', None is returned.\n\n    Optional `strict\' argument when false adds a bunch of commonly found,\n    but non-standard types.\n    """\n'),
    ('stdlib/mimetypes.py', 343, 354, 'add_type', 'def add_type(type, ext, strict=True):\n    """Add a mapping between a type and an extension.\n\n    When the extension is already known, the new\n    type will replace the old one. When the type\n    is already known the extension will be added\n    to the list of known extensions.\n\n    If strict is true, information will be added to\n    list of standard types, else to the list of non-standard\n    types.\n    """\n'),
    ('stdlib/mimetypes.py', 360, 360, 'init', 'def init(files=None):\n'),
