    ('stdlib/os.py', 553, 557, 'execlp', 'def execlp(file, *args):\n    """execlp(file, *args)\n\n    Execute the executable file (which is searched for along $PATH)\n    with argument list args, replacing the current process. """\n'),
    ('stdlib/os.py', 560, 565, 'execlpe', 'def execlpe(file, *args):\n    """execlpe(file, *args, env)\n\n    Execute the executable file (which is searched for along $PATH)\n    with argument list args and environment env, replacing the current\n    process. """\n'),
    ('stdlib/os.py', 569, 574, 'execvp', 'def execvp(file, args):\n    """execvp(file, args)\n\n    Execute the executable file (which is searched for along $PATH)\n    with argument list args, replacing the current process.\n    args may be a list or tuple of strings. """\n'),
    ('stdlib/os.py', 577, 583, 'execvpe', 'def execvpe(file, args, env):\n    """execvpe(file, args, env)\n\n    Execute the executable file (which is searched for along $PATH)\n    with argument list args and environment env, replacing the\n    current process.\n    args may be a list or tuple of strings. """\n'),
    ('stdlib/os.py', 620, 626, 'get_exec_path', 'def get_exec_path(env=None):\n    """Returns the sequence of directories that will be searched for the\n    named executable (similar to a shell) when launching a process.\n\n    *env* must be an environment variable dict or None.  If *env* is None,\n    os.environ will be used.\n    """\n'),
    ('stdlib/os.py', 772, 775, 'getenv', 'def getenv(key, default=None):\n    """Get an environment variable, return None if it doesn\'t exist.\n    The optional second argument can specify an alternate default.\n    key, default and the result are str."""\n'),
