    ('stdlib/pdb.py', 1641, 1641, 'pm', 'def pm():\n'),
    ('stdlib/pdb.py', 1649, 1649, 'test', 'def test():\n'),
    ('stdlib/pdb.py', 1653, 1653, 'help', 'def help():\n'),
    ('stdlib/pdb.py', 1672, 1672, 'main', 'def main():\n'),
    ('stdlib/pickle.py', 335, 336, 'whichmodule', 'def whichmodule(obj, name):\n    """Find the module an object belong to."""\n'),
    ('stdlib/pickle.py', 354, 374, 'encode_long', 'def encode_long(x):\n    r"""Encode a long to a two\'s complement little-endian binary string.\n    Note that 0 is a special case, returning an empty string, to save a\n    byte in the LONG1 pickling context.\n\n    >>> encode_long(0)\n    b\'\'\n    >>> encode_long(255)\n    b\'\\xff\\x00\'\n    >>> encode_long(32767)\n    b\'\\xff\\x7f\'\n    >>> encode_long(-256)\n    b\'\\x00\\xff\'\n    >>> encode_long(-32768)\n    b\'\\x00\\x80\'\n    >>> encode_long(-128)\n    b\'\\x80\'\n    >>> encode_long(127)\n    b\'\\x7f\'\n    >>>\n    """\n'),
    ('stdlib/pickle.py', 384, 401, 'decode_long', 'def decode_long(data):\n    r"""Decode a long from a two\'s complement little-endian binary string.\n\n    >>> decode_long(b\'\')\n    0\n    >>> decode_long(b"\\xff\\x00")\n    255\n    >>> decode_long(b"\\xff\\x7f")\n    32767\n    >>> decode_long(b"\\x00\\xff")\n    -256\n    >>> decode_long(b"\\x00\\x80")\n    -32768\n    >>> decode_long(b"\\x80")\n    -128\n    >>> decode_long(b"\\x7f")\n    127\n    """\n'),
    ('stdlib/pickletools.py', 212, 217, 'read_uint1', 'def read_uint1(f):\n    r"""\n    >>> import io\n    >>> read_uint1(io.BytesIO(b\'\\xff\'))\n    255\n    """\n'),
    ('stdlib/pickletools.py', 231, 238, 'read_uint2', 'def read_uint2(f):\n    r"""\n    >>> import io\n    >>> read_uint2(io.BytesIO(b\'\\xff\\x00\'))\n    255\n    >>> read_uint2(io.BytesIO(b\'\\xff\\xff\'))\n    65535\n    """\n'),
    ('stdlib/pickletools.py', 252, 259, 'read_int4', 'def read_int4(f):\n    r"""\n    >>> import io\n    >>> read_int4(io.BytesIO(b\'\\xff\\x00\\x00\\x00\'))\n    255\n    >>> read_int4(io.BytesIO(b\'\\x00\\x00\\x00\\x80\')) == -(2**31)\n    True\n    """\n'),
    ('stdlib/pickletools.py', 273, 280, 'read_uint4', 'def read_uint4(f):\n    r"""\n    >>> import io\n    >>> read_uint4(io.BytesIO(b\'\\xff\\x00\\x00\\x00\'))\n    255\n    >>> read_uint4(io.BytesIO(b\'\\x00\\x00\\x00\\x80\')) == 2**31\n    True\n    """\n'),
    ('stdlib/pickletools.py', 294, 301, 'read_uint8', 'def read_uint8(f):\n    r"""\n    >>> import io\n    >>> read_uint8(io.BytesIO(b\'\\xff\\x00\\x00\\x00\\x00\\x00\\x00\\x00\'))\n    255\n    >>> read_uint8(io.BytesIO(b\'\\xff\' * 8)) == 2**64-1\n    True\n    """\n'),
    ('stdlib/pickletools.py', 315, 340, 'read_stringnl', 'def read_stringnl(f, decode=True, stripquotes=True):\n    r"""\n    >>> import io\n    >>> read_stringnl(io.BytesIO(b"\'abcd\'\\nefg\\n"))\n    \'abcd\'\n\n    >>> read_stringnl(io.BytesIO(b"\\n"))\n    Traceback (most recent call last):\n    ...\n    ValueError: no string quotes around b\'\'\n\n    >>> read_stringnl(io.BytesIO(b"\\n"), stripquotes=False)\n    \'\'\n\n    >>> read_stringnl(io.BytesIO(b"\'\'\\n"))\n    \'\'\n\n    >>> read_stringnl(io.BytesIO(b\'"abcd"\'))\n    Traceback (most recent call last):\n    ...\n    ValueError: no newline found when trying to read stringnl\n\n    Embedded escapes are undone in the result.\n    >>> read_stringnl(io.BytesIO(br"\'a\\n\\\\b\\x00c\\td\'" + b"\\n\'e\'"))\n    \'a\\n\\\\b\\x00c\\td\'\n    """\n'),
    ('stdlib/pickletools.py', 372, 372, 'read_stringnl_noescape', 'def read_stringnl_noescape(f):\n'),
    ('stdlib/pickletools.py', 386, 391, 'read_stringnl_noescape_pair', 'def read_stringnl_noescape_pair(f):\n    r"""\n    >>> import io\n    >>> read_stringnl_noescape_pair(io.BytesIO(b"Queue\\nEmpty\\njunk"))\n    \'Queue Empty\'\n    """\n'),
    ('stdlib/pickletools.py', 409, 416, 'read_string1', 'def read_string1(f):\n    r"""\n    >>> import io\n    >>> read_string1(io.BytesIO(b"\\x00"))\n    \'\'\n    >>> read_string1(io.BytesIO(b"\\x03abcdef"))\n    \'abc\'\n    """\n'),
    ('stdlib/pickletools.py', 438, 449, 'read_string4', 'def read_string4(f):\n    r"""\n    >>> import io\n    >>> read_string4(io.BytesIO(b"\\x00\\x00\\x00\\x00abc"))\n    \'\'\n    >>> read_string4(io.BytesIO(b"\\x03\\x00\\x00\\x00abcdef"))\n    \'abc\'\n    >>> read_string4(io.BytesIO(b"\\x00\\x00\\x00\\x03abcdef"))\n    Traceback (most recent call last):\n    ...\n    ValueError: expected 50331648 bytes in a string4, but only 6 remain\n    """\n'),
    ('stdlib/pickletools.py', 472, 479, 'read_bytes1', 'def read_bytes1(f):\n    r"""\n    >>> import io\n    >>> read_bytes1(io.BytesIO(b"\\x00"))\n    b\'\'\n    >>> read_bytes1(io.BytesIO(b"\\x03abcdef"))\n    b\'abc\'\n    """\n'),
    ('stdlib/pickletools.py', 500, 511, 'read_bytes4', 'def read_bytes4(f):\n    r"""\n    >>> import io\n    >>> read_bytes4(io.BytesIO(b"\\x00\\x00\\x00\\x00abc"))\n    b\'\'\n    >>> read_bytes4(io.BytesIO(b"\\x03\\x00\\x00\\x00abcdef"))\n    b\'abc\'\n    >>> read_bytes4(io.BytesIO(b"\\x00\\x00\\x00\\x03abcdef"))\n    Traceback (most recent call last):\n    ...\n    ValueError: expected 50331648 bytes in a bytes4, but only 6 remain\n    """\n'),
    ('stdlib/pickletools.py', 534, 546, 'read_bytes8', 'def read_bytes8(f):\n    r"""\n    >>> import io, struct, sys\n    >>> read_bytes8(io.BytesIO(b"\\x00\\x00\\x00\\x00\\x00\\x00\\x00\\x00abc"))\n    b\'\'\n    >>> read_bytes8(io.BytesIO(b"\\x03\\x00\\x00\\x00\\x00\\x00\\x00\\x00abcdef"))\n    b\'abc\'\n    >>> bigsize8 = struct.pack("<Q", sys.maxsize//3)\n    >>> read_bytes8(io.BytesIO(bigsize8 + b"abcdef"))  #doctest: +ELLIPSIS\n    Traceback (most recent call last):\n    ...\n    ValueError: expected ... bytes in a bytes8, but only 6 remain\n    """\n'),
    ('stdlib/pickletools.py', 569, 581, 'read_bytearray8', 'def read_bytearray8(f):\n    r"""\n    >>> import io, struct, sys\n    >>> read_bytearray8(io.BytesIO(b"\\x00\\x00\\x00\\x00\\x00\\x00\\x00\\x00abc"))\n    bytearray(b\'\')\n    >>> read_bytearray8(io.BytesIO(b"\\x03\\x00\\x00\\x00\\x00\\x00\\x00\\x00abcdef"))\n    bytearray(b\'abc\')\n    >>> bigsize8 = struct.pack("<Q", sys.maxsize//3)\n    >>> read_bytearray8(io.BytesIO(bigsize8 + b"abcdef"))  #doctest: +ELLIPSIS\n    Traceback (most recent call last):\n    ...\n    ValueError: expected ... bytes in a bytearray8, but only 6 remain\n    """\n'),
    ('stdlib/pickletools.py', 603, 608, 'read_unicodestringnl', 'def read_unicodestringnl(f):\n    r"""\n    >>> import io\n    >>> read_unicodestringnl(io.BytesIO(b"abc\\\\uabcd\\njunk")) == \'abc\\uabcd\'\n    True\n    """\n'),
    ('stdlib/pickletools.py', 629, 645, 'read_unicodestring1', 'def read_unicodestring1(f):\n    r"""\n    >>> import io\n    >>> s = \'abcd\\uabcd\'\n    >>> enc = s.encode(\'utf-8\')\n    >>> enc\n    b\'abcd\\xea\\xaf\\x8d\'\n    >>> n = bytes([len(enc)])  # little-endian 1-byte length\n    >>> t = read_unicodestring1(io.BytesIO(n + enc + b\'junk\'))\n    >>> s == t\n    True\n\n    >>> read_unicodestring1(io.BytesIO(n + enc[:-1]))\n    Traceback (most recent call last):\n    ...\n    ValueError: expected 7 bytes in a unicodestring1, but only 6 remain\n    """\n'),
    ('stdlib/pickletools.py', 668, 684, 'read_unicodestring4', 'def read_unicodestring4(f):\n    r"""\n    >>> import io\n    >>> s = \'abcd\\uabcd\'\n    >>> enc = s.encode(\'utf-8\')\n    >>> enc\n    b\'abcd\\xea\\xaf\\x8d\'\n    >>> n = bytes([len(enc), 0, 0, 0])  # little-endian 4-byte length\n    >>> t = read_unicodestring4(io.BytesIO(n + enc + b\'junk\'))\n    >>> s == t\n    True\n\n    >>> read_unicodestring4(io.BytesIO(n + enc[:-1]))\n    Traceback (most recent call last):\n    ...\n    ValueError: expected 7 bytes in a unicodestring4, but only 6 remain\n    """\n'),
    ('stdlib/pickletools.py', 709, 725, 'read_unicodestring8', 'def read_unicodestring8(f):\n    r"""\n    >>> import io\n    >>> s = \'abcd\\uabcd\'\n    >>> enc = s.encode(\'utf-8\')\n    >>> enc\n    b\'abcd\\xea\\xaf\\x8d\'\n    >>> n = bytes([len(enc)]) + b\'\\0\' * 7  # little-endian 8-byte length\n    >>> t = read_unicodestring8(io.BytesIO(n + enc + b\'junk\'))\n    >>> s == t\n    True\n\n    >>> read_unicodestring8(io.BytesIO(n + enc[:-1]))\n    Traceback (most recent call last):\n    ...\n    ValueError: expected 7 bytes in a unicodestring8, but only 6 remain\n    """\n'),
    ('stdlib/pickletools.py', 750, 760, 'read_decimalnl_short', 'def read_decimalnl_short(f):\n    r"""\n    >>> import io\n    >>> read_decimalnl_short(io.BytesIO(b"1234\\n56"))\n    1234\n\n    >>> read_decimalnl_short(io.BytesIO(b"1234L\\n56"))\n    Traceback (most recent call last):\n    ...\n    ValueError: invalid literal for int() with base 10: b\'1234L\'\n    """\n'),
    ('stdlib/pickletools.py', 772, 781, 'read_decimalnl_long', 'def read_decimalnl_long(f):\n    r"""\n    >>> import io\n\n    >>> read_decimalnl_long(io.BytesIO(b"1234L\\n56"))\n    1234\n\n    >>> read_decimalnl_long(io.BytesIO(b"123456789012345678901234L\\n6"))\n    123456789012345678901234\n    """\n'),
    ('stdlib/pickletools.py', 813, 818, 'read_floatnl', 'def read_floatnl(f):\n    r"""\n    >>> import io\n    >>> read_floatnl(io.BytesIO(b"-1.25\\n6"))\n    -1.25\n    """\n'),
    ('stdlib/pickletools.py', 835, 843, 'read_float8', 'def read_float8(f):\n    r"""\n    >>> import io, struct\n    >>> raw = struct.pack(">d", -1.25)\n    >>> raw\n    b\'\\xbf\\xf4\\x00\\x00\\x00\\x00\\x00\\x00\'\n    >>> read_float8(io.BytesIO(raw + b"\\n"))\n    -1.25\n    """\n'),
    ('stdlib/pickletools.py', 873, 886, 'read_long1', 'def read_long1(f):\n    r"""\n    >>> import io\n    >>> read_long1(io.BytesIO(b"\\x00"))\n    0\n    >>> read_long1(io.BytesIO(b"\\x02\\xff\\x00"))\n    255\n    >>> read_long1(io.BytesIO(b"\\x02\\xff\\x7f"))\n    32767\n    >>> read_long1(io.BytesIO(b"\\x02\\x00\\xff"))\n    -256\n    >>> read_long1(io.BytesIO(b"\\x02\\x00\\x80"))\n    -32768\n    """\n'),
    ('stdlib/pickletools.py', 905, 918, 'read_long4', 'def read_long4(f):\n    r"""\n    >>> import io\n    >>> read_long4(io.BytesIO(b"\\x02\\x00\\x00\\x00\\xff\\x00"))\n    255\n    >>> read_long4(io.BytesIO(b"\\x02\\x00\\x00\\x00\\xff\\x7f"))\n    32767\n    >>> read_long4(io.BytesIO(b"\\x02\\x00\\x00\\x00\\x00\\xff"))\n    -256\n    >>> read_long4(io.BytesIO(b"\\x02\\x00\\x00\\x00\\x00\\x80"))\n    -32768\n    >>> read_long1(io.BytesIO(b"\\x00\\x00\\x00\\x00"))\n    0\n    """\n'),
    ('stdlib/pickletools.py', 2224, 2225, 'assure_pickle_consistency', 'def assure_pickle_consistency(verbose=False):\n\n'),
    ('stdlib/pickletools.py', 2300, 2322, 'genops', 'def genops(pickle):\n    """Generate all the opcodes in a pickle.\n\n    \'pickle\' is a file-like object, or string, containing the pickle.\n\n    Each opcode in the pickle is generated, from the current pickle position,\n    stopping after a STOP opcode is delivered.  A triple is generated for\n    each opcode:\n\n        opcode, arg, pos\n\n    opcode is an OpcodeInfo record, describing the current opcode.\n\n    If the opcode has an argument embedded in the pickle, arg is its decoded\n    value, as a Python object.  If the opcode doesn\'t have an argument, arg\n    is None.\n\n    If the pickle has a tell() method, pos was the value of pickle.tell()\n    before reading the current opcode.  If the pickle is a bytes object,\n    it\'s wrapped in a BytesIO object, and the latter\'s tell() result is\n    used.  Else (the pickle doesn\'t have a tell(), and it\'s not obvious how\n    to query its current position) pos is None.\n    """\n'),
    ('stdlib/pickletools.py', 2328, 2329, 'optimize', "def optimize(p):\n    'Optimize a pickle string by removing unused PUT opcodes'\n"),
    ('stdlib/pickletools.py', 2395, 2434, 'dis', 'def dis(pickle, out=None, memo=None, indentlevel=4, annotate=0):\n    """Produce a symbolic disassembly of a pickle.\n\n    \'pickle\' is a file-like object, or string, containing a (at least one)\n    pickle.  The pickle is disassembled from the current position, through\n    the first STOP opcode encountered.\n\n    Optional arg \'out\' is a file-like object to which the disassembly is\n    printed.  It defaults to sys.stdout.\n\n    Optional arg \'memo\' is a Python dict, used as the pickle\'s memo.  It\n    may be mutated by dis(), if the pickle contains PUT or BINPUT opcodes.\n    Passing the same memo object to another dis() call then allows disassembly\n    to proceed across multiple pickles that were all created by the same\n    pickler with the same memo.  Ordinarily you don\'t need to worry about this.\n\n    Optional arg \'indentlevel\' is the number of blanks by which to indent\n    a new MARK level.  It defaults to 4.\n\n    Optional arg \'annotate\' if nonzero instructs dis() to add short\n    description of the opcode on each line of disassembled output.\n    The value given to \'annotate\' must be an integer and is used as a\n    hint for the column where annotation should start.  The default\n    value is 0, meaning no annotations.\n\n    In addition to printing the disassembly, some sanity checks are made:\n\n    + All embedded opcode arguments "make sense".\n\n    + Explicit and implicit pop operations have enough items on the stack.\n\n    + When an opcode implicitly refers to a markobject, a markobject is\n      actually on the stack.\n\n    + A memo entry isn\'t referenced before it\'s defined.\n\n    + The markobject isn\'t stored in the memo.\n\n    + A memo entry isn\'t redefined.\n    """\n'),
    ('stdlib/pipes.py', 181, 184, 'makepipeline', "def makepipeline(infile, steps, outfile):\n    # Build a list with for each command:\n    # [input filename or '', command string, kind, output filename or '']\n\n"),
    ('stdlib/pkgutil.py', 40, 42, 'read_code', 'def read_code(stream):\n    # This helper is needed in order for the PEP 302 emulation to\n    # correctly handle compiled files\n'),
    ('stdlib/pkgutil.py', 53, 80, 'walk_packages', 'def walk_packages(path=None, prefix=\'\', onerror=None):\n    """Yields ModuleInfo for all modules recursively\n    on path, or, if path is None, all accessible modules.\n\n    \'path\' should be either None or a list of paths to look for\n    modules in.\n\n    \'prefix\' is a string to output on the front of every module name\n    on output.\n\n    Note that this function must import all *packages* (NOT all\n    modules!) on the given path, in order to access the __path__\n    attribute to find submodules.\n\n    \'onerror\' is a function which gets called with one argument (the\n    name of the package which was being imported) if any exception\n    occurs while trying to import a package.  If no onerror function is\n    supplied, ImportErrors are caught and ignored, while all other\n    exceptions are propagated, terminating the search.\n\n    Examples:\n\n    # list all modules python can access\n    walk_packages()\n\n    # list all submodules of ctypes\n    walk_packages(ctypes.__path__, ctypes.__name__+\'.\')\n    """\n'),
    ('stdlib/pkgutil.py', 110, 119, 'iter_modules', 'def iter_modules(path=None, prefix=\'\'):\n    """Yields ModuleInfo for all submodules on path,\n    or, if path is None, all top-level modules on sys.path.\n\n    \'path\' should be either None or a list of paths to look for\n    modules in.\n\n    \'prefix\' is a string to output on the front of every module name\n    on output.\n    """\n'),
    ('stdlib/pkgutil.py', 137, 137, 'iter_importer_modules', "def iter_importer_modules(importer, prefix=''):\n"),
    ('stdlib/pkgutil.py', 407, 415, 'get_importer', 'def get_importer(path_item):\n    """Retrieve a finder for the given path item\n\n    The returned finder is cached in sys.path_importer_cache\n    if it was newly created by a path hook.\n\n    The cache (or part of it) can be cleared manually if a\n    rescan of sys.path_hooks is necessary.\n    """\n'),
    ('stdlib/pkgutil.py', 431, 442, 'iter_importers', 'def iter_importers(fullname=""):\n    """Yield finders for the given module name\n\n    If fullname contains a \'.\', the finders will be for the package\n    containing fullname, otherwise they will be all registered top level\n    finders (i.e. those on both sys.meta_path and sys.path_hooks).\n\n    If the named module is in a package, that package is imported as a side\n    effect of invoking this function.\n\n    If no module name is specified, all top level finders are produced.\n    """\n'),
    ('stdlib/pkgutil.py', 460, 466, 'get_loader', 'def get_loader(module_or_name):\n    """Get a "loader" object for module_or_name\n\n    Returns None if the module cannot be found or imported.\n    If the named module is not already imported, its containing package\n    (if any) is imported, in order to establish the package __path__.\n    """\n'),
    ('stdlib/pkgutil.py', 484, 490, 'find_loader', 'def find_loader(fullname):\n    """Find a "loader" object for fullname\n\n    This is a backwards compatibility wrapper around\n    importlib.util.find_spec that converts most failures to ImportError\n    and only returns the loader rather than the full spec\n    """\n'),
    ('stdlib/pkgutil.py', 505, 536, 'extend_path', 'def extend_path(path, name):\n    """Extend a package\'s path.\n\n    Intended use is to place the following code in a package\'s __init__.py:\n\n        from pkgutil import extend_path\n        __path__ = extend_path(__path__, __name__)\n\n    This will add to the package\'s __path__ all subdirectories of\n    directories on sys.path named after the package.  This is useful\n    if one wants to distribute different parts of a single logical\n    package as multiple directories.\n\n    It also looks for *.pkg files beginning where * matches the name\n    argument.  This feature is similar to *.pth files (see site.py),\n    except that it doesn\'t special-case lines starting with \'import\'.\n    A *.pkg file is trusted at face value: apart from checking for\n    duplicates, all entries found in a *.pkg file are added to the\n    path, regardless of whether they are exist the filesystem.  (This\n    is a feature.)\n\n    If the input path is not a list (as is the case for frozen\n    packages) it is returned unchanged.  The input path is not\n    modified; an extended copy is returned.  Items are only appended\n    to the copy at the end.\n\n    It is assumed that sys.path is a sequence.  Items of sys.path that\n    are not (unicode or 8-bit) strings referring to existing\n    directories are ignored.  Unicode items of sys.path that cause\n    errors when used as filenames may cause this function to raise an\n    exception (in line with os.path.isdir() behavior).\n    """\n'),
    ('stdlib/pkgutil.py', 599, 619, 'get_data', 'def get_data(package, resource):\n    """Get a resource from a package.\n\n    This is a wrapper round the PEP 302 loader get_data API. The package\n    argument should be the name of a package, in standard module format\n    (foo.bar). The resource argument should be in the form of a relative\n    filename, using \'/\' as the path separator. The parent directory name \'..\'\n    is not allowed, and nor is a rooted name (starting with a \'/\').\n\n    The function returns a binary string, which is the contents of the\n    specified resource.\n\n    For packages located in the filesystem, which have already been imported,\n    this is the rough equivalent of\n\n        d = os.path.dirname(sys.modules[package].__file__)\n        data = open(os.path.join(d, resource), \'rb\').read()\n\n    If the package cannot be located or loaded, or it uses a PEP 302 loader\n    which does not support get_data(), then None is returned.\n    """\n'),
    ('stdlib/pkgutil.py', 644, 675, 'resolve_name', 'def resolve_name(name):\n    """\n    Resolve a name to an object.\n\n    It is expected that `name` will be a string in one of the following\n    formats, where W is shorthand for a valid Python identifier and dot stands\n    for a literal period in these pseudo-regexes:\n\n    W(.W)*\n    W(.W)*:(W(.W)*)?\n\n    The first form is intended for backward compatibility only. It assumes that\n    some part of the dotted name is a package, and the rest is an object\n    somewhere within that package, possibly nested inside other objects.\n    Because the place where the package stops and the object hierarchy starts\n    can\'t be inferred by inspection, repeated attempts to import must be done\n    with this form.\n\n    In the second form, the caller makes the division point clear through the\n    provision of a single colon: the dotted name to the left of the colon is a\n    package to be imported, and the dotted name to the right is the object\n    hierarchy within that package. Only one import is needed in this form. If\n    it ends with the colon, then a module object is returned.\n\n    The function will return an object (which might be a module), or raise one\n    of the following exceptions:\n\n    ValueError - if `name` isn\'t in a recognised format\n    ImportError - if an import failed when it shouldn\'t have\n    AttributeError - if a failure occurred when traversing the object hierarchy\n                     within the imported package to get to the desired object.\n    """\n'),
    ('stdlib/platform.py', 162, 176, 'libc_ver', 'def libc_ver(executable=None, lib=\'\', version=\'\', chunksize=16384):\n\n    """ Tries to determine the libc version that the file executable\n        (which defaults to the Python interpreter) is linked against.\n\n        Returns a tuple of strings (lib,version) which default to the\n        given parameters in case the lookup fails.\n\n        Note that the function has intimate knowledge of how different\n        libc versions add symbols to the executable and thus is probably\n        only useable for executables compiled using gcc.\n\n        The file is read and scanned in chunks of chunksize bytes.\n\n    """\n'),
    ('stdlib/platform.py', 339, 339, 'win32_is_iot', 'def win32_is_iot():\n'),
    ('stdlib/platform.py', 342, 342, 'win32_edition', 'def win32_edition():\n'),
    ('stdlib/platform.py', 360, 360, 'win32_ver', "def win32_ver(release='', version='', csd='', ptype=''):\n"),
    ('stdlib/platform.py', 433, 441, 'mac_ver', 'def mac_ver(release=\'\', versioninfo=(\'\', \'\', \'\'), machine=\'\'):\n\n    """ Get macOS version information and return it as tuple (release,\n        versioninfo, machine) with versioninfo being a tuple (version,\n        dev_stage, non_release_version).\n\n        Entries which cannot be determined are set to the parameter values\n        which default to \'\'. All tuple entries are strings.\n    """\n'),
    ('stdlib/platform.py', 463, 474, 'java_ver', 'def java_ver(release=\'\', vendor=\'\', vminfo=(\'\', \'\', \'\'), osinfo=(\'\', \'\', \'\')):\n\n    """ Version interface for Jython.\n\n        Returns a tuple (release, vendor, vminfo, osinfo) with vminfo being\n        a tuple (vm_name, vm_release, vm_vendor) and osinfo being a\n        tuple (os_name, os_version, os_arch).\n\n        Values which cannot be determined are set to the defaults\n        given as parameters (which all default to \'\').\n\n    """\n'),
    ('stdlib/platform.py', 498, 506, 'system_alias', 'def system_alias(system, release, version):\n\n    """ Returns (system, release, version) aliased to common\n        marketing names used for some systems.\n\n        It also does some reordering of the information in some cases\n        where it would otherwise cause confusion.\n\n    """\n'),
    ('stdlib/platform.py', 640, 660, 'architecture', 'def architecture(executable=sys.executable, bits=\'\', linkage=\'\'):\n\n    """ Queries the given executable (defaults to the Python interpreter\n        binary) for various architecture information.\n\n        Returns a tuple (bits, linkage) which contains information about\n        the bit architecture and the linkage format used for the\n        executable. Both values are returned as strings.\n\n        Values that cannot be determined are returned as given by the\n        parameter presets. If bits is given as \'\', the sizeof(pointer)\n        (or sizeof(long) on Python version < 1.5.2) is used as\n        indicator for the supported pointer size.\n\n        The function relies on the system\'s "file" command to do the\n        actual work. This is available on most if not all Unix\n        platforms. On some non-Unix platforms where the "file" command\n        does not exist and the executable is set to the Python interpreter\n        binary defaults from _default_architecture are used.\n\n    """\n'),
    ('stdlib/platform.py', 814, 825, 'uname', 'def uname():\n\n    """ Fairly portable uname interface. Returns a tuple\n        of strings (system, node, release, version, machine, processor)\n        identifying the underlying platform.\n\n        Note that unlike the os.uname function this also returns\n        possible processor information as an additional tuple entry.\n\n        Entries which cannot be determined are set to \'\'.\n\n    """\n'),
    ('stdlib/platform.py', 903, 909, 'system', 'def system():\n\n    """ Returns the system/OS name, e.g. \'Linux\', \'Windows\' or \'Java\'.\n\n        An empty string is returned if the value cannot be determined.\n\n    """\n'),
    ('stdlib/platform.py', 912, 919, 'node', 'def node():\n\n    """ Returns the computer\'s network name (which may not be fully\n        qualified)\n\n        An empty string is returned if the value cannot be determined.\n\n    """\n'),
    ('stdlib/platform.py', 922, 928, 'release', 'def release():\n\n    """ Returns the system\'s release, e.g. \'2.2.0\' or \'NT\'\n\n        An empty string is returned if the value cannot be determined.\n\n    """\n'),
    ('stdlib/platform.py', 931, 937, 'version', 'def version():\n\n    """ Returns the system\'s release version, e.g. \'#3 on degas\'\n\n        An empty string is returned if the value cannot be determined.\n\n    """\n'),
    ('stdlib/platform.py', 940, 946, 'machine', 'def machine():\n\n    """ Returns the machine type, e.g. \'i386\'\n\n        An empty string is returned if the value cannot be determined.\n\n    """\n'),
    ('stdlib/platform.py', 949, 958, 'processor', 'def processor():\n\n    """ Returns the (true) processor name, e.g. \'amdk6\'\n\n        An empty string is returned if the value cannot be\n        determined. Note that many platforms do not provide this\n        information or simply return the same value as for machine(),\n        e.g.  NetBSD does this.\n\n    """\n'),
    ('stdlib/platform.py', 1095, 1105, 'python_implementation', 'def python_implementation():\n\n    """ Returns a string identifying the Python implementation.\n\n        Currently, the following implementations are identified:\n          \'CPython\' (C implementation of Python),\n          \'IronPython\' (.NET implementation of Python),\n          \'Jython\' (Java implementation of Python),\n          \'PyPy\' (Python implementation of Python).\n\n    """\n'),
    ('stdlib/platform.py', 1108, 1115, 'python_version', 'def python_version():\n\n    """ Returns the Python version as string \'major.minor.patchlevel\'\n\n        Note that unlike the Python sys.version, the returned value\n        will always include the patchlevel (it defaults to 0).\n\n    """\n'),
    ('stdlib/platform.py', 1118, 1126, 'python_version_tuple', 'def python_version_tuple():\n\n    """ Returns the Python version as tuple (major, minor, patchlevel)\n        of strings.\n\n        Note that unlike the Python sys.version, the returned value\n        will always include the patchlevel (it defaults to 0).\n\n    """\n'),
    ('stdlib/platform.py', 1129, 1139, 'python_branch', 'def python_branch():\n\n    """ Returns a string identifying the Python implementation\n        branch.\n\n        For CPython this is the SCM branch from which the\n        Python binary was built.\n\n        If not available, an empty string is returned.\n\n    """\n'),
    ('stdlib/platform.py', 1143, 1153, 'python_revision', 'def python_revision():\n\n    """ Returns a string identifying the Python implementation\n        revision.\n\n        For CPython this is the SCM revision from which the\n        Python binary was built.\n\n        If not available, an empty string is returned.\n\n    """\n'),
    ('stdlib/platform.py', 1156, 1161, 'python_build', 'def python_build():\n\n    """ Returns a tuple (buildno, builddate) stating the Python\n        build number and date as strings.\n\n    """\n'),
    ('stdlib/platform.py', 1164, 1169, 'python_compiler', 'def python_compiler():\n\n    """ Returns a string identifying the compiler used for compiling\n        Python.\n\n    """\n'),
    ('stdlib/platform.py', 1176, 1194, 'platform', 'def platform(aliased=0, terse=0):\n\n    """ Returns a single string identifying the underlying platform\n        with as much useful information as possible (but no more :).\n\n        The output is intended to be human readable rather than\n        machine parseable. It may look different on different\n        platforms and this is intended.\n\n        If "aliased" is true, the function will use aliases for\n        various platforms that report system names which differ from\n        their common names, e.g. SunOS will be reported as\n        Solaris. The system_alias() function is used to implement\n        this.\n\n        Setting terse to true causes the function to return only the\n        absolute minimum information needed to identify the platform.\n\n    """\n'),
    ('stdlib/platform.py', 1284, 1286, 'freedesktop_os_release', 'def freedesktop_os_release():\n    """Return operation system identification from freedesktop.org os-release\n    """\n'),
    ('stdlib/plistlib.py', 865, 868, 'load', 'def load(fp, *, fmt=None, dict_type=dict):\n    """Read a .plist file. \'fp\' should be a readable and binary file object.\n    Return the unpacked root object (which usually is a dictionary).\n    """\n'),
    ('stdlib/plistlib.py', 887, 890, 'loads', 'def loads(value, *, fmt=None, dict_type=dict):\n    """Read a .plist file from a bytes object.\n    Return the unpacked root object (which usually is a dictionary).\n    """\n'),
    ('stdlib/plistlib.py', 895, 898, 'dump', 'def dump(value, fp, *, fmt=FMT_XML, sort_keys=True, skipkeys=False):\n    """Write \'value\' to a .plist file. \'fp\' should be a writable,\n    binary file object.\n    """\n'),
    ('stdlib/plistlib.py', 906, 908, 'dumps', 'def dumps(value, *, fmt=FMT_XML, skipkeys=False, sort_keys=True):\n    """Return a bytes object with the contents for a .plist file.\n    """\n'),
    ('stdlib/posixpath.py', 52, 53, 'normcase', 'def normcase(s):\n    """Normalize case of pathname.  Has no effect under Posix"""\n'),
    ('stdlib/posixpath.py', 60, 61, 'isabs', 'def isabs(s):\n    """Test whether a path is absolute"""\n'),
    ('stdlib/posixpath.py', 71, 75, 'join', 'def join(a, *p):\n    """Join two or more pathname components, inserting \'/\' as needed.\n    If any component is an absolute path, all previous path components\n    will be discarded.  An empty last part will result in a path that\n    ends with a separator."""\n'),
    ('stdlib/posixpath.py', 100, 102, 'split', 'def split(p):\n    """Split a pathname.  Returns tuple "(head, tail)" where "tail" is\n    everything after the final slash.  Either part may be empty."""\n'),
    ('stdlib/posixpath.py', 117, 117, 'splitext', 'def splitext(p):\n'),
    ('stdlib/posixpath.py', 131, 133, 'splitdrive', 'def splitdrive(p):\n    """Split a pathname into drive and path. On Posix, drive is always\n    empty."""\n'),
    ('stdlib/posixpath.py', 140, 141, 'basename', 'def basename(p):\n    """Returns the final component of a pathname"""\n'),
    ('stdlib/posixpath.py', 150, 151, 'dirname', 'def dirname(p):\n    """Returns the directory component of a pathname"""\n'),
    ('stdlib/posixpath.py', 164, 165, 'islink', 'def islink(path):\n    """Test whether a path is a symbolic link"""\n'),
    ('stdlib/posixpath.py', 174, 175, 'lexists', 'def lexists(path):\n    """Test whether a path exists.  Returns True for broken symbolic links"""\n'),
    ('stdlib/posixpath.py', 186, 187, 'ismount', 'def ismount(path):\n    """Test whether a path is a mount point"""\n'),
    ('stdlib/posixpath.py', 229, 231, 'expanduser', 'def expanduser(path):\n    """Expand ~ and ~user constructions.  If user or $HOME is unknown,\n    do nothing."""\n'),
    ('stdlib/posixpath.py', 285, 287, 'expandvars', 'def expandvars(path):\n    """Expand shell variables of form $var and ${var}.  Unknown variables\n    are left unchanged."""\n'),
    ('stdlib/posixpath.py', 338, 339, 'normpath', 'def normpath(path):\n    """Normalize path, eliminating double slashes, etc."""\n'),
    ('stdlib/posixpath.py', 377, 378, 'abspath', 'def abspath(path):\n    """Return an absolute path."""\n'),
    ('stdlib/posixpath.py', 392, 394, 'realpath', 'def realpath(filename, *, strict=False):\n    """Return the canonical path of the specified filename, eliminating any\nsymbolic links encountered in the path."""\n'),
    ('stdlib/posixpath.py', 466, 467, 'relpath', 'def relpath(path, start=None):\n    """Return a relative version of a path"""\n'),
    ('stdlib/posixpath.py', 507, 508, 'commonpath', 'def commonpath(paths):\n    """Given a sequence of path names, returns the longest common sub-path."""\n'),
    ('stdlib/pprint.py', 48, 50, 'pprint', 'def pprint(object, stream=None, indent=1, width=80, depth=None, *,\n           compact=False, sort_dicts=True, underscore_numbers=False):\n    """Pretty-print a Python object to a stream [default is sys.stdout]."""\n'),
    ('stdlib/pprint.py', 57, 59, 'pformat', 'def pformat(object, indent=1, width=80, depth=None, *,\n            compact=False, sort_dicts=True, underscore_numbers=False):\n    """Format a Python object into a pretty-printed representation."""\n'),
    ('stdlib/pprint.py', 64, 65, 'pp', 'def pp(object, *args, sort_dicts=False, **kwargs):\n    """Pretty-print a Python object"""\n'),
    ('stdlib/pprint.py', 68, 69, 'saferepr', 'def saferepr(object):\n    """Version of repr() which can handle recursive data structures."""\n'),
    ('stdlib/pprint.py', 72, 73, 'isreadable', 'def isreadable(object):\n    """Determine if saferepr(object) is readable by eval()."""\n'),
    ('stdlib/pprint.py', 76, 77, 'isrecursive', 'def isrecursive(object):\n    """Determine if object requires a recursive representation."""\n'),
    ('stdlib/profile.py', 81, 91, 'run', 'def run(statement, filename=None, sort=-1):\n    """Run statement under profiler optionally saving results in filename\n\n    This function takes a single argument that can be passed to the\n    "exec" statement, and an optional file name.  In all cases this\n    routine attempts to "exec" its first argument and gather profiling\n    statistics from the execution. If no file name is present, then this\n    function automatically prints a simple profiling report, sorted by the\n    standard name string (file/line/function-name) that is presented in\n    each line.\n    """\n'),
    ('stdlib/profile.py', 94, 99, 'runctx', 'def runctx(statement, globals, locals, filename=None, sort=-1):\n    """Run statement under profiler, supplying your own globals and locals,\n    optionally saving results in filename.\n\n    statement and filename have the same semantics as profile.run\n    """\n'),
    ('stdlib/profile.py', 553, 553, 'main', 'def main():\n'),
    ('stdlib/pstats.py', 546, 546, 'func_strip_path', 'def func_strip_path(func_name):\n'),
    ('stdlib/pstats.py', 550, 550, 'func_get_function_name', 'def func_get_function_name(func):\n'),
    ('stdlib/pstats.py', 553, 553, 'func_std_string', 'def func_std_string(func_name): # match what old profile produced\n'),
    ('stdlib/pstats.py', 570, 571, 'add_func_stats', 'def add_func_stats(target, source):\n    """Add together all the stats for two profile entries."""\n'),
    ('stdlib/pstats.py', 577, 578, 'add_callers', 'def add_callers(target, source):\n    """Combine two caller lists in a single list."""\n'),
    ('stdlib/pstats.py', 594, 595, 'count_calls', 'def count_calls(callers):\n    """Sum the caller statistics to get total number of calls received."""\n'),
    ('stdlib/pstats.py', 605, 605, 'f8', 'def f8(x):\n'),
    ('stdlib/pty.py', 26, 28, 'openpty', 'def openpty():\n    """openpty() -> (master_fd, slave_fd)\n    Open a pty master/slave pair, using os.openpty() if possible."""\n'),
    ('stdlib/pty.py', 38, 41, 'master_open', 'def master_open():\n    """master_open() -> (master_fd, slave_name)\n    Open a pty master and return the fd, and the filename of the slave end.\n    Deprecated, use openpty() instead."""\n'),
    ('stdlib/pty.py', 66, 70, 'slave_open', 'def slave_open(tty_name):\n    """slave_open(tty_name) -> slave_fd\n    Open the pty slave and acquire the controlling terminal, returning\n    opened filedescriptor.\n    Deprecated, use openpty() instead."""\n'),
    ('stdlib/pty.py', 84, 86, 'fork', 'def fork():\n    """fork() -> (pid, master_fd)\n    Fork and make the child a session leader with a controlling terminal."""\n'),
    ('stdlib/pty.py', 163, 164, 'spawn', 'def spawn(argv, master_read=_read, stdin_read=_read):\n    """Create a spawned process."""\n'),
    ('stdlib/py_compile.py', 79, 123, 'compile', 'def compile(file, cfile=None, dfile=None, doraise=False, optimize=-1,\n            invalidation_mode=None, quiet=0):\n    """Byte-compile one Python source file to Python bytecode.\n\n    :param file: The source file name.\n    :param cfile: The target byte compiled file name.  When not given, this\n        defaults to the PEP 3147/PEP 488 location.\n    :param dfile: Purported file name, i.e. the file name that shows up in\n        error messages.  Defaults to the source file name.\n    :param doraise: Flag indicating whether or not an exception should be\n        raised when a compile error is found.  If an exception occurs and this\n        flag is set to False, a string indicating the nature of the exception\n        will be printed, and the function will return to the caller. If an\n        exception occurs and this flag is set to True, a PyCompileError\n        exception will be raised.\n    :param optimize: The optimization level for the compiler.  Valid values\n        are -1, 0, 1 and 2.  A value of -1 means to use the optimization\n        level of the current interpreter, as given by -O command line options.\n    :param invalidation_mode:\n    :param quiet: Return full output with False or 0, errors only with 1,\n        and no output with 2.\n\n    :return: Path to the resulting byte compiled file.\n\n    Note that it isn\'t necessary to byte-compile Python modules for\n    execution efficiency -- Python itself byte-compiles a module when\n    it is loaded, and if it can, writes out the bytecode to the\n    corresponding .pyc file.\n\n    However, if a Python installation is shared between users, it is a\n    good idea to byte-compile all modules upon installation, since\n    other users may not be able to write in the source directories,\n    and thus they won\'t be able to write the .pyc file, and then\n    they would be byte-compiling every module each time it is loaded.\n    This can slow down program start-up considerably.\n\n    See compileall.py for a script/module that uses this module to\n    byte-compile all installed files (or all files in selected\n    directories).\n\n    Do note that FileExistsError is raised if cfile ends up pointing at a\n    non-regular file or symlink. Because the compilation uses a file renaming,\n    the resulting file would be regular and thus not the same type of file as\n    it was previously.\n    """\n'),
    ('stdlib/py_compile.py', 176, 176, 'main', 'def main():\n'),
    ('stdlib/pyclbr.py', 100, 104, 'readmodule', 'def readmodule(module, path=None):\n    """Return Class objects for the top-level classes in module.\n\n    This is the original interface, before Functions were added.\n    """\n'),
    ('stdlib/pyclbr.py', 112, 118, 'readmodule_ex', 'def readmodule_ex(module, path=None):\n    """Return a dictionary with all functions and classes in module.\n\n    Search for module in PATH + sys.path.\n    If possible, include imported superclasses.\n    Do this by reading source, without importing (and executing) it.\n    """\n'),
    ('stdlib/pydoc.py', 82, 83, 'pathdirs', 'def pathdirs():\n    """Convert sys.path into a list of absolute, existing, unique paths."""\n'),
    ('stdlib/pydoc.py', 189, 190, 'getdoc', 'def getdoc(object):\n    """Get the doc string or comments for an object."""\n'),
    ('stdlib/pydoc.py', 194, 195, 'splitdoc', 'def splitdoc(doc):\n    """Split a doc string into a synopsis line (if any) and the rest."""\n'),
    ('stdlib/pydoc.py', 203, 204, 'classname', 'def classname(object, modname):\n    """Get a class name and qualify it with a module name if necessary."""\n'),
    ('stdlib/pydoc.py', 210, 211, 'isdata', 'def isdata(object):\n    """Check if an object is of a type that probably means it\'s data."""\n'),
    ('stdlib/pydoc.py', 216, 217, 'replace', 'def replace(text, *pairs):\n    """Do a series of global replacements on a string."""\n'),
    ('stdlib/pydoc.py', 223, 224, 'cram', 'def cram(text, maxlen):\n    """Omit part of a string if needed to make it fit in a maximum length."""\n'),
    ('stdlib/pydoc.py', 232, 233, 'stripid', 'def stripid(text):\n    """Remove the hexadecimal id from a Python object representation."""\n'),
    ('stdlib/pydoc.py', 250, 250, 'allmethods', 'def allmethods(cl):\n'),
    ('stdlib/pydoc.py', 277, 278, 'visiblename', 'def visiblename(name, all=None, obj=None):\n    """Decide whether to show documentation on a variable."""\n'),
    ('stdlib/pydoc.py', 297, 298, 'classify_class_attrs', 'def classify_class_attrs(object):\n    """Wrap inspect.classify_class_attrs, with fixup for data descriptors."""\n'),
    ('stdlib/pydoc.py', 308, 309, 'sort_attributes', "def sort_attributes(attrs, object):\n    'Sort the attrs list in-place by _fields and then alphabetically by name'\n"),
    ('stdlib/pydoc.py', 322, 323, 'ispackage', 'def ispackage(path):\n    """Guess whether a path refers to a package directory."""\n'),
    ('stdlib/pydoc.py', 330, 330, 'source_synopsis', 'def source_synopsis(file):\n'),
    ('stdlib/pydoc.py', 347, 348, 'synopsis', 'def synopsis(filename, cache={}):\n    """Get the one-line summary out of a module file."""\n'),
    ('stdlib/pydoc.py', 396, 397, 'importfile', 'def importfile(path):\n    """Import a Python source file or compiled file given its path."""\n'),
    ('stdlib/pydoc.py', 414, 421, 'safeimport', 'def safeimport(path, forceload=0, cache={}):\n    """Import a module; handle errors; return None if the module isn\'t found.\n\n    If the module *is* found but an exception occurs, it\'s wrapped in an\n    ErrorDuringImport exception and reraised.  Unlike __import__, if a\n    package path is specified, the module at the end of the path is returned,\n    not the package at the beginning.  If the optional \'forceload\' argument\n    is 1, we reload the module from disk (unless it\'s a dynamic extension)."""\n'),
    ('stdlib/pydoc.py', 1554, 1555, 'pager', 'def pager(text):\n    """The first time this is called, determine what kind of pager to use."""\n'),
    ('stdlib/pydoc.py', 1560, 1561, 'getpager', 'def getpager():\n    """Decide what method to use for paging through text."""\n'),
    ('stdlib/pydoc.py', 1594, 1595, 'plain', 'def plain(text):\n    """Remove boldface formatting from text."""\n'),
    ('stdlib/pydoc.py', 1598, 1599, 'pipepager', 'def pipepager(text, cmd):\n    """Page through text by feeding it to another program."""\n'),
    ('stdlib/pydoc.py', 1622, 1623, 'tempfilepager', 'def tempfilepager(text, cmd):\n    """Page through text by invoking a program on a temporary file."""\n'),
    ('stdlib/pydoc.py', 1639, 1640, 'ttypager', 'def ttypager(text):\n    """Page through text on a text terminal."""\n'),
    ('stdlib/pydoc.py', 1683, 1684, 'plainpager', 'def plainpager(text):\n    """Simply print unformatted text.  This is the ultimate fallback."""\n'),
    ('stdlib/pydoc.py', 1687, 1688, 'describe', 'def describe(thing):\n    """Produce a short description of the given thing."""\n'),
    ('stdlib/pydoc.py', 1714, 1715, 'locate', 'def locate(path, forceload=0):\n    """Locate an object by name or dotted path, importing as necessary."""\n'),
    ('stdlib/pydoc.py', 1739, 1740, 'resolve', 'def resolve(thing, forceload=0):\n    """Given an object or a path to an object, get the object and its name."""\n'),
    ('stdlib/pydoc.py', 1753, 1755, 'render_doc', 'def render_doc(thing, title=\'Python Library Documentation: %s\', forceload=0,\n        renderer=None):\n    """Render text documentation, given an object or a path to an object."""\n'),
    ('stdlib/pydoc.py', 1780, 1782, 'doc', 'def doc(thing, title=\'Python Library Documentation: %s\', forceload=0,\n        output=None):\n    """Display text documentation, given an object or a path to an object."""\n'),
    ('stdlib/pydoc.py', 1791, 1792, 'writedoc', 'def writedoc(thing, forceload=0):\n    """Write HTML documentation to a file in the current directory."""\n'),
    ('stdlib/pydoc.py', 1802, 1803, 'writedocs', 'def writedocs(dir, pkgpath=\'\', done=None):\n    """Write out HTML documentation for all modules in a directory tree."""\n'),
    ('stdlib/pydoc.py', 2275, 2276, 'apropos', 'def apropos(key):\n    """Print all the one-line module summaries that contain a substring."""\n'),
    ('stdlib/pydoc.py', 2678, 2683, 'browse', 'def browse(port=0, *, open_browser=True, hostname=\'localhost\'):\n    """Start the enhanced pydoc web server and open a web browser.\n\n    Use port \'0\' to start the server on an arbitrary port.\n    Set open_browser to False to suppress opening a browser.\n    """\n'),
    ('stdlib/pydoc.py', 2715, 2715, 'ispath', 'def ispath(x):\n'),
    ('stdlib/pydoc.py', 2756, 2757, 'cli', 'def cli():\n    """Command-line interface (looks at sys.argv to decide what to do)."""\n'),
    ('stdlib/quopri.py', 21, 27, 'needsquoting', 'def needsquoting(c, quotetabs, header):\n    """Decide whether a particular byte ordinal needs to be quoted.\n\n    The \'quotetabs\' flag indicates whether embedded tabs and spaces should be\n    quoted.  Note that line-ending tabs and spaces are always encoded, as per\n    RFC 1521.\n    """\n'),
    ('stdlib/quopri.py', 36, 37, 'quote', 'def quote(c):\n    """Quote a single character."""\n'),
    ('stdlib/quopri.py', 44, 51, 'encode', 'def encode(input, output, quotetabs, header=False):\n    """Read \'input\', apply quoted-printable encoding, and write to \'output\'.\n\n    \'input\' and \'output\' are binary file objects. The \'quotetabs\' flag\n    indicates whether embedded tabs and spaces should be quoted. Note that\n    line-ending tabs and spaces are always encoded, as per RFC 1521.\n    The \'header\' flag indicates whether we are encoding spaces as _ as per RFC\n    1522."""\n'),
    ('stdlib/quopri.py', 106, 106, 'encodestring', 'def encodestring(s, quotetabs=False, header=False):\n'),
    ('stdlib/quopri.py', 117, 120, 'decode', 'def decode(input, output, header=False):\n    """Read \'input\', apply quoted-printable decoding, and write to \'output\'.\n    \'input\' and \'output\' are binary file objects.\n    If \'header\' is true, decode underscore as space (per RFC 1522)."""\n'),
    ('stdlib/quopri.py', 160, 160, 'decodestring', 'def decodestring(s, header=False):\n'),
    ('stdlib/quopri.py', 172, 173, 'ishex', 'def ishex(c):\n    """Return true if the byte ordinal \'c\' is a hexadecimal digit in ASCII."""\n'),
    ('stdlib/quopri.py', 177, 178, 'unhex', 'def unhex(s):\n    """Get the integer value of a hexadecimal number."""\n'),
    ('stdlib/quopri.py', 195, 195, 'main', 'def main():\n'),
    ('stdlib/re.py', 187, 189, 'match', 'def match(pattern, string, flags=0):\n    """Try to apply the pattern at the start of the string, returning\n    a Match object, or None if no match was found."""\n'),
    ('stdlib/re.py', 192, 194, 'fullmatch', 'def fullmatch(pattern, string, flags=0):\n    """Try to apply the pattern to all of the string, returning\n    a Match object, or None if no match was found."""\n'),
    ('stdlib/re.py', 197, 199, 'search', 'def search(pattern, string, flags=0):\n    """Scan through string looking for a match to the pattern, returning\n    a Match object, or None if no match was found."""\n'),
    ('stdlib/re.py', 202, 208, 'sub', 'def sub(pattern, repl, string, count=0, flags=0):\n    """Return the string obtained by replacing the leftmost\n    non-overlapping occurrences of the pattern in string by the\n    replacement repl.  repl can be either a string or a callable;\n    if a string, backslash escapes in it are processed.  If it is\n    a callable, it\'s passed the Match object and must return\n    a replacement string to be used."""\n'),
    ('stdlib/re.py', 211, 219, 'subn', 'def subn(pattern, repl, string, count=0, flags=0):\n    """Return a 2-tuple containing (new_string, number).\n    new_string is the string obtained by replacing the leftmost\n    non-overlapping occurrences of the pattern in the source\n    string by the replacement repl.  number is the number of\n    substitutions that were made. repl can be either a string or a\n    callable; if a string, backslash escapes in it are processed.\n    If it is a callable, it\'s passed the Match object and must\n    return a replacement string to be used."""\n'),
    ('stdlib/re.py', 222, 229, 'split', 'def split(pattern, string, maxsplit=0, flags=0):\n    """Split the source string by the occurrences of the pattern,\n    returning a list containing the resulting substrings.  If\n    capturing parentheses are used in pattern, then the text of all\n    groups in the pattern are also returned as part of the resulting\n    list.  If maxsplit is nonzero, at most maxsplit splits occur,\n    and the remainder of the string is returned as the final element\n    of the list."""\n'),
    ('stdlib/re.py', 232, 239, 'findall', 'def findall(pattern, string, flags=0):\n    """Return a list of all non-overlapping matches in the string.\n\n    If one or more capturing groups are present in the pattern, return\n    a list of groups; this will be a list of tuples if the pattern\n    has more than one group.\n\n    Empty matches are included in the result."""\n'),
    ('stdlib/re.py', 242, 246, 'finditer', 'def finditer(pattern, string, flags=0):\n    """Return an iterator over all non-overlapping matches in the\n    string.  For each match, the iterator returns a Match object.\n\n    Empty matches are included in the result."""\n'),
    ('stdlib/re.py', 249, 250, 'compile', 'def compile(pattern, flags=0):\n    "Compile a regular expression pattern, returning a Pattern object."\n'),
    ('stdlib/re.py', 253, 254, 'purge', 'def purge():\n    "Clear the regular expression caches"\n'),
    ('stdlib/re.py', 258, 259, 'template', 'def template(pattern, flags=0):\n    "Compile a template pattern, returning a Pattern object"\n'),
    ('stdlib/re.py', 269, 272, 'escape', 'def escape(pattern):\n    """\n    Escape special characters in a string.\n    """\n'),
    ('stdlib/reprlib.py', 9, 10, 'recursive_repr', "def recursive_repr(fillvalue='...'):\n    'Decorator to make a repr function return fillvalue for a recursive call'\n"),
    ('stdlib/rlcompleter.py', 202, 202, 'get_class_members', 'def get_class_members(klass):\n'),
    ('stdlib/runpy.py', 199, 219, 'run_module', 'def run_module(mod_name, init_globals=None,\n               run_name=None, alter_sys=False):\n    """Execute a module\'s code without importing it.\n\n       mod_name -- an absolute module name or package name.\n\n       Optional arguments:\n       init_globals -- dictionary used to pre-populate the module’s\n       globals dictionary before the code is executed.\n\n       run_name -- if not None, this will be used for setting __name__;\n       otherwise, __name__ will be set to mod_name + \'__main__\' if the\n       named module is a package and to just mod_name otherwise.\n\n       alter_sys -- if True, sys.argv[0] is updated with the value of\n       __file__ and sys.modules[__name__] is updated with a temporary\n       module object for the module being executed. Both are\n       restored to their original values before the function returns.\n\n       Returns the resulting module globals dictionary.\n    """\n'),
    ('stdlib/runpy.py', 260, 274, 'run_path', 'def run_path(path_name, init_globals=None, run_name=None):\n    """Execute code located at the specified filesystem location.\n\n       path_name -- filesystem location of a Python script, zipfile,\n       or directory containing a top level __main__.py script.\n\n       Optional arguments:\n       init_globals -- dictionary used to pre-populate the module’s\n       globals dictionary before the code is executed.\n\n       run_name -- if not None, this will be used to set __name__;\n       otherwise, \'<run_path>\' will be used for __name__.\n\n       Returns the resulting module globals dictionary.\n    """\n'),
    ('stdlib/secrets.py', 26, 27, 'randbelow', 'def randbelow(exclusive_upper_bound):\n    """Return a random int in the range [0, n)."""\n'),
    ('stdlib/secrets.py', 34, 43, 'token_bytes', 'def token_bytes(nbytes=None):\n    """Return a random byte string containing *nbytes* bytes.\n\n    If *nbytes* is ``None`` or not supplied, a reasonable\n    default is used.\n\n    >>> token_bytes(16)  #doctest:+SKIP\n    b\'\\\\xebr\\\\x17D*t\\\\xae\\\\xd4\\\\xe3S\\\\xb6\\\\xe2\\\\xebP1\\\\x8b\'\n\n    """\n'),
    ('stdlib/secrets.py', 48, 58, 'token_hex', 'def token_hex(nbytes=None):\n    """Return a random text string, in hexadecimal.\n\n    The string has *nbytes* random bytes, each byte converted to two\n    hex digits.  If *nbytes* is ``None`` or not supplied, a reasonable\n    default is used.\n\n    >>> token_hex(16)  #doctest:+SKIP\n    \'f9bf78b9a18ce6d46a0cd2b0b86df9da\'\n\n    """\n'),
    ('stdlib/secrets.py', 61, 70, 'token_urlsafe', 'def token_urlsafe(nbytes=None):\n    """Return a random URL-safe text string, in Base64 encoding.\n\n    The string has *nbytes* random bytes.  If *nbytes* is ``None``\n    or not supplied, a reasonable default is used.\n\n    >>> token_urlsafe(16)  #doctest:+SKIP\n    \'Drmhze6EPcv0fN_81Bj-nA\'\n\n    """\n'),
    ('stdlib/shelve.py', 230, 241, 'open', 'def open(filename, flag=\'c\', protocol=None, writeback=False):\n    """Open a persistent dictionary for reading and writing.\n\n    The filename parameter is the base filename for the underlying\n    database.  As a side-effect, an extension may be added to the\n    filename and more than one file may be created.  The optional flag\n    parameter has the same interpretation as the flag parameter of\n    dbm.open(). The optional protocol parameter specifies the\n    version of the pickle protocol.\n\n    See the module\'s __doc__ string for an overview of the interface.\n    """\n'),
    ('stdlib/shlex.py', 305, 306, 'split', 'def split(s, comments=False, posix=True):\n    """Split the string *s* using shell-like syntax."""\n'),
    ('stdlib/shlex.py', 318, 319, 'join', 'def join(split_command):\n    """Return a shell-escaped string from *split_command*."""\n'),
    ('stdlib/shlex.py', 325, 326, 'quote', 'def quote(s):\n    """Return a shell-escaped version of the string *s*."""\n'),
    ('stdlib/shutil.py', 187, 188, 'copyfileobj', 'def copyfileobj(fsrc, fdst, length=0):\n    """copy data from file-like object fsrc to file-like object fdst"""\n'),
    ('stdlib/shutil.py', 224, 230, 'copyfile', 'def copyfile(src, dst, *, follow_symlinks=True):\n    """Copy data from src to dst in the most efficient way possible.\n\n    If follow_symlinks is not set and src is a symbolic link, a new\n    symlink will be created instead of copying the file it points to.\n\n    """\n'),
    ('stdlib/shutil.py', 288, 295, 'copymode', 'def copymode(src, dst, *, follow_symlinks=True):\n    """Copy mode bits from src to dst.\n\n    If follow_symlinks is not set, symlinks aren\'t followed if and only\n    if both `src` and `dst` are symlinks.  If `lchmod` isn\'t available\n    (e.g. Linux) this method does nothing.\n\n    """\n'),
    ('stdlib/shutil.py', 337, 348, 'copystat', 'def copystat(src, dst, *, follow_symlinks=True):\n    """Copy file metadata\n\n    Copy the permission bits, last access time, last modification time, and\n    flags from `src` to `dst`. On Linux, copystat() also copies the "extended\n    attributes" where possible. The file contents, owner, and group are\n    unaffected. `src` and `dst` are path-like objects or path names given as\n    strings.\n\n    If the optional flag `follow_symlinks` is not set, symlinks aren\'t\n    followed if and only if both `src` and `dst` are symlinks.\n    """\n'),
    ('stdlib/shutil.py', 403, 414, 'copy', 'def copy(src, dst, *, follow_symlinks=True):\n    """Copy data and mode bits ("cp src dst"). Return the file\'s destination.\n\n    The destination may be a directory.\n\n    If follow_symlinks is false, symlinks won\'t be followed. This\n    resembles GNU\'s "cp -P src dst".\n\n    If source and destination are the same file, a SameFileError will be\n    raised.\n\n    """\n'),
    ('stdlib/shutil.py', 421, 431, 'copy2', 'def copy2(src, dst, *, follow_symlinks=True):\n    """Copy data and metadata. Return the file\'s destination.\n\n    Metadata is copied with copystat(). Please see the copystat function\n    for more information.\n\n    The destination may be a directory.\n\n    If follow_symlinks is false, symlinks won\'t be followed. This\n    resembles GNU\'s "cp -P src dst".\n    """\n'),
    ('stdlib/shutil.py', 438, 442, 'ignore_patterns', 'def ignore_patterns(*patterns):\n    """Function that can be used as copytree() ignore parameter.\n\n    Patterns is a sequence of glob-style patterns\n    that are used to exclude files"""\n'),
    ('stdlib/shutil.py', 516, 555, 'copytree', 'def copytree(src, dst, symlinks=False, ignore=None, copy_function=copy2,\n             ignore_dangling_symlinks=False, dirs_exist_ok=False):\n    """Recursively copy a directory tree and return the destination directory.\n\n    If exception(s) occur, an Error is raised with a list of reasons.\n\n    If the optional symlinks flag is true, symbolic links in the\n    source tree result in symbolic links in the destination tree; if\n    it is false, the contents of the files pointed to by symbolic\n    links are copied. If the file pointed by the symlink doesn\'t\n    exist, an exception will be added in the list of errors raised in\n    an Error exception at the end of the copy process.\n\n    You can set the optional ignore_dangling_symlinks flag to true if you\n    want to silence this exception. Notice that this has no effect on\n    platforms that don\'t support os.symlink.\n\n    The optional ignore argument is a callable. If given, it\n    is called with the `src` parameter, which is the directory\n    being visited by copytree(), and `names` which is the list of\n    `src` contents, as returned by os.listdir():\n\n        callable(src, names) -> ignored_names\n\n    Since copytree() is called recursively, the callable will be\n    called once for each directory that is copied. It returns a\n    list of names relative to the `src` directory that should\n    not be copied.\n\n    The optional copy_function argument is a callable that will be used\n    to copy each file. It will be called with the source path and the\n    destination path as arguments. By default, copy2() is used, but any\n    function that supports the same signature (like copy()) can be used.\n\n    If dirs_exist_ok is false (the default) and `dst` already exists, a\n    `FileExistsError` is raised. If `dirs_exist_ok` is true, the copying\n    operation will continue if it encounters existing directories, and files\n    within the `dst` tree will be overwritten by corresponding files from the\n    `src` tree.\n    """\n'),
    ('stdlib/shutil.py', 688, 698, 'rmtree', 'def rmtree(path, ignore_errors=False, onerror=None):\n    """Recursively delete a directory tree.\n\n    If ignore_errors is set, errors are ignored; otherwise, if onerror\n    is set, it is called to handle the error with arguments (func,\n    path, exc_info) where func is platform and implementation dependent;\n    path is the argument to that function that caused it to fail; and\n    exc_info is a tuple returned by sys.exc_info().  If ignore_errors\n    is false and onerror is None, an exception is raised.\n\n    """\n'),
    ('stdlib/shutil.py', 774, 799, 'move', 'def move(src, dst, copy_function=copy2):\n    """Recursively move a file or directory to another location. This is\n    similar to the Unix "mv" command. Return the file or directory\'s\n    destination.\n\n    If the destination is a directory or a symlink to a directory, the source\n    is moved inside the directory. The destination path must not already\n    exist.\n\n    If the destination already exists but is not a directory, it may be\n    overwritten depending on os.rename() semantics.\n\n    If the destination is on our current filesystem, then rename() is used.\n    Otherwise, src is copied to the destination and then removed. Symlinks are\n    recreated under the new name if os.rename() fails because of cross\n    filesystem renames.\n\n    The optional `copy_function` argument is a callable that will be used\n    to copy the source or it will be delegated to `copytree`.\n    By default, copy2() is used, but any function that supports the same\n    signature (like copy()) can be used.\n\n    A lot more could be done here...  A look at a mv.c shows a lot of\n    the issues this implementation glosses over.\n\n    """\n'),
    ('stdlib/shutil.py', 1040, 1044, 'get_archive_formats', 'def get_archive_formats():\n    """Returns a list of supported formats for archiving and unarchiving.\n\n    Each element of the returned sequence is a tuple (name, description)\n    """\n'),
    ('stdlib/shutil.py', 1050, 1058, 'register_archive_format', 'def register_archive_format(name, function, extra_args=None, description=\'\'):\n    """Registers an archive format.\n\n    name is the name of the format. function is the callable that will be\n    used to create archives. If provided, extra_args is a sequence of\n    (name, value) tuples that will be passed as arguments to the callable.\n    description can be provided to describe the format, and will be returned\n    by the get_archive_formats() function.\n    """\n'),
    ('stdlib/shutil.py', 1071, 1071, 'unregister_archive_format', 'def unregister_archive_format(name):\n'),
    ('stdlib/shutil.py', 1074, 1091, 'make_archive', 'def make_archive(base_name, format, root_dir=None, base_dir=None, verbose=0,\n                 dry_run=0, owner=None, group=None, logger=None):\n    """Create an archive file (eg. zip or tar).\n\n    \'base_name\' is the name of the file to create, minus any format-specific\n    extension; \'format\' is the archive format: one of "zip", "tar", "gztar",\n    "bztar", or "xztar".  Or any other registered format.\n\n    \'root_dir\' is a directory that will be the root directory of the\n    archive; ie. we typically chdir into \'root_dir\' before creating the\n    archive.  \'base_dir\' is the directory where we start archiving from;\n    ie. \'base_dir\' will be the common prefix of all files and\n    directories in the archive.  \'root_dir\' and \'base_dir\' both default\n    to the current directory.  Returns the name of the archive file.\n\n    \'owner\' and \'group\' are used when creating a tar archive. By default,\n    uses the current owner and group.\n    """\n'),
    ('stdlib/shutil.py', 1134, 1139, 'get_unpack_formats', 'def get_unpack_formats():\n    """Returns a list of supported formats for unpacking.\n\n    Each element of the returned sequence is a tuple\n    (name, extensions, description)\n    """\n'),
    ('stdlib/shutil.py', 1163, 1179, 'register_unpack_format', 'def register_unpack_format(name, extensions, function, extra_args=None,\n                           description=\'\'):\n    """Registers an unpack format.\n\n    `name` is the name of the format. `extensions` is a list of extensions\n    corresponding to the format.\n\n    `function` is the callable that will be\n    used to unpack archives. The callable will receive archives to unpack.\n    If it\'s unable to handle an archive, it needs to raise a ReadError\n    exception.\n\n    If provided, `extra_args` is a sequence of\n    (name, value) tuples that will be passed as arguments to the callable.\n    description can be provided to describe the format, and will be returned\n    by the get_unpack_formats() function.\n    """\n'),
    ('stdlib/shutil.py', 1185, 1186, 'unregister_unpack_format', 'def unregister_unpack_format(name):\n    """Removes the pack format from the registry."""\n'),
    ('stdlib/shutil.py', 1268, 1285, 'unpack_archive', 'def unpack_archive(filename, extract_dir=None, format=None, *, filter=None):\n    """Unpack an archive.\n\n    `filename` is the name of the archive.\n\n    `extract_dir` is the name of the target directory, where the archive\n    is unpacked. If not provided, the current working directory is used.\n\n    `format` is the archive format: one of "zip", "tar", "gztar", "bztar",\n    or "xztar".  Or any other registered format.  If not provided,\n    unpack_archive will use the filename extension and see if an unpacker\n    was registered for that extension.\n\n    In case none is found, a ValueError is raised.\n\n    If `filter` is given, it is passed to the underlying\n    extraction function.\n    """\n'),
    ('stdlib/shutil.py', 1353, 1358, 'chown', 'def chown(path, user=None, group=None):\n    """Change owner user and group of the given path.\n\n    user and group can be the uid/gid or the user/group names, and in that case,\n    they are converted to their respective uid/gid.\n    """\n'),
    ('stdlib/shutil.py', 1385, 1403, 'get_terminal_size', 'def get_terminal_size(fallback=(80, 24)):\n    """Get the size of the terminal window.\n\n    For each of the two dimensions, the environment variable, COLUMNS\n    and LINES respectively, is checked. If the variable is defined and\n    the value is a positive integer, it is used.\n\n    When COLUMNS or LINES is not defined, which is the common case,\n    the terminal connected to sys.__stdout__ is queried\n    by invoking os.get_terminal_size.\n\n    If the terminal size cannot be successfully queried, either because\n    the system doesn\'t support querying, or because we are not\n    connected to a terminal, the value given in fallback parameter\n    is used. Fallback defaults to (80, 24) which is the default\n    size used by many terminal emulators.\n\n    The value returned is a named tuple of type os.terminal_size.\n    """\n'),
    ('stdlib/shutil.py', 1439, 1448, 'which', 'def which(cmd, mode=os.F_OK | os.X_OK, path=None):\n    """Given a command, mode, and a PATH string, return the path which\n    conforms to the given mode on the PATH, or None if there is no such\n    file.\n\n    `mode` defaults to os.F_OK | os.X_OK. `path` defaults to the result\n    of os.environ.get("PATH"), or can be overridden with a custom search\n    path.\n\n    """\n'),
    ('stdlib/signal.py', 55, 55, 'signal', 'def signal(signalnum, handler):\n'),
    ('stdlib/signal.py', 61, 61, 'getsignal', 'def getsignal(signalnum):\n'),
    ('stdlib/site.py', 96, 96, 'makepath', 'def makepath(*paths):\n'),
    ('stdlib/site.py', 105, 106, 'abs_paths', 'def abs_paths():\n    """Set all module __file__ and __cached__ attributes to an absolute path"""\n'),
    ('stdlib/site.py', 128, 130, 'removeduppaths', 'def removeduppaths():\n    """ Remove duplicate entries from sys.path along with making them\n    absolute"""\n'),
    ('stdlib/site.py', 160, 164, 'addpackage', 'def addpackage(sitedir, name, known_paths):\n    """Process a .pth file within the site-packages directory:\n       For each line in the file, either combine it with sitedir to a path\n       and add that to known_paths, or execute it if it starts with \'import \'.\n    """\n'),
    ('stdlib/site.py', 207, 209, 'addsitedir', 'def addsitedir(sitedir, known_paths=None):\n    """Add \'sitedir\' argument to sys.path if missing and handle .pth files in\n    \'sitedir\'"""\n'),
    ('stdlib/site.py', 232, 241, 'check_enableusersite', 'def check_enableusersite():\n    """Check if user site directory is safe for inclusion\n\n    The function tests for the command line flag (including environment var),\n    process uid/gid equal to effective uid/gid.\n\n    None: Disabled for security reasons\n    False: Disabled by user (command line option)\n    True: Safe and enabled\n    """\n'),
    ('stdlib/site.py', 301, 307, 'getuserbase', 'def getuserbase():\n    """Returns the `user base` directory path.\n\n    The `user base` directory can be used to store data. If the global\n    variable ``USER_BASE`` is not initialized yet, this function will also set\n    it.\n    """\n'),
    ('stdlib/site.py', 314, 319, 'getusersitepackages', 'def getusersitepackages():\n    """Returns the user-specific site-packages directory path.\n\n    If the global variable ``USER_SITE`` is not initialized yet, this\n    function will also set it.\n    """\n'),
    ('stdlib/site.py', 331, 336, 'addusersitepackages', 'def addusersitepackages(known_paths):\n    """Add a per user site-package to sys.path\n\n    Each user has its own python directory with site-packages in the\n    home directory.\n    """\n'),
    ('stdlib/site.py', 346, 352, 'getsitepackages', 'def getsitepackages(prefixes=None):\n    """Returns a list containing all global site-packages directories.\n\n    For each directory present in ``prefixes`` (or the global ``PREFIXES``),\n    this function will find its `site-packages` subdirectory depending on the\n    system environment, and will return a list of full paths.\n    """\n'),
    ('stdlib/site.py', 382, 383, 'addsitepackages', 'def addsitepackages(known_paths, prefixes=None):\n    """Add site-packages to sys.path"""\n'),
    ('stdlib/site.py', 391, 397, 'setquit', 'def setquit():\n    """Define new builtins \'quit\' and \'exit\'.\n\n    These are objects which make the interpreter exit when called.\n    The repr of each object contains a hint at how it works.\n\n    """\n'),
    ('stdlib/site.py', 407, 408, 'setcopyright', 'def setcopyright():\n    """Set \'copyright\' and \'credits\' in builtins"""\n'),
    ('stdlib/site.py', 431, 431, 'sethelper', 'def sethelper():\n'),
    ('stdlib/site.py', 434, 442, 'enablerlcompleter', 'def enablerlcompleter():\n    """Enable default readline configuration on interactive prompts, by\n    registering a sys.__interactivehook__.\n\n    If the readline module can be imported, the hook will set the Tab key\n    as completion key and register ~/.python_history as history file.\n    This can be overridden in the sitecustomize or usercustomize module,\n    or in a PYTHONSTARTUP file.\n    """\n'),
    ('stdlib/site.py', 493, 493, 'venv', 'def venv(known_paths):\n'),
    ('stdlib/site.py', 545, 546, 'execsitecustomize', 'def execsitecustomize():\n    """Run custom site specific code, if available."""\n'),
    ('stdlib/site.py', 565, 566, 'execusercustomize', 'def execusercustomize():\n    """Run custom user specific code, if available."""\n'),
    ('stdlib/site.py', 585, 590, 'main', 'def main():\n    """Add standard site-specific directories to the module search path.\n\n    This function is called automatically when this module is imported,\n    unless the python interpreter was started with the -S flag.\n    """\n'),
    ('stdlib/smtpd.py', 124, 124, 'usage', "def usage(code, msg=''):\n"),
    ('stdlib/smtpd.py', 884, 884, 'parseargs', 'def parseargs():\n'),
    ('stdlib/smtplib.py', 146, 150, 'quoteaddr', 'def quoteaddr(addrstring):\n    """Quote a subset of the email addresses defined by RFC 821.\n\n    Should be able to handle anything email.utils.parseaddr can handle.\n    """\n'),
    ('stdlib/smtplib.py', 167, 172, 'quotedata', 'def quotedata(data):\n    """Quote data for email.\n\n    Double leading \'.\', and change Unix newline \'\\\\n\', or Mac \'\\\\r\' into\n    internet CRLF end-of-line.\n    """\n'),
    ('stdlib/sndhdr.py', 52, 53, 'what', 'def what(filename):\n    """Guess the type of a sound file."""\n'),
    ('stdlib/sndhdr.py', 58, 59, 'whathdr', 'def whathdr(filename):\n    """Recognize sound headers."""\n'),
