    ('stdlib/sndhdr.py', 235, 235, 'testall', 'def testall(list, recursive, toplevel):\n'),
    ('stdlib/socket.py', 539, 544, 'fromfd', 'def fromfd(fd, family, type, proto=0):\n    """ fromfd(fd, family, type[, proto]) -> socket object\n\n    Create a socket object from a duplicate of the given file\n    descriptor.  The remaining arguments are the same as for socket().\n    """\n'),
    ('stdlib/socket.py', 779, 788, 'getfqdn', 'def getfqdn(name=\'\'):\n    """Get fully qualified domain name from name.\n\n    An empty argument is interpreted as meaning the local host.\n\n    First the hostname returned by gethostbyaddr() is checked, then\n    possibly existing aliases. In case no FQDN is available and `name`\n    was given, it is returned unchanged. If `name` was empty, \'0.0.0.0\' or \'::\',\n    hostname from gethostname() is returned.\n    """\n'),
    ('stdlib/socket.py', 808, 820, 'create_connection', 'def create_connection(address, timeout=_GLOBAL_DEFAULT_TIMEOUT,\n                      source_address=None):\n    """Connect to *address* and return the socket object.\n\n    Convenience function.  Connect to *address* (a 2-tuple ``(host,\n    port)``) and return the socket object.  Passing the optional\n    *timeout* parameter will set the timeout on the socket instance\n    before attempting to connect.  If no *timeout* is supplied, the\n    global default timeout setting returned by :func:`getdefaulttimeout`\n    is used.  If *source_address* is set it must be a tuple of (host, port)\n    for the socket to bind as a source address before making the connection.\n    A host of \'\' or port 0 tells the OS to use the default.\n    """\n'),
    ('stdlib/socket.py', 853, 856, 'has_dualstack_ipv6', 'def has_dualstack_ipv6():\n    """Return True if the platform supports creating a SOCK_STREAM socket\n    which can handle both AF_INET and AF_INET6 (IPv4 / IPv6) connections.\n    """\n'),
    ('stdlib/socket.py', 869, 887, 'create_server', 'def create_server(address, *, family=AF_INET, backlog=None, reuse_port=False,\n                  dualstack_ipv6=False):\n    """Convenience function which creates a SOCK_STREAM type socket\n    bound to *address* (a 2-tuple (host, port)) and return the socket\n    object.\n\n    *family* should be either AF_INET or AF_INET6.\n    *backlog* is the queue size passed to socket.listen().\n    *reuse_port* dictates whether to use the SO_REUSEPORT socket option.\n    *dualstack_ipv6*: if true and the platform supports it, it will\n    create an AF_INET6 socket able to accept both IPv4 or IPv6\n    connections. When false it will explicitly disable this option on\n    platforms that enable it by default (e.g. Linux).\n\n    >>> with create_server((\'\', 8000)) as server:\n    ...     while True:\n    ...         conn, addr = server.accept()\n    ...         # handle new connection\n    """\n'),
    ('stdlib/socket.py', 938, 951, 'getaddrinfo', 'def getaddrinfo(host, port, family=0, type=0, proto=0, flags=0):\n    """Resolve host and port into list of address info entries.\n\n    Translate the host/port argument into a sequence of 5-tuples that contain\n    all the necessary arguments for creating a socket connected to that service.\n    host is a domain name, a string representation of an IPv4/v6 address or\n    None. port is a string service name such as \'http\', a numeric port number or\n    None. By passing None as the value of host and port, you can pass NULL to\n    the underlying C API.\n\n    The family, type and proto arguments can be optionally specified in order to\n    narrow the list of addresses returned. Passing zero as a value for each of\n    these arguments selects the full range of results.\n    """\n'),
    ('stdlib/sre_compile.py', 619, 619, 'isstring', 'def isstring(obj):\n'),
    ('stdlib/sre_compile.py', 640, 640, 'dis', 'def dis(code):\n'),
    ('stdlib/sre_compile.py', 783, 785, 'compile', 'def compile(p, flags=0):\n    # internal: convert pattern list to internal format\n\n'),
    ('stdlib/sre_parse.py', 928, 929, 'fix_flags', 'def fix_flags(src, flags):\n    # Check and fix flags according to the type of pattern (str or bytes)\n'),
    ('stdlib/sre_parse.py', 944, 946, 'parse', "def parse(str, flags=0, state=None):\n    # parse 're' pattern into list of (opcode, argument) tuples\n\n"),
    ('stdlib/sre_parse.py', 981, 983, 'parse_template', "def parse_template(source, state):\n    # parse 're' replacement string into list of literals and\n    # group references\n"),
    ('stdlib/sre_parse.py', 1066, 1066, 'expand_template', 'def expand_template(template, match):\n'),
    ('stdlib/ssl.py', 372, 384, 'match_hostname', 'def match_hostname(cert, hostname):\n    """Verify that *cert* (in decoded format as returned by\n    SSLSocket.getpeercert()) matches the *hostname*.  RFC 2818 and RFC 6125\n    rules are followed.\n\n    The function matches IP addresses rather than dNSNames if hostname is a\n    valid ipaddress string. IPv4 addresses are supported on all platforms.\n    IPv6 addresses are supported on platforms with IPv6 support (AF_INET6\n    and inet_pton).\n\n    CertificateError is raised on failure. On success, the function\n    returns nothing.\n    """\n'),
    ('stdlib/ssl.py', 438, 440, 'get_default_verify_paths', 'def get_default_verify_paths():\n    """Return paths to default cafile and capath.\n    """\n'),
    ('stdlib/ssl.py', 741, 748, 'create_default_context', 'def create_default_context(purpose=Purpose.SERVER_AUTH, *, cafile=None,\n                           capath=None, cadata=None):\n    """Create a SSLContext object with default settings.\n\n    NOTE: The protocol and settings may change anytime without prior\n          deprecation. The values represent a fair balance between maximum\n          compatibility and security.\n    """\n'),
    ('stdlib/ssl.py', 1418, 1423, 'wrap_socket', 'def wrap_socket(sock, keyfile=None, certfile=None,\n                server_side=False, cert_reqs=CERT_NONE,\n                ssl_version=PROTOCOL_TLS, ca_certs=None,\n                do_handshake_on_connect=True,\n                suppress_ragged_eofs=True,\n                ciphers=None):\n'),
    ('stdlib/ssl.py', 1450, 1459, 'cert_time_to_seconds', 'def cert_time_to_seconds(cert_time):\n    """Return the time in seconds since the Epoch, given the timestring\n    representing the "notBefore" or "notAfter" date from a certificate\n    in ``"%b %d %H:%M:%S %Y %Z"`` strptime format (C locale).\n\n    "notBefore" or "notAfter" dates must use UTC (RFC 5280).\n\n    Month is one of: Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec\n    UTC should be specified as GMT (see ASN1_TIME_print())\n    """\n'),
    ('stdlib/ssl.py', 1483, 1485, 'DER_cert_to_PEM_cert', 'def DER_cert_to_PEM_cert(der_cert_bytes):\n    """Takes a certificate in binary DER format and returns the\n    PEM version of it as a string."""\n'),
    ('stdlib/ssl.py', 1493, 1495, 'PEM_cert_to_DER_cert', 'def PEM_cert_to_DER_cert(pem_cert_string):\n    """Takes a certificate in ASCII PEM format and returns the\n    DER-encoded version of it as a byte sequence"""\n'),
    ('stdlib/ssl.py', 1506, 1513, 'get_server_certificate', 'def get_server_certificate(addr, ssl_version=PROTOCOL_TLS_CLIENT,\n                           ca_certs=None, timeout=_GLOBAL_DEFAULT_TIMEOUT):\n    """Retrieve the certificate from the server at the specified address,\n    and return it as a PEM-encoded string.\n    If \'ca_certs\' is specified, validate the server cert against it.\n    If \'ssl_version\' is specified, use it in the connection attempt.\n    If \'timeout\' is specified, use it in the connection attempt.\n    """\n'),
    ('stdlib/ssl.py', 1528, 1528, 'get_protocol_name', 'def get_protocol_name(protocol_code):\n'),
    ('stdlib/stat.py', 21, 24, 'S_IMODE', 'def S_IMODE(mode):\n    """Return the portion of the file\'s mode that can be set by\n    os.chmod().\n    """\n'),
    ('stdlib/stat.py', 27, 30, 'S_IFMT', 'def S_IFMT(mode):\n    """Return the portion of the file\'s mode that describes the\n    file type.\n    """\n'),
    ('stdlib/stat.py', 50, 51, 'S_ISDIR', 'def S_ISDIR(mode):\n    """Return True if mode is from a directory."""\n'),
    ('stdlib/stat.py', 54, 55, 'S_ISCHR', 'def S_ISCHR(mode):\n    """Return True if mode is from a character special device file."""\n'),
    ('stdlib/stat.py', 58, 59, 'S_ISBLK', 'def S_ISBLK(mode):\n    """Return True if mode is from a block special device file."""\n'),
    ('stdlib/stat.py', 62, 63, 'S_ISREG', 'def S_ISREG(mode):\n    """Return True if mode is from a regular file."""\n'),
    ('stdlib/stat.py', 66, 67, 'S_ISFIFO', 'def S_ISFIFO(mode):\n    """Return True if mode is from a FIFO (named pipe)."""\n'),
    ('stdlib/stat.py', 70, 71, 'S_ISLNK', 'def S_ISLNK(mode):\n    """Return True if mode is from a symbolic link."""\n'),
    ('stdlib/stat.py', 74, 75, 'S_ISSOCK', 'def S_ISSOCK(mode):\n    """Return True if mode is from a socket."""\n'),
    ('stdlib/stat.py', 78, 79, 'S_ISDOOR', 'def S_ISDOOR(mode):\n    """Return True if mode is from a door."""\n'),
    ('stdlib/stat.py', 82, 83, 'S_ISPORT', 'def S_ISPORT(mode):\n    """Return True if mode is from an event port."""\n'),
    ('stdlib/stat.py', 86, 87, 'S_ISWHT', 'def S_ISWHT(mode):\n    """Return True if mode is from a whiteout."""\n'),
    ('stdlib/stat.py', 156, 157, 'filemode', 'def filemode(mode):\n    """Convert a file\'s mode to a string of the form \'-rwxrwxrwx\'."""\n'),
    ('stdlib/statistics.py', 308, 323, 'mean', 'def mean(data):\n    """Return the sample arithmetic mean of data.\n\n    >>> mean([1, 2, 3, 4, 4])\n    2.8\n\n    >>> from fractions import Fraction as F\n    >>> mean([F(3, 7), F(1, 21), F(5, 3), F(1, 3)])\n    Fraction(13, 21)\n\n    >>> from decimal import Decimal as D\n    >>> mean([D("0.5"), D("0.75"), D("0.625"), D("0.375")])\n    Decimal(\'0.5625\')\n\n    If ``data`` is empty, StatisticsError will be raised.\n    """\n'),
    ('stdlib/statistics.py', 334, 342, 'fmean', 'def fmean(data):\n    """Convert data to floats and compute the arithmetic mean.\n\n    This runs faster than the mean() function and it always returns a float.\n    If the input dataset is empty, it raises a StatisticsError.\n\n    >>> fmean([3.5, 4.0, 5.25])\n    4.25\n    """\n'),
    ('stdlib/statistics.py', 361, 372, 'geometric_mean', 'def geometric_mean(data):\n    """Convert data to floats and compute the geometric mean.\n\n    Raises a StatisticsError if the input dataset is empty,\n    if it contains a zero, or if it contains a negative value.\n\n    No special efforts are made to achieve exact results.\n    (However, this may change in the future.)\n\n    >>> round(geometric_mean([54, 24, 36]), 9)\n    36.0\n    """\n'),
    ('stdlib/statistics.py', 380, 402, 'harmonic_mean', 'def harmonic_mean(data, weights=None):\n    """Return the harmonic mean of data.\n\n    The harmonic mean is the reciprocal of the arithmetic mean of the\n    reciprocals of the data.  It can be used for averaging ratios or\n    rates, for example speeds.\n\n    Suppose a car travels 40 km/hr for 5 km and then speeds-up to\n    60 km/hr for another 5 km. What is the average speed?\n\n        >>> harmonic_mean([40, 60])\n        48.0\n\n    Suppose a car travels 40 km/hr for 5 km, and when traffic clears,\n    speeds-up to 60 km/hr for the remaining 30 km of the journey. What\n    is the average speed?\n\n        >>> harmonic_mean([40, 60], weights=[5, 30])\n        56.0\n\n    If ``data`` is empty, or any element is less than zero,\n    ``harmonic_mean`` will raise ``StatisticsError``.\n    """\n'),
    ('stdlib/statistics.py', 436, 448, 'median', 'def median(data):\n    """Return the median (middle value) of numeric data.\n\n    When the number of data points is odd, return the middle data point.\n    When the number of data points is even, the median is interpolated by\n    taking the average of the two middle values:\n\n    >>> median([1, 3, 5])\n    3\n    >>> median([1, 3, 5, 7])\n    4.0\n\n    """\n'),
    ('stdlib/statistics.py', 460, 471, 'median_low', 'def median_low(data):\n    """Return the low median of numeric data.\n\n    When the number of data points is odd, the middle value is returned.\n    When it is even, the smaller of the two middle values is returned.\n\n    >>> median_low([1, 3, 5])\n    3\n    >>> median_low([1, 3, 5, 7])\n    3\n\n    """\n'),
    ('stdlib/statistics.py', 482, 493, 'median_high', 'def median_high(data):\n    """Return the high median of data.\n\n    When the number of data points is odd, the middle value is returned.\n    When it is even, the larger of the two middle values is returned.\n\n    >>> median_high([1, 3, 5])\n    3\n    >>> median_high([1, 3, 5, 7])\n    5\n\n    """\n'),
    ('stdlib/statistics.py', 501, 526, 'median_grouped', 'def median_grouped(data, interval=1):\n    """Return the 50th percentile (median) of grouped continuous data.\n\n    >>> median_grouped([1, 2, 2, 3, 4, 4, 4, 4, 4, 5])\n    3.7\n    >>> median_grouped([52, 52, 53, 54])\n    52.5\n\n    This calculates the median as the 50th percentile, and should be\n    used when your data is continuous and grouped. In the above example,\n    the values 1, 2, 3, etc. actually represent the midpoint of classes\n    0.5-1.5, 1.5-2.5, 2.5-3.5, etc. The middle value falls somewhere in\n    class 3.5-4.5, and interpolation is used to estimate it.\n\n    Optional argument ``interval`` represents the class interval, and\n    defaults to 1. Changing the class interval naturally will change the\n    interpolated 50th percentile value:\n\n    >>> median_grouped([1, 3, 3, 5, 7], interval=1)\n    3.25\n    >>> median_grouped([1, 3, 3, 5, 7], interval=2)\n    3.5\n\n    This function does not check whether the data points are at least\n    ``interval`` apart.\n    """\n'),
    ('stdlib/statistics.py', 556, 578, 'mode', 'def mode(data):\n    """Return the most common data point from discrete or nominal data.\n\n    ``mode`` assumes discrete data, and returns a single value. This is the\n    standard treatment of the mode as commonly taught in schools:\n\n        >>> mode([1, 1, 2, 3, 3, 3, 3, 4])\n        3\n\n    This also works with nominal (non-numeric) data:\n\n        >>> mode(["red", "blue", "blue", "red", "green", "red", "red"])\n        \'red\'\n\n    If there are multiple modes with same frequency, return the first one\n    encountered:\n\n        >>> mode([\'red\', \'red\', \'green\', \'blue\', \'blue\'])\n        \'red\'\n\n    If *data* is empty, ``mode``, raises StatisticsError.\n\n    """\n'),
    ('stdlib/statistics.py', 586, 598, 'multimode', 'def multimode(data):\n    """Return a list of the most frequently occurring values.\n\n    Will return more than one result if there are multiple modes\n    or an empty list if *data* is empty.\n\n    >>> multimode(\'aabbbbbbbbcc\')\n    [\'b\']\n    >>> multimode(\'aabbbbccddddeeffffgg\')\n    [\'b\', \'d\', \'f\']\n    >>> multimode(\'\')\n    []\n    """\n'),
    ('stdlib/statistics.py', 641, 656, 'quantiles', 'def quantiles(data, *, n=4, method=\'exclusive\'):\n    """Divide *data* into *n* continuous intervals with equal probability.\n\n    Returns a list of (n - 1) cut points separating the intervals.\n\n    Set *n* to 4 for quartiles (the default).  Set *n* to 10 for deciles.\n    Set *n* to 100 for percentiles which gives the 99 cuts points that\n    separate *data* in to 100 equal sized groups.\n\n    The *data* can be any iterable containing sample.\n    The cut points are linearly interpolated between data points.\n\n    If *method* is set to *inclusive*, *data* is treated as population\n    data.  The minimum value is treated as the 0th percentile and the\n    maximum value is treated as the 100th percentile.\n    """\n'),
    ('stdlib/statistics.py', 725, 762, 'variance', 'def variance(data, xbar=None):\n    """Return the sample variance of data.\n\n    data should be an iterable of Real-valued numbers, with at least two\n    values. The optional argument xbar, if given, should be the mean of\n    the data. If it is missing or None, the mean is automatically calculated.\n\n    Use this function when your data is a sample from a population. To\n    calculate the variance from the entire population, see ``pvariance``.\n\n    Examples:\n\n    >>> data = [2.75, 1.75, 1.25, 0.25, 0.5, 1.25, 3.5]\n    >>> variance(data)\n    1.3720238095238095\n\n    If you have already calculated the mean of your data, you can pass it as\n    the optional second argument ``xbar`` to avoid recalculating it:\n\n    >>> m = mean(data)\n    >>> variance(data, m)\n    1.3720238095238095\n\n    This function does not check that ``xbar`` is actually the mean of\n    ``data``. Giving arbitrary values for ``xbar`` may lead to invalid or\n    impossible results.\n\n    Decimals and Fractions are supported:\n\n    >>> from decimal import Decimal as D\n    >>> variance([D("27.5"), D("30.25"), D("30.25"), D("34.5"), D("41.75")])\n    Decimal(\'31.01875\')\n\n    >>> from fractions import Fraction as F\n    >>> variance([F(1, 6), F(1, 2), F(5, 3)])\n    Fraction(67, 108)\n\n    """\n'),
    ('stdlib/statistics.py', 772, 806, 'pvariance', 'def pvariance(data, mu=None):\n    """Return the population variance of ``data``.\n\n    data should be a sequence or iterable of Real-valued numbers, with at least one\n    value. The optional argument mu, if given, should be the mean of\n    the data. If it is missing or None, the mean is automatically calculated.\n\n    Use this function to calculate the variance from the entire population.\n    To estimate the variance from a sample, the ``variance`` function is\n    usually a better choice.\n\n    Examples:\n\n    >>> data = [0.0, 0.25, 0.25, 1.25, 1.5, 1.75, 2.75, 3.25]\n    >>> pvariance(data)\n    1.25\n\n    If you have already calculated the mean of the data, you can pass it as\n    the optional second argument to avoid recalculating it:\n\n    >>> mu = mean(data)\n    >>> pvariance(data, mu)\n    1.25\n\n    Decimals and Fractions are supported:\n\n    >>> from decimal import Decimal as D\n    >>> pvariance([D("27.5"), D("30.25"), D("30.25"), D("34.5"), D("41.75")])\n    Decimal(\'24.815\')\n\n    >>> from fractions import Fraction as F\n    >>> pvariance([F(1, 4), F(5, 4), F(1, 2)])\n    Fraction(13, 72)\n\n    """\n'),
    ('stdlib/statistics.py', 816, 824, 'stdev', 'def stdev(data, xbar=None):\n    """Return the square root of the sample variance.\n\n    See ``variance`` for arguments and other details.\n\n    >>> stdev([1.5, 2.5, 2.5, 2.75, 3.25, 4.75])\n    1.0810874155219827\n\n    """\n'),
    ('stdlib/statistics.py', 835, 843, 'pstdev', 'def pstdev(data, mu=None):\n    """Return the square root of the population variance.\n\n    See ``pvariance`` for arguments and other details.\n\n    >>> pstdev([1.5, 2.5, 2.5, 2.75, 3.25, 4.75])\n    0.986893273527251\n\n    """\n'),
    ('stdlib/statistics.py', 861, 877, 'covariance', 'def covariance(x, y, /):\n    """Covariance\n\n    Return the sample covariance of two inputs *x* and *y*. Covariance\n    is a measure of the joint variability of two inputs.\n\n    >>> x = [1, 2, 3, 4, 5, 6, 7, 8, 9]\n    >>> y = [1, 2, 3, 1, 2, 3, 1, 2, 3]\n    >>> covariance(x, y)\n    0.75\n    >>> z = [9, 8, 7, 6, 5, 4, 3, 2, 1]\n    >>> covariance(x, z)\n    -7.5\n    >>> covariance(z, x)\n    -7.5\n\n    """\n'),
    ('stdlib/statistics.py', 889, 905, 'correlation', 'def correlation(x, y, /):\n    """Pearson\'s correlation coefficient\n\n    Return the Pearson\'s correlation coefficient for two inputs. Pearson\'s\n    correlation coefficient *r* takes values between -1 and +1. It measures the\n    strength and direction of the linear relationship, where +1 means very\n    strong, positive linear relationship, -1 very strong, negative linear\n    relationship, and 0 no linear relationship.\n\n    >>> x = [1, 2, 3, 4, 5, 6, 7, 8, 9]\n    >>> y = [9, 8, 7, 6, 5, 4, 3, 2, 1]\n    >>> correlation(x, x)\n    1.0\n    >>> correlation(x, y)\n    -1.0\n\n    """\n'),
    ('stdlib/statistics.py', 925, 949, 'linear_regression', 'def linear_regression(x, y, /):\n    """Slope and intercept for simple linear regression.\n\n    Return the slope and intercept of simple linear regression\n    parameters estimated using ordinary least squares. Simple linear\n    regression describes relationship between an independent variable\n    *x* and a dependent variable *y* in terms of linear function:\n\n        y = slope * x + intercept + noise\n\n    where *slope* and *intercept* are the regression parameters that are\n    estimated, and noise represents the variability of the data that was\n    not explained by the linear regression (it is equal to the\n    difference between predicted and actual values of the dependent\n    variable).\n\n    The parameters are returned as a named tuple.\n\n    >>> x = [1, 2, 3, 4, 5]\n    >>> noise = NormalDist().samples(5, seed=42)\n    >>> y = [3 * x[i] + 2 + noise[i] for i in range(5)]\n    >>> linear_regression(x, y)  #doctest: +ELLIPSIS\n    LinearRegression(slope=3.09078914170..., intercept=1.75684970486...)\n\n    """\n'),
    ('stdlib/string.py', 37, 47, 'capwords', 'def capwords(s, sep=None):\n    """capwords(s [,sep]) -> string\n\n    Split the argument into words using split, capitalize each\n    word using capitalize, and join the capitalized words using\n    join.  If the optional second argument sep is absent or None,\n    runs of whitespace characters are replaced by a single space\n    and leading and trailing whitespace are removed, otherwise\n    sep is used to split and join the words.\n\n    """\n'),
    ('stdlib/stringprep.py', 12, 12, 'in_table_a1', 'def in_table_a1(code):\n'),
