    ('stdlib/stringprep.py', 267, 267, 'in_table_d1', 'def in_table_d1(code):\n'),
    ('stdlib/stringprep.py', 271, 271, 'in_table_d2', 'def in_table_d2(code):\n'),
    ('stdlib/subprocess.py', 337, 344, 'call', 'def call(*popenargs, timeout=None, **kwargs):\n    """Run command with arguments.  Wait for command to complete or\n    timeout, then return the returncode attribute.\n\n    The arguments are the same as for the Popen constructor.  Example:\n\n    retcode = call(["ls", "-l"])\n    """\n'),
    ('stdlib/subprocess.py', 354, 363, 'check_call', 'def check_call(*popenargs, **kwargs):\n    """Run command with arguments.  Wait for command to complete.  If\n    the exit code was zero then return, otherwise raise\n    CalledProcessError.  The CalledProcessError object will have the\n    return code in the returncode attribute.\n\n    The arguments are the same as for the call function.  Example:\n\n    check_call(["ls", "-l"])\n    """\n'),
    ('stdlib/subprocess.py', 373, 407, 'check_output', 'def check_output(*popenargs, timeout=None, **kwargs):\n    r"""Run command with arguments and return its output.\n\n    If the exit code was non-zero it raises a CalledProcessError.  The\n    CalledProcessError object will have the return code in the returncode\n    attribute and output in the output attribute.\n\n    The arguments are the same as for the Popen constructor.  Example:\n\n    >>> check_output(["ls", "-l", "/dev/null"])\n    b\'crw-rw-rw- 1 root root 1, 3 Oct 18  2007 /dev/null\\n\'\n\n    The stdout argument is not allowed as it is used internally.\n    To capture standard error in the result, use stderr=STDOUT.\n\n    >>> check_output(["/bin/sh", "-c",\n    ...               "ls -l non_existent_file ; exit 0"],\n    ...              stderr=STDOUT)\n    b\'ls: non_existent_file: No such file or directory\\n\'\n\n    There is an additional optional argument, "input", allowing you to\n    pass a string to the subprocess\'s stdin.  If you use this argument\n    you may not also use the Popen constructor\'s "stdin" argument, as\n    it too will be used internally.  Example:\n\n    >>> check_output(["sed", "-e", "s/foo/bar/"],\n    ...              input=b"when in the course of fooman events\\n")\n    b\'when in the course of barman events\\n\'\n\n    By default, all communication is in bytes, and therefore any "input"\n    should be bytes, and the return value will be bytes.  If in text mode,\n    any "input" should be a string, and the return value will be a string\n    decoded according to locale encoding, or by "encoding" if set. Text mode\n    is triggered by setting any of text, encoding, errors or universal_newlines.\n    """\n'),
    ('stdlib/subprocess.py', 461, 490, 'run', 'def run(*popenargs,\n        input=None, capture_output=False, timeout=None, check=False, **kwargs):\n    """Run command with arguments and return a CompletedProcess instance.\n\n    The returned instance will have attributes args, returncode, stdout and\n    stderr. By default, stdout and stderr are not captured, and those attributes\n    will be None. Pass stdout=PIPE and/or stderr=PIPE in order to capture them,\n    or pass capture_output=True to capture both.\n\n    If check is True and the exit code was non-zero, it raises a\n    CalledProcessError. The CalledProcessError object will have the return code\n    in the returncode attribute, and output & stderr attributes if those streams\n    were captured.\n\n    If timeout is given, and the process takes too long, a TimeoutExpired\n    exception will be raised.\n\n    There is an optional argument "input", allowing you to\n    pass bytes or a string to the subprocess\'s stdin.  If you use this argument\n    you may not also use the Popen constructor\'s "stdin" argument, as\n    it will be used internally.\n\n    By default, all communication is in bytes, and therefore any "input" should\n    be bytes, and the stdout and stderr will be bytes. If in text mode, any\n    "input" should be a string, and stdout and stderr will be strings decoded\n    according to locale encoding, or by "encoding" if set. Text mode is\n    triggered by setting any of text, encoding, errors or universal_newlines.\n\n    The other arguments are the same as for the Popen constructor.\n    """\n'),
    ('stdlib/subprocess.py', 531, 555, 'list2cmdline', 'def list2cmdline(seq):\n    """\n    Translate a sequence of arguments into a command line\n    string, using the same rules as the MS C runtime:\n\n    1) Arguments are delimited by white space, which is either a\n       space or a tab.\n\n    2) A string surrounded by double quotation marks is\n       interpreted as a single argument, regardless of white space\n       contained within.  A quoted string can be embedded in an\n       argument.\n\n    3) A double quotation mark preceded by a backslash is\n       interpreted as a literal double quotation mark.\n\n    4) Backslashes are interpreted literally, unless they\n       immediately precede a double quotation mark.\n\n    5) If backslashes immediately precede a double quotation mark,\n       every pair of backslashes is interpreted as a literal\n       backslash.  If the number of backslashes is odd, the last\n       backslash escapes the next double quotation mark as\n       described in rule 3.\n    """\n'),
    ('stdlib/subprocess.py', 604, 624, 'getstatusoutput', 'def getstatusoutput(cmd):\n    """Return (exitcode, output) of executing cmd in a shell.\n\n    Execute the string \'cmd\' in a shell with \'check_output\' and\n    return a 2-tuple (status, output). The locale encoding is used\n    to decode the output and process newlines.\n\n    A trailing newline is stripped from the output.\n    The exit status for the command can be interpreted\n    according to the rules for the function \'wait\'. Example:\n\n    >>> import subprocess\n    >>> subprocess.getstatusoutput(\'ls /bin/ls\')\n    (0, \'/bin/ls\')\n    >>> subprocess.getstatusoutput(\'cat /bin/junk\')\n    (1, \'cat: /bin/junk: No such file or directory\')\n    >>> subprocess.getstatusoutput(\'/bin/junk\')\n    (127, \'sh: /bin/junk: not found\')\n    >>> subprocess.getstatusoutput(\'/bin/kill $$\')\n    (-15, \'\')\n    """\n'),
    ('stdlib/subprocess.py', 635, 644, 'getoutput', 'def getoutput(cmd):\n    """Return output (stdout or stderr) of executing cmd in a shell.\n\n    Like getstatusoutput(), except the exit status is ignored and the return\n    value is a string containing the command\'s output.  Example:\n\n    >>> import subprocess\n    >>> subprocess.getoutput(\'ls /bin/ls\')\n    \'/bin/ls\'\n    """\n'),
    ('stdlib/sunau.py', 515, 515, 'open', 'def open(f, mode=None):\n'),
    ('stdlib/symtable.py', 12, 17, 'symtable', 'def symtable(code, filename, compile_type):\n    """ Return the toplevel *SymbolTable* for the source code.\n\n    *filename* is the name of the file with the code\n    and *compile_type* is the *compile()* mode argument.\n    """\n'),
    ('stdlib/sysconfig.py', 178, 178, 'is_python_build', 'def is_python_build(check_home=False):\n'),
    ('stdlib/sysconfig.py', 247, 247, 'get_preferred_scheme', 'def get_preferred_scheme(key):\n'),
    ('stdlib/sysconfig.py', 257, 257, 'get_default_scheme', 'def get_default_scheme():\n'),
    ('stdlib/sysconfig.py', 389, 390, 'get_makefile_filename', 'def get_makefile_filename():\n    """Return the path of the Makefile."""\n'),
    ('stdlib/sysconfig.py', 499, 505, 'parse_config_h', 'def parse_config_h(fp, vars=None):\n    """Parse a config.h-style file.\n\n    A dictionary containing name/value pairs is returned.  If an\n    optional dictionary is passed in as the second argument, it is\n    used instead of a new dictionary.\n    """\n'),
    ('stdlib/sysconfig.py', 533, 534, 'get_config_h_filename', 'def get_config_h_filename():\n    """Return the path of pyconfig.h."""\n'),
    ('stdlib/sysconfig.py', 545, 546, 'get_scheme_names', 'def get_scheme_names():\n    """Return a tuple containing the schemes names."""\n'),
    ('stdlib/sysconfig.py', 550, 551, 'get_path_names', 'def get_path_names():\n    """Return a tuple containing the paths names."""\n'),
    ('stdlib/sysconfig.py', 555, 560, 'get_paths', 'def get_paths(scheme=get_default_scheme(), vars=None, expand=True):\n    """Return a mapping containing an install scheme.\n\n    ``scheme`` is the install scheme name. If not provided, it will\n    return the default scheme for the current platform.\n    """\n'),
    ('stdlib/sysconfig.py', 567, 571, 'get_path', 'def get_path(name, scheme=get_default_scheme(), vars=None, expand=True):\n    """Return a path corresponding to the scheme.\n\n    ``scheme`` is the install scheme name.\n    """\n'),
    ('stdlib/sysconfig.py', 575, 584, 'get_config_vars', 'def get_config_vars(*args):\n    """With no arguments, return a dictionary of all configuration\n    variables relevant for the current platform.\n\n    On Unix, this means every variable defined in Python\'s installed Makefile;\n    On Windows it\'s a much smaller set.\n\n    With arguments, return a list of values that result from looking up\n    each argument in the configuration variable dictionary.\n    """\n'),
    ('stdlib/sysconfig.py', 658, 663, 'get_config_var', 'def get_config_var(name):\n    """Return the value of a single variable using the dictionary returned by\n    \'get_config_vars()\'.\n\n    Equivalent to get_config_vars().get(name)\n    """\n'),
    ('stdlib/sysconfig.py', 670, 690, 'get_platform', 'def get_platform():\n    """Return a string that identifies the current platform.\n\n    This is used mainly to distinguish platform-specific build directories and\n    platform-specific built distributions.  Typically includes the OS name and\n    version and the architecture (as supplied by \'os.uname()\'), although the\n    exact information included depends on the OS; on Linux, the kernel version\n    isn\'t particularly important.\n\n    Examples of returned values:\n       linux-i586\n       linux-alpha (?)\n       solaris-2.6-sun4u\n\n    Windows will return one of:\n       win-amd64 (64bit Windows on AMD64 (aka x86_64, Intel64, EM64T, etc)\n       win32 (all others - specifically, sys.platform is returned)\n\n    For other non-POSIX platforms, currently just returns \'sys.platform\'.\n\n    """\n'),
    ('stdlib/sysconfig.py', 751, 751, 'get_python_version', 'def get_python_version():\n'),
    ('stdlib/sysconfig.py', 755, 762, 'expand_makefile_vars', 'def expand_makefile_vars(s, vars):\n    """Expand Makefile-style variables -- "${foo}" or "$(foo)" -- in\n    \'string\' according to \'vars\' (a dictionary mapping variable names to\n    values).  Variables not present in \'vars\' are silently expanded to the\n    empty string.  The variable values in \'vars\' should not contain further\n    variable expansions; if \'vars\' is the output of \'parse_makefile()\',\n    you\'re fine.  Returns a variable-expanded version of \'s\'.\n    """\n'),
    ('stdlib/tabnanny.py', 32, 32, 'errprint', 'def errprint(*args):\n'),
    ('stdlib/tabnanny.py', 39, 39, 'main', 'def main():\n'),
    ('stdlib/tabnanny.py', 73, 81, 'check', 'def check(file):\n    """check(file_or_dir)\n\n    If file_or_dir is a directory and not a symbolic link, then recursively\n    descend the directory tree named by file_or_dir, checking all .py files\n    along the way. If file_or_dir is an ordinary Python source file, it is\n    checked for whitespace related problems. The diagnostic messages are\n    written to standard output using the print statement.\n    """\n'),
    ('stdlib/tabnanny.py', 268, 268, 'format_witnesses', 'def format_witnesses(w):\n'),
    ('stdlib/tabnanny.py', 275, 275, 'process_tokens', 'def process_tokens(tokens):\n'),
    ('stdlib/tarfile.py', 160, 162, 'stn', 'def stn(s, length, encoding, errors):\n    """Convert a string to a null-terminated bytes object.\n    """\n'),
    ('stdlib/tarfile.py', 168, 170, 'nts', 'def nts(s, encoding, errors):\n    """Convert a null-terminated bytes object to a string.\n    """\n'),
    ('stdlib/tarfile.py', 176, 178, 'nti', 'def nti(s):\n    """Convert a number field to a python number.\n    """\n'),
    ('stdlib/tarfile.py', 196, 198, 'itn', 'def itn(n, digits=8, format=DEFAULT_FORMAT):\n    """Convert a python number to a number field.\n    """\n'),
    ('stdlib/tarfile.py', 226, 234, 'calc_chksums', 'def calc_chksums(buf):\n    """Calculate the checksum for a member\'s header by summing up all\n       characters except for the chksum field which is treated as if\n       it was filled with spaces. According to the GNU tar sources,\n       some tars (Sun and NeXT) calculate chksum with signed char,\n       which will be different if there are chars in the buffer with\n       the high bit set. So we calculate two checksums, unsigned and\n       signed.\n    """\n'),
    ('stdlib/tarfile.py', 239, 242, 'copyfileobj', 'def copyfileobj(src, dst, length=None, exception=OSError, bufsize=None):\n    """Copy length bytes from fileobj src to fileobj dst.\n       If length is None, copy the entire content.\n    """\n'),
    ('stdlib/tarfile.py', 809, 809, 'fully_trusted_filter', 'def fully_trusted_filter(member, dest_path):\n'),
    ('stdlib/tarfile.py', 812, 812, 'tar_filter', 'def tar_filter(member, dest_path):\n'),
    ('stdlib/tarfile.py', 818, 818, 'data_filter', 'def data_filter(member, dest_path):\n'),
    ('stdlib/tarfile.py', 2770, 2775, 'is_tarfile', 'def is_tarfile(name):\n    """Return True if name points to a tar archive that we\n       are able to handle, else return False.\n\n       \'name\' should be a string, file, or file-like object.\n    """\n'),
    ('stdlib/tarfile.py', 2789, 2789, 'main', 'def main():\n'),
    ('stdlib/telnetlib.py', 649, 656, 'test', 'def test():\n    """Test program for telnetlib.\n\n    Usage: python telnetlib.py [-d] ... [host [port]]\n\n    Default host is localhost; default port is 23.\n\n    """\n'),
    ('stdlib/tempfile.py', 275, 276, 'gettempprefix', 'def gettempprefix():\n    """The default prefix for temporary directories as string."""\n'),
    ('stdlib/tempfile.py', 279, 280, 'gettempprefixb', 'def gettempprefixb():\n    """The default prefix for temporary directories as bytes."""\n'),
    ('stdlib/tempfile.py', 297, 298, 'gettempdir', 'def gettempdir():\n    """Returns tempfile.tempdir as str."""\n'),
    ('stdlib/tempfile.py', 301, 302, 'gettempdirb', 'def gettempdirb():\n    """Returns tempfile.tempdir as bytes."""\n'),
    ('stdlib/tempfile.py', 305, 332, 'mkstemp', 'def mkstemp(suffix=None, prefix=None, dir=None, text=False):\n    """User-callable function to create and return a unique temporary\n    file.  The return value is a pair (fd, name) where fd is the\n    file descriptor returned by os.open, and name is the filename.\n\n    If \'suffix\' is not None, the file name will end with that suffix,\n    otherwise there will be no suffix.\n\n    If \'prefix\' is not None, the file name will begin with that prefix,\n    otherwise a default prefix is used.\n\n    If \'dir\' is not None, the file will be created in that directory,\n    otherwise a default directory is used.\n\n    If \'text\' is specified and true, the file is opened in text\n    mode.  Else (the default) the file is opened in binary mode.\n\n    If any of \'suffix\', \'prefix\' and \'dir\' are not None, they must be the\n    same type.  If they are bytes, the returned name will be bytes; str\n    otherwise.\n\n    The file is readable and writable only by the creating user ID.\n    If the operating system uses permission bits to indicate whether a\n    file is executable, the file is executable by no one. The file\n    descriptor is not inherited by children of this process.\n\n    Caller is responsible for deleting the file when done with it.\n    """\n'),
    ('stdlib/tempfile.py', 344, 355, 'mkdtemp', 'def mkdtemp(suffix=None, prefix=None, dir=None):\n    """User-callable function to create and return a unique temporary\n    directory.  The return value is the pathname of the directory.\n\n    Arguments are as for mkstemp, except that the \'text\' argument is\n    not accepted.\n\n    The directory is readable, writable, and searchable only by the\n    creating user.\n\n    Caller is responsible for deleting the directory when done with it.\n    """\n'),
    ('stdlib/tempfile.py', 384, 396, 'mktemp', 'def mktemp(suffix="", prefix=template, dir=None):\n    """User-callable function to return a unique temporary file name.  The\n    file is not created.\n\n    Arguments are similar to mkstemp, except that the \'text\' argument is\n    not accepted, and suffix=None, prefix=None and bytes file names are not\n    supported.\n\n    THIS FUNCTION IS UNSAFE AND SHOULD NOT BE USED.  The file name may\n    refer to a file that did not exist at some point, but by the time\n    you get around to creating it, someone else may have beaten you to\n    the punch.\n    """\n'),
    ('stdlib/tempfile.py', 522, 539, 'NamedTemporaryFile', 'def NamedTemporaryFile(mode=\'w+b\', buffering=-1, encoding=None,\n                       newline=None, suffix=None, prefix=None,\n                       dir=None, delete=True, *, errors=None):\n    """Create and return a temporary file.\n    Arguments:\n    \'prefix\', \'suffix\', \'dir\' -- as for mkstemp.\n    \'mode\' -- the mode argument to io.open (default "w+b").\n    \'buffering\' -- the buffer size argument to io.open (default -1).\n    \'encoding\' -- the encoding argument to io.open (default None)\n    \'newline\' -- the newline argument to io.open (default None)\n    \'delete\' -- whether the file is deleted on close (default True).\n    \'errors\' -- the errors argument to io.open (default None)\n    The file is created as mkstemp() would do it.\n\n    Returns an object with a file-like interface; the name of the file\n    is accessible as its \'name\' attribute.  The file will be automatically\n    deleted when it is closed unless the \'delete\' argument is set to False.\n    """\n'),
    ('stdlib/textwrap.py', 376, 385, 'wrap', 'def wrap(text, width=70, **kwargs):\n    """Wrap a single paragraph of text, returning a list of wrapped lines.\n\n    Reformat the single paragraph in \'text\' so it fits in lines of no\n    more than \'width\' columns, and return a list of wrapped lines.  By\n    default, tabs in \'text\' are expanded with string.expandtabs(), and\n    all other whitespace characters (including newline) are converted to\n    space.  See TextWrapper class for available keyword args to customize\n    wrapping behaviour.\n    """\n'),
    ('stdlib/textwrap.py', 389, 397, 'fill', 'def fill(text, width=70, **kwargs):\n    """Fill a single paragraph of text, returning a new string.\n\n    Reformat the single paragraph in \'text\' to fit in lines of no more\n    than \'width\' columns, and return a new string containing the entire\n    wrapped paragraph.  As with wrap(), tabs are expanded and other\n    whitespace characters converted to space.  See TextWrapper class for\n    available keyword args to customize wrapping behaviour.\n    """\n'),
    ('stdlib/textwrap.py', 401, 412, 'shorten', 'def shorten(text, width, **kwargs):\n    """Collapse and truncate the given text to fit in the given width.\n\n    The text first has its whitespace collapsed.  If it then fits in\n    the *width*, it is returned as is.  Otherwise, as many words\n    as possible are joined and then the placeholder is appended::\n\n        >>> textwrap.shorten("Hello  world!", width=12)\n        \'Hello world!\'\n        >>> textwrap.shorten("Hello  world!", width=11)\n        \'Hello [...]\'\n    """\n'),
    ('stdlib/textwrap.py', 422, 434, 'dedent', 'def dedent(text):\n    """Remove any common leading whitespace from every line in `text`.\n\n    This can be used to make triple-quoted strings line up with the left\n    edge of the display, while still presenting them in the source code\n    in indented form.\n\n    Note that tabs and spaces are both treated as whitespace, but they\n    are not equal: the lines "  hello" and "\\\\thello" are\n    considered to have no common leading whitespace.\n\n    Entirely blank lines are normalized to a newline character.\n    """\n'),
    ('stdlib/textwrap.py', 473, 480, 'indent', 'def indent(text, prefix, predicate=None):\n    """Adds \'prefix\' to the beginning of selected lines in \'text\'.\n\n    If \'predicate\' is provided, \'prefix\' will only be added to the lines\n    where \'predicate(line)\' is True. If \'predicate\' is not provided,\n    it will default to adding \'prefix\' to all non-empty lines that do not\n    consist solely of whitespace characters.\n    """\n'),
    ('stdlib/threading.py', 58, 64, 'setprofile', 'def setprofile(func):\n    """Set a profile function for all threads started from the threading module.\n\n    The func will be passed to sys.setprofile() for each thread, before its\n    run() method is called.\n\n    """\n'),
    ('stdlib/threading.py', 68, 69, 'getprofile', 'def getprofile():\n    """Get the profiler function as set by threading.setprofile()."""\n'),
    ('stdlib/threading.py', 72, 78, 'settrace', 'def settrace(func):\n    """Set a trace function for all threads started from the threading module.\n\n    The func will be passed to sys.settrace() for each thread, before its run()\n    method is called.\n\n    """\n'),
    ('stdlib/threading.py', 82, 83, 'gettrace', 'def gettrace():\n    """Get the trace function as set by threading.settrace()."""\n'),
    ('stdlib/threading.py', 90, 98, 'RLock', 'def RLock(*args, **kwargs):\n    """Factory function that returns a new reentrant lock.\n\n    A reentrant lock must be released by the thread that acquired it. Once a\n    thread has acquired a reentrant lock, the same thread may acquire it again\n    without blocking; the thread must release it once for each time it has\n    acquired it.\n\n    """\n'),
    ('stdlib/threading.py', 1430, 1436, 'current_thread', 'def current_thread():\n    """Return the current Thread object, corresponding to the caller\'s thread of control.\n\n    If the caller\'s thread of control was not created through the threading\n    module, a dummy thread object with limited functionality is returned.\n\n    """\n'),
    ('stdlib/threading.py', 1442, 1447, 'currentThread', 'def currentThread():\n    """Return the current Thread object, corresponding to the caller\'s thread of control.\n\n    This function is deprecated, use current_thread() instead.\n\n    """\n'),
    ('stdlib/threading.py', 1453, 1459, 'active_count', 'def active_count():\n    """Return the number of Thread objects currently alive.\n\n    The returned count is equal to the length of the list returned by\n    enumerate().\n\n    """\n'),
    ('stdlib/threading.py', 1463, 1468, 'activeCount', 'def activeCount():\n    """Return the number of Thread objects currently alive.\n\n    This function is deprecated, use active_count() instead.\n\n    """\n'),
    ('stdlib/threading.py', 1478, 1485, 'enumerate', 'def enumerate():\n    """Return a list of all Thread objects currently alive.\n\n    The list includes daemonic threads, dummy thread objects created by\n    current_thread(), and the main thread. It excludes terminated threads and\n    threads that have not yet been started.\n\n    """\n'),
    ('stdlib/threading.py', 1574, 1579, 'main_thread', 'def main_thread():\n    """Return the main thread object.\n\n    In normal conditions, the main thread is the thread from which the\n    Python interpreter was started.\n    """\n'),
    ('stdlib/timeit.py', 80, 81, 'reindent', 'def reindent(src, indent):\n    """Helper to reindent a multi-line statement."""\n'),
    ('stdlib/timeit.py', 231, 233, 'timeit', 'def timeit(stmt="pass", setup="pass", timer=default_timer,\n           number=default_number, globals=None):\n    """Convenience function to create Timer object and call timeit method."""\n'),
    ('stdlib/timeit.py', 236, 238, 'repeat', 'def repeat(stmt="pass", setup="pass", timer=default_timer,\n           repeat=default_repeat, number=default_number, globals=None):\n    """Convenience function to create Timer object and call repeat method."""\n'),
    ('stdlib/timeit.py', 241, 257, 'main', 'def main(args=None, *, _wrap_timer=None):\n    """Main program, used when run as a script.\n\n    The optional \'args\' argument specifies the command line to be parsed,\n    defaulting to sys.argv[1:].\n\n    The return value is an exit code to be passed to sys.exit(); it\n    may be None to indicate success.\n\n    When an exception happens during timing, a traceback is printed to\n    stderr and the return value is 1.  Exceptions at other times\n    (including the template compilation) are not caught.\n\n    \'_wrap_timer\' is an internal interface used for unit testing.  If it\n    is not None, it must be a callable that accepts a timer function\n    and returns another timer function (used for unit testing).\n    """\n'),
    ('stdlib/token.py', 130, 130, 'ISTERMINAL', 'def ISTERMINAL(x):\n'),
    ('stdlib/token.py', 133, 133, 'ISNONTERMINAL', 'def ISNONTERMINAL(x):\n'),
    ('stdlib/token.py', 136, 136, 'ISEOF', 'def ISEOF(x):\n'),
    ('stdlib/tokenize.py', 59, 59, 'group', "def group(*choices): return '(' + '|'.join(choices) + ')'\n"),
    ('stdlib/tokenize.py', 60, 60, 'any', "def any(*choices): return group(*choices) + '*'\n"),
    ('stdlib/tokenize.py', 61, 61, 'maybe', "def maybe(*choices): return group(*choices) + '?'\n"),
    ('stdlib/tokenize.py', 259, 278, 'untokenize', 'def untokenize(iterable):\n    """Transform tokens back into Python source code.\n    It returns a bytes object, encoded using the ENCODING\n    token, which is the first token sequence output by tokenize.\n\n    Each element returned by the iterable must be a token sequence\n    with at least two elements, a token number and token value.  If\n    only two tokens are passed, the resulting output is poor.\n\n    Round-trip invariant for full input:\n        Untokenized source will match input source exactly\n\n    Round-trip invariant for limited input:\n        # Output bytes will tokenize back to the input\n        t1 = [tok[:2] for tok in tokenize(f.readline)]\n        newcode = untokenize(t1)\n        readline = BytesIO(newcode).readline\n        t2 = [tok[:2] for tok in tokenize(readline)]\n        assert t1 == t2\n    """\n'),
    ('stdlib/tokenize.py', 297, 313, 'detect_encoding', 'def detect_encoding(readline):\n    """\n    The detect_encoding() function is used to detect the encoding that should\n    be used to decode a Python source file.  It requires one argument, readline,\n    in the same way as the tokenize() generator.\n\n    It will call readline a maximum of twice, and return the encoding used\n    (as a string) and a list of any lines (left as bytes) it has read in.\n\n    It detects the encoding from the presence of a utf-8 bom or an encoding\n    cookie as specified in pep-0263.  If both a bom and a cookie are present,\n    but disagree, a SyntaxError will be raised.  If the encoding cookie is an\n    invalid charset, raise a SyntaxError.  Note that if a utf-8 bom is found,\n    \'utf-8-sig\' is returned.\n\n    If no encoding is specified, then the default of \'utf-8\' will be returned.\n    """\n'),
    ('stdlib/tokenize.py', 390, 393, 'open', 'def open(filename):\n    """Open a file in read only mode using the encoding detected by\n    detect_encoding().\n    """\n'),
    ('stdlib/tokenize.py', 406, 424, 'tokenize', 'def tokenize(readline):\n    """\n    The tokenize() generator requires one argument, readline, which\n    must be a callable object which provides the same interface as the\n    readline() method of built-in file objects.  Each call to the function\n    should return one line of input as bytes.  Alternatively, readline\n    can be a callable function terminating with StopIteration:\n        readline = open(myfile, \'rb\').__next__  # Example of alternate readline\n\n    The generator produces 5-tuples with these members: the token type; the\n    token string; a 2-tuple (srow, scol) of ints specifying the row and\n    column where the token begins in the source; a 2-tuple (erow, ecol) of\n    ints specifying the row and column where the token ends in the source;\n    and the line on which the token was found.  The line passed is the\n    physical line.\n\n    The first token sequence will always be an ENCODING token\n    which tells you which encoding was used to decode the bytes stream.\n    """\n'),
    ('stdlib/tokenize.py', 614, 619, 'generate_tokens', 'def generate_tokens(readline):\n    """Tokenize a source reading Python code as unicode strings.\n\n    This has the same API as tokenize(), except that it expects the *readline*\n    callable to return str objects instead of bytes.\n    """\n'),
    ('stdlib/tokenize.py', 622, 622, 'main', 'def main():\n'),
    ('stdlib/trace.py', 594, 594, 'main', 'def main():\n'),
    ('stdlib/traceback.py', 19, 21, 'print_list', 'def print_list(extracted_list, file=None):\n    """Print the list of tuples as returned by extract_tb() or\n    extract_stack() as a formatted stack trace to the given file."""\n'),
    ('stdlib/traceback.py', 27, 38, 'format_list', 'def format_list(extracted_list):\n    """Format a list of tuples or FrameSummary objects for printing.\n\n    Given a list of tuples or FrameSummary objects as returned by\n    extract_tb() or extract_stack(), return a list of strings ready\n    for printing.\n\n    Each string in the resulting list corresponds to the item with the\n    same index in the argument list.  Each string ends in a newline;\n    the strings may contain internal newlines as well, for those items\n    whose source text line is not None.\n    """\n'),
    ('stdlib/traceback.py', 45, 52, 'print_tb', 'def print_tb(tb, limit=None, file=None):\n    """Print up to \'limit\' stack trace entries from the traceback \'tb\'.\n\n    If \'limit\' is omitted or None, all entries are printed.  If \'file\'\n    is omitted or None, the output goes to sys.stderr; otherwise\n    \'file\' should be an open file or file-like object with a write()\n    method.\n    """\n'),
    ('stdlib/traceback.py', 55, 56, 'format_tb', 'def format_tb(tb, limit=None):\n    """A shorthand for \'format_list(extract_tb(tb, limit))\'."""\n'),
    ('stdlib/traceback.py', 59, 71, 'extract_tb', 'def extract_tb(tb, limit=None):\n    """\n    Return a StackSummary object representing a list of\n    pre-processed entries from traceback.\n\n    This is useful for alternate formatting of stack traces.  If\n    \'limit\' is omitted or None, all entries are extracted.  A\n    pre-processed stack trace entry is a FrameSummary object\n    containing attributes filename, lineno, name, and line\n    representing the information that is usually printed for a stack\n    trace.  The line is a string with leading and trailing\n    whitespace stripped; if the source is not available it is None.\n    """\n'),
    ('stdlib/traceback.py', 104, 115, 'print_exception', 'def print_exception(exc, /, value=_sentinel, tb=_sentinel, limit=None, \\\n                    file=None, chain=True):\n    """Print exception up to \'limit\' stack trace entries from \'tb\' to \'file\'.\n\n    This differs from print_tb() in the following ways: (1) if\n    traceback is not None, it prints a header "Traceback (most recent\n    call last):"; (2) it prints the exception type and value after the\n    stack trace; (3) if type is SyntaxError and value has the\n    appropriate format, it prints the line where the syntax error\n    occurred with a caret on the next line indicating the approximate\n    position of the error.\n    """\n'),
    ('stdlib/traceback.py', 124, 133, 'format_exception', 'def format_exception(exc, /, value=_sentinel, tb=_sentinel, limit=None, \\\n                     chain=True):\n    """Format a stack trace and the exception information.\n\n    The arguments have the same meaning as the corresponding arguments\n    to print_exception().  The return value is a list of strings, each\n    ending in a newline and some containing internal newlines.  When\n    these lines are concatenated and printed, exactly the same text is\n    printed as does print_exception().\n    """\n'),
    ('stdlib/traceback.py', 139, 152, 'format_exception_only', 'def format_exception_only(exc, /, value=_sentinel):\n    """Format the exception part of a traceback.\n\n    The return value is a list of strings, each ending in a newline.\n\n    Normally, the list contains a single string; however, for\n    SyntaxError exceptions, it contains several lines that (when\n    printed) display detailed information about where the syntax\n    error occurred.\n\n    The message indicating which exception occurred is always the last\n    string in the list.\n\n    """\n'),
    ('stdlib/traceback.py', 177, 178, 'print_exc', 'def print_exc(limit=None, file=None, chain=True):\n    """Shorthand for \'print_exception(*sys.exc_info(), limit, file)\'."""\n'),
    ('stdlib/traceback.py', 181, 182, 'format_exc', 'def format_exc(limit=None, chain=True):\n    """Like print_exc() but return a string."""\n'),
    ('stdlib/traceback.py', 185, 187, 'print_last', 'def print_last(limit=None, file=None, chain=True):\n    """This is a shorthand for \'print_exception(sys.last_type,\n    sys.last_value, sys.last_traceback, limit, file)\'."""\n'),
    ('stdlib/traceback.py', 197, 203, 'print_stack', 'def print_stack(f=None, limit=None, file=None):\n    """Print a stack trace from its invocation point.\n\n    The optional \'f\' argument can be used to specify an alternate\n    stack frame at which to start. The optional \'limit\' and \'file\'\n    arguments have the same meaning as for print_exception().\n    """\n'),
    ('stdlib/traceback.py', 209, 210, 'format_stack', 'def format_stack(f=None, limit=None):\n    """Shorthand for \'format_list(extract_stack(f, limit))\'."""\n'),
    ('stdlib/traceback.py', 216, 224, 'extract_stack', 'def extract_stack(f=None, limit=None):\n    """Extract the raw traceback from the current stack frame.\n\n    The return value has the same format as for extract_tb().  The\n    optional \'f\' and \'limit\' arguments have the same meaning as for\n    print_stack().  Each item in the list is a quadruple (filename,\n    line number, function name, text), and the entries are in order\n    from oldest to newest stack frame.\n    """\n'),
    ('stdlib/traceback.py', 232, 233, 'clear_frames', 'def clear_frames(tb):\n    "Clear all references to local variables in the frames of a traceback."\n'),
    ('stdlib/traceback.py', 309, 314, 'walk_stack', 'def walk_stack(f):\n    """Walk a stack yielding the frame and line number for each frame.\n\n    This will follow f.f_back from the given frame. If no frame is given, the\n    current stack is used. Usually used with StackSummary.extract.\n    """\n'),
    ('stdlib/traceback.py', 322, 327, 'walk_tb', 'def walk_tb(tb):\n    """Walk a traceback yielding the frame and line number for each frame.\n\n    This will follow tb.tb_next (and thus is in the opposite order to\n    walk_stack). Usually used with StackSummary.extract.\n    """\n'),
    ('stdlib/tracemalloc.py', 257, 264, 'get_object_traceback', 'def get_object_traceback(obj):\n    """\n    Get the traceback where the Python object *obj* was allocated.\n    Return a Traceback instance.\n\n    Return None if the tracemalloc module is not tracing memory allocations or\n    did not trace the allocation of the object.\n    """\n'),
    ('stdlib/tracemalloc.py', 551, 554, 'take_snapshot', 'def take_snapshot():\n    """\n    Take a snapshot of traces of memory blocks allocated by Python.\n    """\n'),
    ('stdlib/tty.py', 18, 19, 'setraw', 'def setraw(fd, when=TCSAFLUSH):\n    """Put terminal into a raw mode."""\n'),
    ('stdlib/tty.py', 30, 31, 'setcbreak', 'def setcbreak(fd, when=TCSAFLUSH):\n    """Put terminal into a cbreak mode."""\n'),
    ('stdlib/turtle.py', 171, 172, 'config_dict', 'def config_dict(filename):\n    """Convert content of config-file into dictionary."""\n'),
    ('stdlib/turtle.py', 200, 212, 'readconfig', 'def readconfig(cfgdict):\n    """Read config-files, change configuration-dict accordingly.\n\n    If there is a turtle.cfg file in the current working directory,\n    read it from there. If this contains an importconfig-value,\n    say \'myway\', construct filename turtle_mayway.cfg else use\n    turtle.cfg and read it from the import-directory, where\n    turtle.py is located.\n    Update configuration dictionary first according to config-file,\n    in the import directory, then according to config-file in the\n    current working directory.\n    If no config-file is found, the default configuration is used.\n    """\n'),
    ('stdlib/turtle.py', 3659, 3662, 'Screen', 'def Screen():\n    """Return the singleton screen object.\n    If none exists at the moment, create a new one and return it,\n    else return the existing one."""\n'),
    ('stdlib/turtle.py', 3822, 3833, 'write_docstringdict', 'def write_docstringdict(filename="turtle_docstringdict"):\n    """Create and write docstring-dictionary to file.\n\n    Optional argument:\n    filename -- a string, used as filename\n                default value is turtle_docstringdict\n\n    Has to be called explicitly, (not used by the turtle-graphics classes)\n    The docstring dictionary will be written to the Python script <filname>.py\n    It is intended to serve as a template for translation of the docstrings\n    into different languages.\n    """\n'),
    ('stdlib/turtle.py', 3856, 3862, 'read_docstrings', 'def read_docstrings(lang):\n    """Read in docstrings from lang-specific docstring dictionary.\n\n    Transfer docstrings, translated to lang, from a dictionary-file\n    to the methods of classes Screen and Turtle and - in revised form -\n    to the corresponding functions.\n    """\n'),
    ('stdlib/turtle.py', 3885, 3892, 'getmethparlist', 'def getmethparlist(ob):\n    """Get strings describing the arguments for the given object\n\n    Returns a pair of strings representing function parameter lists\n    including parenthesis.  The first string is suitable for use in\n    function definition and the second is suitable for use in function\n    call.  The "self" parameter is not included.\n    """\n'),
    ('stdlib/types.py', 69, 70, 'new_class', 'def new_class(name, bases=(), kwds=None, exec_body=None):\n    """Create a class object dynamically using the appropriate metaclass."""\n'),
    ('stdlib/types.py', 79, 80, 'resolve_bases', 'def resolve_bases(bases):\n    """Resolve MRO entries dynamically as specified by PEP 560."""\n'),
    ('stdlib/types.py', 100, 110, 'prepare_class', 'def prepare_class(name, bases=(), kwds=None):\n    """Call the __prepare__ method of the appropriate metaclass.\n\n    Returns (metaclass, namespace, kwds) as a 3-tuple\n\n    *metaclass* is the appropriate metaclass\n    *namespace* is the prepared class namespace\n    *kwds* is an updated copy of the passed in kwds argument with any\n    \'metaclass\' entry removed. If no kwds argument is passed in, this will\n    be an empty dict.\n    """\n'),
    ('stdlib/types.py', 249, 250, 'coroutine', 'def coroutine(func):\n    """Convert regular generator function to a coroutine."""\n'),
    ('stdlib/typing.py', 414, 424, 'Any', 'def Any(self, parameters):\n    """Special type indicating an unconstrained type.\n\n    - Any is compatible with every type.\n    - Any assumed to have all methods.\n    - All values assumed to be instances of Any.\n\n    Note that all the above statements are true from the point of view of\n    static type checkers. At runtime, Any should not be used with instance\n    or class checks.\n    """\n'),
    ('stdlib/typing.py', 428, 439, 'NoReturn', 'def NoReturn(self, parameters):\n    """Special type indicating functions that never return.\n    Example::\n\n      from typing import NoReturn\n\n      def stop() -> NoReturn:\n          raise Exception(\'no way\')\n\n    This type is invalid in other positions, e.g., ``List[NoReturn]``\n    will fail in static type checkers.\n    """\n'),
    ('stdlib/typing.py', 443, 458, 'ClassVar', 'def ClassVar(self, parameters):\n    """Special type construct to mark class variables.\n\n    An annotation wrapped in ClassVar indicates that a given\n    attribute is intended to be used as a class variable and\n    should not be set on instances of that class. Usage::\n\n      class Starship:\n          stats: ClassVar[Dict[str, int]] = {} # class variable\n          damage: int = 10                     # instance variable\n\n    ClassVar accepts only types and cannot be further subscribed.\n\n    Note that ClassVar is not a class itself, and should not\n    be used with isinstance() or issubclass().\n    """\n'),
    ('stdlib/typing.py', 463, 479, 'Final', 'def Final(self, parameters):\n    """Special typing construct to indicate final names to type checkers.\n\n    A final name cannot be re-assigned or overridden in a subclass.\n    For example:\n\n      MAX_SIZE: Final = 9000\n      MAX_SIZE += 1  # Error reported by type checker\n\n      class Connection:\n          TIMEOUT: Final[int] = 10\n\n      class FastConnector(Connection):\n          TIMEOUT = 1  # Error reported by type checker\n\n    There is no runtime checking of these properties.\n    """\n'),
    ('stdlib/typing.py', 484, 509, 'Union', 'def Union(self, parameters):\n    """Union type; Union[X, Y] means either X or Y.\n\n    To define a union, use e.g. Union[int, str].  Details:\n    - The arguments must be types and there must be at least one.\n    - None as an argument is a special case and is replaced by\n      type(None).\n    - Unions of unions are flattened, e.g.::\n\n        Union[Union[int, str], float] == Union[int, str, float]\n\n    - Unions of a single argument vanish, e.g.::\n\n        Union[int] == int  # The constructor actually returns int\n\n    - Redundant arguments are skipped, e.g.::\n\n        Union[int, str, int] == Union[int, str]\n\n    - When comparing unions, the argument order is ignored, e.g.::\n\n        Union[int, str] == Union[str, int]\n\n    - You cannot subclass or instantiate a union.\n    - You can use Optional[X] as a shorthand for Union[X, None].\n    """\n'),
    ('stdlib/typing.py', 524, 528, 'Optional', 'def Optional(self, parameters):\n    """Optional type.\n\n    Optional[X] is equivalent to Union[X, None].\n    """\n'),
    ('stdlib/typing.py', 534, 554, 'Literal', 'def Literal(self, *parameters):\n    """Special typing form to define literal types (a.k.a. value types).\n\n    This form can be used to indicate to type checkers that the corresponding\n    variable or function parameter has a value equivalent to the provided\n    literal (or one of several literals):\n\n      def validate_simple(data: Any) -> Literal[True]:  # always returns True\n          ...\n\n      MODE = Literal[\'r\', \'rb\', \'w\', \'wb\']\n      def open_helper(file: str, mode: MODE) -> str:\n          ...\n\n      open_helper(\'/some/path\', \'r\')  # Passes type check\n      open_helper(\'/other/path\', \'typo\')  # Error in type checker\n\n    Literal[...] cannot be subclassed. At runtime, an arbitrary value\n    is allowed as type argument to Literal[...], but type checkers may\n    impose restrictions.\n    """\n'),
    ('stdlib/typing.py', 568, 578, 'TypeAlias', 'def TypeAlias(self, parameters):\n    """Special marker indicating that an assignment should\n    be recognized as a proper type alias definition by type\n    checkers.\n\n    For example::\n\n        Predicate: TypeAlias = Callable[..., bool]\n\n    It\'s invalid when used anywhere except as in the example above.\n    """\n'),
    ('stdlib/typing.py', 583, 593, 'Concatenate', 'def Concatenate(self, parameters):\n    """Used in conjunction with ``ParamSpec`` and ``Callable`` to represent a\n    higher order function which adds, removes or transforms parameters of a\n    callable.\n\n    For example::\n\n       Callable[Concatenate[int, P], int]\n\n    See PEP 612 for detailed information.\n    """\n'),
    ('stdlib/typing.py', 609, 651, 'TypeGuard', 'def TypeGuard(self, parameters):\n    """Special typing form used to annotate the return type of a user-defined\n    type guard function.  ``TypeGuard`` only accepts a single type argument.\n    At runtime, functions marked this way should return a boolean.\n\n    ``TypeGuard`` aims to benefit *type narrowing* -- a technique used by static\n    type checkers to determine a more precise type of an expression within a\n    program\'s code flow.  Usually type narrowing is done by analyzing\n    conditional code flow and applying the narrowing to a block of code.  The\n    conditional expression here is sometimes referred to as a "type guard".\n\n    Sometimes it would be convenient to use a user-defined boolean function\n    as a type guard.  Such a function should use ``TypeGuard[...]`` as its\n    return type to alert static type checkers to this intention.\n\n    Using  ``-> TypeGuard`` tells the static type checker that for a given\n    function:\n\n    1. The return value is a boolean.\n    2. If the return value is ``True``, the type of its argument\n       is the type inside ``TypeGuard``.\n\n       For example::\n\n          def is_str(val: Union[str, float]):\n              # "isinstance" type guard\n              if isinstance(val, str):\n                  # Type of ``val`` is narrowed to ``str``\n                  ...\n              else:\n                  # Else, type of ``val`` is narrowed to ``float``.\n                  ...\n\n    Strict type narrowing is not enforced -- ``TypeB`` need not be a narrower\n    form of ``TypeA`` (it can even be a wider form) and this may lead to\n    type-unsafe results.  The main reason is to allow for things like\n    narrowing ``List[object]`` to ``List[str]`` even though the latter is not\n    a subtype of the former, since ``List`` is invariant.  The responsibility of\n    writing type-safe type guards is left to the user.\n\n    ``TypeGuard`` also works with type variables.  For more information, see\n    PEP 647 (User-Defined Type Guards).\n    """\n'),
    ('stdlib/typing.py', 1712, 1729, 'runtime_checkable', 'def runtime_checkable(cls):\n    """Mark a protocol class as a runtime protocol.\n\n    Such protocol can be used with isinstance() and issubclass().\n    Raise TypeError if applied to a non-protocol class.\n    This allows a simple-minded structural check very similar to\n    one trick ponies in collections.abc such as Iterable.\n    For example::\n\n        @runtime_checkable\n        class Closable(Protocol):\n            def close(self): ...\n\n        assert isinstance(open(\'/some/file\'), Closable)\n\n    Warning: this will check only the presence of the required methods,\n    not their type signatures!\n    """\n'),
    ('stdlib/typing.py', 1737, 1744, 'cast', 'def cast(typ, val):\n    """Cast a value to a type.\n\n    This returns the value unchanged.  To the type checker this\n    signals that the return value has the designated type, but at\n    runtime we intentionally don\'t check anything (we want this\n    to be as fast as possible).\n    """\n'),
    ('stdlib/typing.py', 1773, 1804, 'get_type_hints', 'def get_type_hints(obj, globalns=None, localns=None, include_extras=False):\n    """Return type hints for an object.\n\n    This is often the same as obj.__annotations__, but it handles\n    forward references encoded as string literals, adds Optional[t] if a\n    default value equal to None is set and recursively replaces all\n    \'Annotated[T, ...]\' with \'T\' (unless \'include_extras=True\').\n\n    The argument may be a module, class, method, or function. The annotations\n    are returned as a dictionary. For classes, annotations include also\n    inherited members.\n\n    TypeError is raised if the argument is not of a type that can contain\n    annotations, and an empty dictionary is returned if no annotations are\n    present.\n\n    BEWARE -- the behavior of globalns and localns is counterintuitive\n    (unless you are familiar with how eval() and exec() work).  The\n    search order is locals first, then globals.\n\n    - If no dict arguments are passed, an attempt is made to use the\n      globals from obj (or the respective module\'s globals for classes),\n      and these are also used as the locals.  If the object does not appear\n      to have globals, an empty dictionary is used.  For classes, the search\n      order is globals first then locals.\n\n    - If one dict argument is passed, it is used for both globals and\n      locals.\n\n    - If two dict arguments are passed, they specify globals and\n      locals, respectively.\n    """\n'),
    ('stdlib/typing.py', 1902, 1916, 'get_origin', 'def get_origin(tp):\n    """Get the unsubscripted version of a type.\n\n    This supports generic types, Callable, Tuple, Union, Literal, Final, ClassVar\n    and Annotated. Return None for unsupported types. Examples::\n\n        get_origin(Literal[42]) is Literal\n        get_origin(int) is None\n        get_origin(ClassVar[int]) is ClassVar\n        get_origin(Generic) is Generic\n        get_origin(Generic[T]) is Generic\n        get_origin(Union[T, int]) is Union\n        get_origin(List[Tuple[T, T]][int]) == list\n        get_origin(P.args) is P\n    """\n'),
    ('stdlib/typing.py', 1929, 1939, 'get_args', 'def get_args(tp):\n    """Get type arguments with all substitutions performed.\n\n    For unions, basic simplifications used by Union constructor are performed.\n    Examples::\n        get_args(Dict[str, int]) == (str, int)\n        get_args(int) == ()\n        get_args(Union[int, Union[T, int], str][int]) == (int, str)\n        get_args(Union[int, Tuple[T, int]][str]) == (int, Tuple[str, int])\n        get_args(Callable[[], T][int]) == ([], int)\n    """\n'),
    ('stdlib/typing.py', 1953, 1963, 'is_typeddict', 'def is_typeddict(tp):\n    """Check if an annotation is a TypedDict class\n\n    For example::\n        class Film(TypedDict):\n            title: str\n            year: int\n\n        is_typeddict(Film)  # => True\n        is_typeddict(Union[list, str])  # => False\n    """\n'),
    ('stdlib/typing.py', 1967, 1975, 'no_type_check', 'def no_type_check(arg):\n    """Decorator to indicate that annotations are not type hints.\n\n    The argument must be a class or function; if it is a class, it\n    applies recursively to all methods and classes defined in that class\n    (but not to methods defined in its superclasses or subclasses).\n\n    This mutates the function(s) or class(es) in place.\n    """\n'),
    ('stdlib/typing.py', 1993, 1998, 'no_type_check_decorator', 'def no_type_check_decorator(decorator):\n    """Decorator to give another decorator the @no_type_check effect.\n\n    This wraps the decorator with something that wraps the decorated\n    function in @no_type_check.\n    """\n'),
    ('stdlib/typing.py', 2018, 2043, 'overload', 'def overload(func):\n    """Decorator for overloaded functions/methods.\n\n    In a stub file, place two or more stub definitions for the same\n    function in a row, each decorated with @overload.  For example:\n\n      @overload\n      def utf8(value: None) -> None: ...\n      @overload\n      def utf8(value: bytes) -> bytes: ...\n      @overload\n      def utf8(value: str) -> bytes: ...\n\n    In a non-stub file (i.e. a regular .py file), do the same but\n    follow it with an implementation.  The implementation should *not*\n    be decorated with @overload.  For example:\n\n      @overload\n      def utf8(value: None) -> None: ...\n      @overload\n      def utf8(value: bytes) -> bytes: ...\n      @overload\n      def utf8(value: str) -> bytes: ...\n      def utf8(value):\n          # implementation goes here\n    """\n'),
    ('stdlib/typing.py', 2047, 2069, 'final', 'def final(f):\n    """A decorator to indicate final methods and final classes.\n\n    Use this decorator to indicate to type checkers that the decorated\n    method cannot be overridden, and decorated class cannot be subclassed.\n    For example:\n\n      class Base:\n          @final\n          def done(self) -> None:\n              ...\n      class Sub(Base):\n          def done(self) -> None:  # Error reported by type checker\n                ...\n\n      @final\n      class Leaf:\n          ...\n      class Other(Leaf):  # Error reported by type checker\n          ...\n\n    There is no runtime checking of these properties.\n    """\n'),
    ('stdlib/typing.py', 2291, 2314, 'NamedTuple', 'def NamedTuple(typename, fields=None, /, **kwargs):\n    """Typed version of namedtuple.\n\n    Usage in Python versions >= 3.6::\n\n        class Employee(NamedTuple):\n            name: str\n            id: int\n\n    This is equivalent to::\n\n        Employee = collections.namedtuple(\'Employee\', [\'name\', \'id\'])\n\n    The resulting class has an extra __annotations__ attribute, giving a\n    dict that maps field names to types.  (The field names are also in\n    the _fields attribute, which is part of the namedtuple API.)\n    Alternative equivalent keyword syntax is also accepted::\n\n        Employee = NamedTuple(\'Employee\', name=str, id=int)\n\n    In Python versions <= 3.5 use::\n\n        Employee = NamedTuple(\'Employee\', [(\'name\', str), (\'id\', int)])\n    """\n'),
    ('stdlib/typing.py', 2390, 2431, 'TypedDict', 'def TypedDict(typename, fields=None, /, *, total=True, **kwargs):\n    """A simple typed namespace. At runtime it is equivalent to a plain dict.\n\n    TypedDict creates a dictionary type that expects all of its\n    instances to have a certain set of keys, where each key is\n    associated with a value of a consistent type. This expectation\n    is not checked at runtime but is only enforced by type checkers.\n    Usage::\n\n        class Point2D(TypedDict):\n            x: int\n            y: int\n            label: str\n\n        a: Point2D = {\'x\': 1, \'y\': 2, \'label\': \'good\'}  # OK\n        b: Point2D = {\'z\': 3, \'label\': \'bad\'}           # Fails type check\n\n        assert Point2D(x=1, y=2, label=\'first\') == dict(x=1, y=2, label=\'first\')\n\n    The type info can be accessed via the Point2D.__annotations__ dict, and\n    the Point2D.__required_keys__ and Point2D.__optional_keys__ frozensets.\n    TypedDict supports two additional equivalent forms::\n\n        Point2D = TypedDict(\'Point2D\', x=int, y=int, label=str)\n        Point2D = TypedDict(\'Point2D\', {\'x\': int, \'y\': int, \'label\': str})\n\n    By default, all keys must be present in a TypedDict. It is possible\n    to override this by specifying totality.\n    Usage::\n\n        class point2D(TypedDict, total=False):\n            x: int\n            y: int\n\n    This means that a point2D TypedDict can have any of the keys omitted.A type\n    checker is only expected to support a literal False or True as the value of\n    the total argument. True is the default, and makes all items defined in the\n    class body be required.\n\n    The class syntax is only supported in Python 3.6+, while two other\n    syntax forms work for Python 2.7 and 3.2+\n    """\n'),
    ('stdlib/uu.py', 42, 43, 'encode', 'def encode(in_file, out_file, name=None, mode=None, *, backtick=False):\n    """Uuencode file"""\n'),
