    ('stdlib/warnings.py', 130, 141, 'filterwarnings', 'def filterwarnings(action, message="", category=Warning, module="", lineno=0,\n                   append=False):\n    """Insert an entry into the list of warnings filters (at the front).\n\n    \'action\' -- one of "error", "ignore", "always", "default", "module",\n                or "once"\n    \'message\' -- a regex that the warning message must match\n    \'category\' -- a class that the warning must be a subclass of\n    \'module\' -- a regex that the module name must match\n    \'lineno\' -- an integer line number, 0 matches all warnings\n    \'append\' -- if true, append to the list of filters\n    """\n'),
    ('stdlib/warnings.py', 165, 174, 'simplefilter', 'def simplefilter(action, category=Warning, lineno=0, append=False):\n    """Insert a simple entry into the list of warnings filters (at the front).\n\n    A simple filter matches all modules and messages.\n    \'action\' -- one of "error", "ignore", "always", "default", "module",\n                or "once"\n    \'category\' -- a class that the warning must be a subclass of\n    \'lineno\' -- an integer line number, 0 matches all warnings\n    \'append\' -- if true, append to the list of filters\n    """\n'),
