    ('stdlib/zipapp.py', 76, 95, 'create_archive', 'def create_archive(source, target=None, interpreter=None, main=None,\n                   filter=None, compressed=False):\n    """Create an application archive from SOURCE.\n\n    The SOURCE can be the name of a directory, or a filename or a file-like\n    object referring to an existing archive.\n\n    The content of SOURCE is packed into an application archive in TARGET,\n    which can be a filename or a file-like object.  If SOURCE is a directory,\n    TARGET can be omitted and will default to the name of SOURCE with .pyz\n    appended.\n\n    The created application archive will have a shebang line specifying\n    that it should run with INTERPRETER (there will be no shebang line if\n    INTERPRETER is None), and a __main__.py which runs MAIN (if MAIN is\n    not specified, an existing __main__.py will be used).  It is an error\n    to specify MAIN for anything other than a directory source with no\n    __main__.py, and it is an error to omit MAIN if the directory has no\n    __main__.py.\n    """\n'),
    ('stdlib/zipapp.py', 150, 150, 'get_interpreter', 'def get_interpreter(archive):\n'),
    ('stdlib/zipapp.py', 156, 162, 'main', 'def main(args=None):\n    """Run the zipapp command line interface.\n\n    The ARGS parameter lets you specify the argument list directly.\n    Omitting ARGS (or setting it to None) works as for argparse, using\n    sys.argv[1:] as the argument list.\n    """\n'),
